code:
name: Discussion Triage Helper

on:
  discussion:
    types: [created]

permissions:
  discussions: write

jobs:
  triage:
    runs-on: ubuntu-latest
    steps:
      - name: Add initial response to discussions
        uses: actions/github-script@v9
        with:
          script: |
            const { discussion } = context.payload;

            // Add helpful response based on discussion category
            let response = "";

            if (discussion.category.slug === "q-a") {
              if (discussion.title.toLowerCase().includes("bug") || 
                  discussion.title.toLowerCase().includes("error") || 
                  discussion.title.toLowerCase().includes("crash") ||
                  discussion.title.toLowerCase().includes("fail")) {

                response = "Thanks for the discussion! This looks like it might be a bug report.\n\n" +
                          "**For Maintainers:** If this is confirmed to be a bug with proper reproduction steps, consider converting to an issue using \"Convert to issue\" in the discussion menu.\n\n" +
                          "**For the Reporter:** To help us triage this effectively, please provide:\n" +
                          "- [ ] Katana version (`katana -version`)\n" +
                          "- [ ] Complete command that reproduces the issue\n" +
                          "- [ ] Expected vs actual behavior\n" +
                          "- [ ] Operating system and environment details\n" +
                          "- [ ] Any error messages or logs\n\n" +
                          "This helps us determine if this should become a tracked issue. Thank you!";

              } else {
                response = "Thanks for your question!\n\n" +
                          "The community and maintainers will help answer this. If this turns out to be a bug or feature request after discussion, a maintainer can convert it to a tracked issue.\n\n" +
                          "**Tip:** For faster responses, you can also join our [Discord server](https://discord.gg/projectdiscovery) for real-time help!";
              }
            }

            else if (discussion.category.slug === "ideas") {
              response = "Thanks for sharing this idea!\n\n" +
                        "**For Maintainers:** If this feature request is well-defined and approved for implementation, consider converting to an issue using \"Convert to issue\" in the discussion menu.\n\n" +
                        "**For the Reporter:** To help evaluate this feature:\n" +
                        "- [ ] Describe the specific use case this would solve\n" +
                        "- [ ] Explain how this would benefit the katana user community\n" +  
                        "- [ ] Consider if this could be implemented as a plugin or external tool\n" +
                        "- [ ] Check if similar functionality already exists\n\n" +
                        "Well-defined features with clear benefits may be converted to tracked issues for implementation. Thanks for contributing!";
            }

            if (response) {
              await github.rest.discussions.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                discussion_number: discussion.number,
                body: response
              });
            }

      - name: Auto-label potential bug reports
        uses: actions/github-script@v9
        with:
          script: |
            const { discussion } = context.payload;
            const title = discussion.title.toLowerCase();
            const body = discussion.body.toLowerCase();

            // Check for keywords that suggest this might be a bug
            const bugKeywords = [
              "bug", "error", "crash", "fail", "broken", "issue", "problem", 
              "exception", "panic", "segfault", "hang", "freeze", "incorrect"
            ];

            const hasBugKeywords = bugKeywords.some(keyword => 
              title.includes(keyword) || body.includes(keyword)
            );

            if (hasBugKeywords && discussion.category.slug === "q-a") {
              // Add a comment suggesting this might need to be converted to an issue
              const detectedKeywords = bugKeywords.filter(k => title.includes(k) || body.includes(k));
              await github.rest.discussions.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,  
                discussion_number: discussion.number,
                body: "**Maintainer Note:** This discussion contains potential bug keywords and may need to be converted to a tracked issue after confirmation.\n\n" +
                      "**Keywords detected:** " + detectedKeywords.join(', ')
              });
            }

name: Workflow Monitor

on:
  schedule:
    # Run weekly on Mondays at 9 AM UTC
    - cron: '0 9 * * 1'
  workflow_dispatch: # Allow manual triggering

permissions:
  issues: read
  discussions: read

jobs:
  monitor-workflow:
    runs-on: ubuntu-latest
    steps:
      - name: Check Discussion vs Issue Activity
        uses: actions/github-script@v9
        with:
          script: |
            const oneWeekAgo = new Date();
            oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
            const since = oneWeekAgo.toISOString();

            // Get discussions created in the last week
            const discussions = await github.graphql(`
              query($owner: String!, $repo: String!, $since: DateTime!) {
                repository(owner: $owner, name: $repo) {
                  discussions(first: 100, orderBy: {field: CREATED_AT, direction: DESC}) {
                    nodes {
                      title
                      createdAt
                      category {
                        name
                        slug
                      }
                      comments(first: 1) {
                        totalCount
                      }
                    }
                  }
                }
              }
            `, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              since: since
            });

            // Get issues created in the last week
            const issues = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              since: since,
              state: 'all'
            });

            // Filter discussions created in the last week
            const recentDiscussions = discussions.repository.discussions.nodes.filter(
              d => new Date(d.createdAt) >= oneWeekAgo
            );

            // Generate and log simple report
            console.log("=== Discussion-First Workflow Report ===");
            console.log(`Period: ${oneWeekAgo.toDateString()} - ${new Date().toDateString()}`);
            console.log(`Discussions Created: ${recentDiscussions.length}`);
            console.log(`Issues Created: ${issues.data.length}`);
            console.log(`Conversion Ratio: ${issues.data.length}/${recentDiscussions.length}`);

            if (recentDiscussions.length > 0) {
              console.log("\nDiscussion Categories:");
              recentDiscussions.forEach(d => {
                console.log(`- ${d.category.name}: ${d.title} (${d.comments.totalCount} comments)`);
              });
            } else {
              console.log("No discussions this week");
            }

            if (issues.data.length > 0) {
              console.log("\nDirect Issues Created:");
              issues.data.forEach(i => {
                console.log(`- ${i.title} (${new Date(i.created_at).toDateString()})`);
              });
              console.log("\nWARNING: Direct issues were created - check workflow configuration");
            } else {
              console.log("\nNo direct issues created - workflow working correctly");
            }

            const responseRate = recentDiscussions.length > 0 ? 
              (recentDiscussions.filter(d => d.comments.totalCount > 0).length / recentDiscussions.length * 100).toFixed(1) : 0;
            console.log(`Community Response Rate: ${responseRate}%`);

            // You could also create an issue or discussion with this report
            // For now, just log it to Actions output

package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"

	"github.com/logrusorgru/aurora"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/katana/internal/testutils"
	"github.com/projectdiscovery/katana/internal/testutils/authlab"
)

var (
	debug           = os.Getenv("DEBUG") == "true"
	success         = aurora.Green("[✓]").String()
	failed          = aurora.Red("[✘]").String()
	errored         = false
	devKatanaBinary = flag.String("dev", "", "Dev Branch Katana Binary")
)

func main() {
	flag.Parse()
	if err := runFunctionalTests(); err != nil {
		log.Fatalf("Could not run functional tests: %s\n", err)
	}
	if errored {
		os.Exit(1)
	}
}

func runFunctionalTests() error {
	server, err := testutils.NewTestServer()
	if err != nil {
		return fmt.Errorf("could not start test server: %w", err)
	}
	defer func() {
		_ = server.Close()
	}()

	fmt.Printf("Test server started at %s\n", server.URL)

	for _, testcase := range testutils.TestCases {
		if testcase.Target == "" {
			testcase.Target = server.URL
		}
		if err := runIndividualTestCase(testcase); err != nil {
			errored = true
			fmt.Fprintf(os.Stderr, "%s Test \"%s\" failed: %s\n", failed, testcase.Name, err)
		} else {
			fmt.Printf("%s Test \"%s\" passed!\n", success, testcase.Name)
		}
	}

	if err := runAuthLabFunctionalTests(); err != nil {
		return err
	}
	return nil
}

func runAuthLabFunctionalTests() error {
	lab, err := authlab.Start()
	if err != nil {
		return fmt.Errorf("could not start auth lab: %w", err)
	}
	defer func() { _ = lab.Close() }()

	fmt.Printf("Auth lab started at %s\n", lab.URL)

	dir, err := os.MkdirTemp("", "katana-rf-*")
	if err != nil {
		return err
	}
	defer func() { _ = os.RemoveAll(dir) }()

	simpleFlow := filepath.Join(dir, "simple.json")
	if err := os.WriteFile(simpleFlow, []byte(authlab.ChromeRecordingSimple(lab.URL)), 0o600); err != nil {
		return err
	}
	explicitFlow := filepath.Join(dir, "explicit.json")
	if err := os.WriteFile(explicitFlow, []byte(authlab.ExplicitStepsSimple(lab.URL)), 0o600); err != nil {
		return err
	}

	cases := testutils.AuthTestCases(lab.URL, simpleFlow)
	// Second case reuses the same CompareFunc shape but should run the explicit steps file.
	if len(cases) >= 2 {
		cases[1].Args = strings.Replace(cases[1].Args, simpleFlow, explicitFlow, 1)
	}

	for _, testcase := range cases {
		if err := runIndividualTestCase(testcase); err != nil {
			errored = true
			fmt.Fprintf(os.Stderr, "%s Test \"%s\" failed: %s\n", failed, testcase.Name, err)
		} else {
			fmt.Printf("%s Test \"%s\" passed!\n", success, testcase.Name)
		}
	}
	return nil
}

func runIndividualTestCase(testcase testutils.TestCase) error {
	argsParts := strings.Fields(testcase.Args)
	devOutput, err := testutils.RunKatanaBinaryAndGetResults(testcase.Target, *devKatanaBinary, debug, argsParts)
	if err != nil {
		return errors.Wrap(err, "could not run Katana dev test")
	}
	if testcase.CompareFunc != nil {
		return testcase.CompareFunc(testcase.Target, devOutput)
	}
	if !testutils.CompareOutput(devOutput, testcase.Expected) {
		return errors.Errorf("expected output %s, got %s", testcase.Expected, devOutput)
	}
	return nil
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"strings"
	"sync/atomic"

	"github.com/projectdiscovery/katana/internal/runner"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
)

var filtersTestcases = map[string]TestCase{
	"match condition":  &matchConditionIntegrationTest{},
	"filter condition": &filterConditionIntegrationTest{},
	"unique filter":    &uniqueFilterIntegrationTest{},
}

type matchConditionIntegrationTest struct{}

// Execute executes a test case and returns an error if occurred
// Execute the docs at ../README.md if the code stops working for integration.
func (h *matchConditionIntegrationTest) Execute() error {
	results, _ := RunKatanaAndGetResults(false,
		"-u", "scanme.sh",
		"-match-condition", "status_code == 200 && contains(body, 'ok')",
	)

	if len(results) != 1 {
		return fmt.Errorf("match condition failed")
	}
	return nil
}

type filterConditionIntegrationTest struct{}

// Execute executes a test case and returns an error if occurred
func (h *filterConditionIntegrationTest) Execute() error {
	results, _ := RunKatanaAndGetResults(false,
		"-u", "scanme.sh",
		"-filter-condition", "status_code == 200 && contains(body, 'ok')",
	)

	if len(results) != 0 {
		return fmt.Errorf("filter condition failed")
	}
	return nil
}

type uniqueFilterIntegrationTest struct{}

func (h *uniqueFilterIntegrationTest) Execute() error {
	// Create a test server that returns 404 for all paths except root
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/" {
			w.WriteHeader(http.StatusOK)
			_, _ = fmt.Fprint(w, `<html><body>
				<a href="/page1">Page 1</a>
				<a href="/page2">Page 2</a>
				<a href="/page3">Page 3</a>
				<a href="/page4">Page 4</a>
			</body></html>`)
		} else {
			w.WriteHeader(http.StatusNotFound)
			// Return identical 404 content for all missing pages
			_, _ = fmt.Fprint(w, `<html><body><h1>404 - Page Not Found</h1></body></html>`)
		}
	}))
	defer server.Close()

	options := types.DefaultOptions
	options.URLs = []string{server.URL}
	options.MaxDepth = 2
	options.Concurrency = 1
	options.DisableUniqueFilter = true

	var fourOhFourCount atomic.Int32
	options.OnResult = func(result output.Result) {
		if result.Response.StatusCode == http.StatusNotFound {
			fourOhFourCount.Add(1)
		}
	}

	katanaRunner, err := runner.New(&options)
	if err != nil {
		return fmt.Errorf("could not create runner: %v", err)
	}
	defer func() {
		_ = katanaRunner.Close()
	}()

	if err := katanaRunner.ExecuteCrawling(); err != nil {
		return fmt.Errorf("could not execute crawling: %v", err)
	}

	if fourOhFourCount.Load() != 4 {
		return fmt.Errorf("expected 4 404 responses, got %d", fourOhFourCount.Load())
	}

	return nil
}

// ExtraArgs
var ExtraDebugArgs = []string{}

func RunKatanaAndGetResults(debug bool, extra ...string) ([]string, error) {
	cmd := exec.Command("./katana")
	extra = append(extra, ExtraDebugArgs...)
	cmd.Args = append(cmd.Args, extra...)
	cmd.Args = append(cmd.Args, "-duc") // disable auto updates
	if debug {
		cmd.Args = append(cmd.Args, "-debug")
		cmd.Stderr = os.Stderr
		fmt.Println(cmd.String())
	} else {
		cmd.Args = append(cmd.Args, "-silent")
	}
	data, err := cmd.Output()
	if debug {
		fmt.Println(string(data))
	}
	if len(data) < 1 && err != nil {
		return nil, fmt.Errorf("%v: %v", err.Error(), string(data))
	}
	var parts []string
	items := strings.Split(string(data), "\n")
	for _, i := range items {
		if i != "" {
			parts = append(parts, i)
		}
	}
	return parts, nil
}

package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/logrusorgru/aurora"
)

type TestCase interface {
	// Execute executes a test case and returns any errors if occurred
	Execute() error
}

var (
	debug      = os.Getenv("DEBUG") == "true"
	customTest = os.Getenv("TEST")

	errored = false
	success = aurora.Green("[✓]").String()
	failed  = aurora.Red("[✘]").String()

	tests = map[string]map[string]TestCase{
		"code":    libraryTestcases,
		"filters": filtersTestcases,
	}
)

func main() {
	for name, tests := range tests {
		fmt.Printf("Running test cases for \"%s\"\n", aurora.Blue(name))
		if customTest != "" && !strings.Contains(name, customTest) {
			continue // only run tests user asked
		}
		for name, test := range tests {
			err := test.Execute()
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s Test \"%s\" failed: %s\n", failed, name, err)
				errored = true
			} else {
				fmt.Printf("%s Test \"%s\" passed!\n", success, name)
			}
		}
	}
	if errored {
		os.Exit(1)
	}
}

package main

import (
	"fmt"
	"math"

	"github.com/projectdiscovery/katana/pkg/engine/standard"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/katana/pkg/utils/queue"
)

var libraryTestcases = map[string]TestCase{
	"katana as library": &goIntegrationTest{},
}

type goIntegrationTest struct{}

// Execute executes a test case and returns an error if occurred
// Execute the docs at ../README.md if the code stops working for integration.
func (h *goIntegrationTest) Execute() error {
	var crawledURLs []string

	options := &types.Options{
		MaxDepth:     1,
		FieldScope:   "rdn",
		BodyReadSize: math.MaxInt,
		RateLimit:    150,
		Verbose:      debug,
		Strategy:     queue.DepthFirst.String(),
		OnResult: func(r output.Result) {
			crawledURLs = append(crawledURLs, r.Request.URL)
		},
	}
	crawlerOptions, err := types.NewCrawlerOptions(options)
	if err != nil {
		return err
	}
	defer func() {
		if err := crawlerOptions.Close(); err != nil {
			fmt.Printf("Error closing crawler options: %v\n", err)
		}
	}()
	crawler, err := standard.New(crawlerOptions)
	if err != nil {
		return err
	}
	defer func() {
		if err := crawler.Close(); err != nil {
			fmt.Printf("Error closing crawler: %v\n", err)
		}
	}()
	var input = "https://public-firing-range.appspot.com"
	err = crawler.Crawl(input)
	if err != nil {
		return err
	}
	if len(crawledURLs) == 0 {
		return fmt.Errorf("no URLs crawled")
	}
	return nil
}

#!/bin/sh
# Resets DVWA, logs in, and prints the session cookie as a request header for katana.
set -eu
base=${DVWA_URL:-http://127.0.0.1:4280}
jar=$(mktemp)
trap 'rm -f "$jar"' EXIT

docker compose -f "$(dirname "$0")/compose.yml" up -d --wait --force-recreate dvwa db >/dev/null

token() { curl -fsS -b "$jar" -c "$jar" "$base/$1" | sed -n "s/.*name='user_token' value='\([0-9a-f]*\)'.*/\1/p"; }

curl -fsS -b "$jar" -c "$jar" -o /dev/null --data "create_db=Create+%2F+Reset+Database&user_token=$(token setup.php)" "$base/setup.php"
curl -fsS -b "$jar" -c "$jar" -o /dev/null --data "username=admin&password=password&Login=Login&user_token=$(token login.php)" "$base/login.php"

session=$(awk '$6 == "PHPSESSID" {print $7}' "$jar")
curl -fsS -b "PHPSESSID=$session; security=low" "$base/index.php" | grep -q 'logout.php' || { echo "dvwa login failed" >&2; exit 1; }
echo "Cookie: PHPSESSID=$session; security=low"

// crawl-bench measures crawl coverage on real apps from the server side.
//
// Each target sits behind a recording reverse proxy, katana crawls the proxy,
// and the requests the app received are summarized into metrics. Results can be
// compared to a baseline from another build or flag set.
//
//	docker compose up -d --wait
//	go run . -katana ../../../katana -out new.json -baseline old.json
package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"sort"
	"strings"
	"text/tabwriter"
	"time"

	"gopkg.in/yaml.v3"
)

type target struct {
	Name string `yaml:"name"`
	URL  string `yaml:"url"`
	// Prepare resets the target before every crawl; each line it prints is passed to katana as a -H header.
	Prepare string   `yaml:"prepare"`
	Args    []string `yaml:"args"`
}

type config struct {
	Targets []target `yaml:"targets"`
	// Runs maps a run name to katana flags, e.g. a standard and a headless crawl.
	Runs map[string][]string `yaml:"runs"`
}

// results maps target, then run name, to median metrics.
type results map[string]map[string]Metrics

func main() {
	configPath := flag.String("config", "bench.yaml", "benchmark config")
	katana := flag.String("katana", "katana", "katana binary to measure")
	repeat := flag.Int("repeat", 3, "crawls per target and run; the median is reported")
	only := flag.String("run", "", "comma separated run names to execute (default all)")
	out := flag.String("out", "", "write results as json")
	baseline := flag.String("baseline", "", "results json to compare against")
	flag.Parse()
	if err := validateRepeat(*repeat); err != nil {
		fatal(err)
	}

	cfg, err := loadConfig(*configPath)
	if err != nil {
		fatal(err)
	}
	runs := selectRuns(cfg.Runs, *only)

	res := results{}
	for _, t := range cfg.Targets {
		res[t.Name] = map[string]Metrics{}
		for _, name := range sortedKeys(runs) {
			var samples []Metrics
			for i := 0; i < *repeat; i++ {
				m, err := crawl(*katana, t, runs[name])
				if err != nil {
					fatal(fmt.Errorf("%s/%s: %w", t.Name, name, err))
				}
				fmt.Fprintf(os.Stderr, "%s/%s #%d: %+v\n", t.Name, name, i+1, m)
				samples = append(samples, m)
			}
			res[t.Name][name] = median(samples)
		}
	}

	if *out != "" {
		data, _ := json.MarshalIndent(res, "", "  ")
		if err := os.WriteFile(*out, append(data, '\n'), 0o644); err != nil {
			fatal(err)
		}
	}
	var base results
	if *baseline != "" {
		data, err := os.ReadFile(*baseline)
		if err != nil {
			fatal(err)
		}
		if err := json.Unmarshal(data, &base); err != nil {
			fatal(err)
		}
	}
	report(res, base)
}

func crawl(katana string, t target, runArgs []string) (Metrics, error) {
	headers, err := prepare(t.Prepare)
	if err != nil {
		return Metrics{}, fmt.Errorf("prepare: %w", err)
	}
	upstream, err := url.Parse(t.URL)
	if err != nil {
		return Metrics{}, err
	}

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return Metrics{}, err
	}
	rec := newRecorder(upstream)
	if err := rec.calibrate(); err != nil {
		return Metrics{}, fmt.Errorf("calibrate: %w", err)
	}
	srv := &http.Server{Handler: rec, ReadHeaderTimeout: 10 * time.Second}
	go func() { _ = srv.Serve(ln) }()
	defer func() { _ = srv.Shutdown(context.Background()) }()

	args := []string{"-u", "http://" + ln.Addr().String() + "/", "-silent", "-disable-update-check"}
	for _, h := range headers {
		args = append(args, "-H", h)
	}
	args = append(append(args, runArgs...), t.Args...)

	cmd := exec.Command(katana, args...)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	start := time.Now()
	if err := cmd.Run(); err != nil {
		return Metrics{}, fmt.Errorf("katana %s: %w: %s", strings.Join(args, " "), err, stderr.String())
	}
	return computeMetrics(rec.snapshot(), time.Since(start).Seconds()), nil
}

func prepare(command string) ([]string, error) {
	if command == "" {
		return nil, nil
	}
	cmd := exec.Command("sh", "-c", command)
	cmd.Stderr = os.Stderr
	output, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	var headers []string
	scanner := bufio.NewScanner(bytes.NewReader(output))
	for scanner.Scan() {
		if line := strings.TrimSpace(scanner.Text()); line != "" {
			headers = append(headers, line)
		}
	}
	return headers, nil
}

func report(res, base results) {
	w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	_, _ = fmt.Fprintln(w, "target\trun\t"+strings.Join(metricNames, "\t"))
	for _, tname := range sortedKeys(res) {
		for _, rname := range sortedKeys(res[tname]) {
			cur := res[tname][rname].fields()
			cells := make([]string, len(cur))
			old, ok := base[tname][rname]
			for i, v := range cur {
				cells[i] = trim(v)
				if ok {
					cells[i] += " (" + delta(old.fields()[i], v) + ")"
				}
			}
			_, _ = fmt.Fprintf(w, "%s\t%s\t%s\n", tname, rname, strings.Join(cells, "\t"))
		}
	}
	_ = w.Flush()
}

func trim(v float64) string {
	if v == float64(int(v)) {
		return fmt.Sprint(int(v))
	}
	return fmt.Sprintf("%.1f", v)
}

func validateRepeat(n int) error {
	if n < 1 {
		return fmt.Errorf("-repeat must be at least 1")
	}
	return nil
}

func loadConfig(path string) (*config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var cfg config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, err
	}
	if len(cfg.Targets) == 0 || len(cfg.Runs) == 0 {
		return nil, fmt.Errorf("%s needs at least one target and one run", path)
	}
	return &cfg, nil
}

func selectRuns(all map[string][]string, only string) map[string][]string {
	if only == "" {
		return all
	}
	selected := map[string][]string{}
	for _, name := range strings.Split(only, ",") {
		args, ok := all[name]
		if !ok {
			fatal(fmt.Errorf("unknown run %q", name))
		}
		selected[name] = args
	}
	return selected
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, err)
	os.Exit(1)
}

package main

import (
	"fmt"
	"net/http"
	"sort"
	"strings"

	"github.com/projectdiscovery/katana/pkg/utils"
)

// Metrics summarizes what one crawl made the target server do.
type Metrics struct {
	// Routes is distinct method and path, with ids normalized, that the server did not 404.
	Routes int `json:"routes"`
	// Params is distinct route and parameter name pairs from query strings and bodies.
	Params int `json:"params"`
	// Forms is distinct route and parameter sets sent in a request body.
	Forms int `json:"forms"`
	// Requests is every request the server received, duplicates included.
	Requests int `json:"requests"`
	// Errors is responses with a 5xx status.
	Errors  int     `json:"errors"`
	Seconds float64 `json:"seconds"`
}

func computeMetrics(hits []hit, seconds float64) Metrics {
	routes := map[string]struct{}{}
	params := map[string]struct{}{}
	forms := map[string]struct{}{}
	m := Metrics{Requests: len(hits), Seconds: seconds}

	for _, h := range hits {
		if h.Status >= http.StatusInternalServerError {
			m.Errors++
		}
		if h.Status == http.StatusNotFound || h.Status == statusClientClosed {
			continue
		}
		route := h.Method + " " + utils.FingerprintURL(h.Path, nil)
		routes[route] = struct{}{}
		for _, p := range h.Params {
			params[route+" "+p] = struct{}{}
		}
		if h.Body {
			names := append([]string(nil), h.BodyParams...)
			sort.Strings(names)
			forms[route+" "+strings.Join(names, ",")] = struct{}{}
		}
	}
	m.Routes, m.Params, m.Forms = len(routes), len(params), len(forms)
	return m
}

// median takes the per field median, so one unlucky run does not decide a comparison.
func median(runs []Metrics) Metrics {
	pick := func(get func(Metrics) float64) float64 {
		values := make([]float64, len(runs))
		for i, r := range runs {
			values[i] = get(r)
		}
		sort.Float64s(values)
		return values[len(values)/2]
	}
	return Metrics{
		Routes:   int(pick(func(m Metrics) float64 { return float64(m.Routes) })),
		Params:   int(pick(func(m Metrics) float64 { return float64(m.Params) })),
		Forms:    int(pick(func(m Metrics) float64 { return float64(m.Forms) })),
		Requests: int(pick(func(m Metrics) float64 { return float64(m.Requests) })),
		Errors:   int(pick(func(m Metrics) float64 { return float64(m.Errors) })),
		Seconds:  pick(func(m Metrics) float64 { return m.Seconds }),
	}
}

func (m Metrics) fields() []float64 {
	return []float64{float64(m.Routes), float64(m.Params), float64(m.Forms), float64(m.Requests), float64(m.Errors), m.Seconds}
}

var metricNames = []string{"routes", "params", "forms", "requests", "errors", "seconds"}

func delta(base, cur float64) string {
	if base == 0 {
		if cur == 0 {
			return "="
		}
		return "new"
	}
	pct := (cur - base) / base * 100
	if pct > -0.5 && pct < 0.5 {
		return "="
	}
	return fmt.Sprintf("%+.0f%%", pct)
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"mime"
	"mime/multipart"
	"net/http"
	"net/http/httputil"
	"net/url"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// maxBodyCapture bounds how much of a request body is read to learn its parameter names.
const maxBodyCapture = 1 << 20

// hit is one request as the target server received it.
type hit struct {
	Method string
	Path   string
	Params []string
	// BodyParams are the parameter names from the request body. Query names stay in Params.
	BodyParams []string
	Body       bool
	Status     int
}

// recorder is a reverse proxy in front of a target that records every request,
// so coverage is measured from the server side rather than from katana's output.
type recorder struct {
	target *url.URL
	proxy  *httputil.ReverseProxy
	// fallback is the page the app serves for paths it does not have, if it answers them with 200.
	fallback     []byte
	fallbackETag string
	mu           sync.Mutex
	hits         []hit
}

func newRecorder(target *url.URL) *recorder {
	r := &recorder{target: target}
	r.proxy = &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)
			// keep the proxy host so absolute links and redirects the app builds point back through the proxy
			pr.Out.Host = pr.In.Host
			// the transport then negotiates and decodes compression itself, so bodies compare byte for byte
			pr.Out.Header.Del("Accept-Encoding")
		},
		// recorded here rather than after ServeHTTP, which for a websocket returns only when the socket closes
		ModifyResponse: func(resp *http.Response) error {
			rewriteSameOriginRedirect(resp, target)
			status := resp.StatusCode
			if r.isFallback(resp) {
				// a single page app serving its shell for an unknown path is a 404 in all but status
				status = http.StatusNotFound
			}
			r.record(resp.Request, status)
			return nil
		},
		ErrorHandler: func(w http.ResponseWriter, req *http.Request, err error) {
			status := http.StatusBadGateway
			if errors.Is(err, context.Canceled) {
				// katana gave up on the request, which says nothing about the server
				status = statusClientClosed
			}
			r.record(req, status)
			w.WriteHeader(status)
		},
	}
	return r
}

// rewriteSameOriginRedirect turns an absolute redirect back to the target into a
// relative one, so katana follows it through the recorder instead of the upstream.
func rewriteSameOriginRedirect(resp *http.Response, target *url.URL) {
	loc := resp.Header.Get("Location")
	if loc == "" {
		return
	}
	redirect, err := url.Parse(loc)
	if err != nil || !redirect.IsAbs() || redirect.Scheme != target.Scheme || redirect.Host != target.Host {
		return
	}
	if redirect.Path == "" {
		redirect.Path = "/"
	}
	redirect.Scheme = ""
	redirect.Host = ""
	redirect.User = nil
	resp.Header.Set("Location", redirect.String())
}

// calibrate learns the app's fallback page by requesting a path that cannot exist.
func (r *recorder) calibrate() error {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, r.target.JoinPath("crawl-bench-"+strconv.FormatInt(time.Now().UnixNano(), 36)).String(), nil)
	if err != nil {
		return err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return nil
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBodyCapture))
	if err != nil {
		return err
	}
	r.fallback = body
	r.fallbackETag = resp.Header.Get("ETag")
	return nil
}

func (r *recorder) isFallback(resp *http.Response) bool {
	if len(r.fallback) == 0 {
		return false
	}
	if resp.StatusCode == http.StatusNotModified {
		// a browser revalidating the fallback it already got
		return r.fallbackETag != "" && resp.Header.Get("ETag") == r.fallbackETag
	}
	if resp.StatusCode != http.StatusOK {
		return false
	}
	if resp.ContentLength >= 0 && resp.ContentLength != int64(len(r.fallback)) {
		return false
	}
	// read one byte past the fallback size so a longer body never matches
	head, _ := io.ReadAll(io.LimitReader(resp.Body, int64(len(r.fallback))+1))
	resp.Body = struct {
		io.Reader
		io.Closer
	}{io.MultiReader(bytes.NewReader(head), resp.Body), resp.Body}
	return bytes.Equal(head, r.fallback)
}

// statusClientClosed follows nginx's convention for a client that left before the response.
const statusClientClosed = 499

type hitKey struct{}

func (r *recorder) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	h := &hit{Method: req.Method, Path: req.URL.Path, Params: queryKeys(req.URL.Query())}
	if req.Body != nil && req.ContentLength != 0 {
		body, _ := io.ReadAll(io.LimitReader(req.Body, maxBodyCapture))
		req.Body = io.NopCloser(io.MultiReader(bytes.NewReader(body), req.Body))
		if len(body) > 0 {
			h.Body = true
			h.BodyParams = bodyKeys(req.Header.Get("Content-Type"), body)
			h.Params = append(h.Params, h.BodyParams...)
		}
	}
	r.proxy.ServeHTTP(w, req.WithContext(context.WithValue(req.Context(), hitKey{}, h)))
}

func (r *recorder) record(req *http.Request, status int) {
	h, ok := req.Context().Value(hitKey{}).(*hit)
	if !ok {
		return
	}
	h.Status = status
	r.mu.Lock()
	r.hits = append(r.hits, *h)
	r.mu.Unlock()
}

func (r *recorder) snapshot() []hit {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]hit(nil), r.hits...)
}

func queryKeys(values url.Values) []string {
	keys := make([]string, 0, len(values))
	for k := range values {
		keys = append(keys, k)
	}
	return keys
}

func bodyKeys(contentType string, body []byte) []string {
	switch {
	case strings.Contains(contentType, "json"):
		var obj map[string]json.RawMessage
		if json.Unmarshal(body, &obj) != nil {
			return nil
		}
		keys := make([]string, 0, len(obj))
		for k := range obj {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		return keys
	case strings.Contains(contentType, "multipart/form-data"):
		_, params, err := mime.ParseMediaType(contentType)
		if err != nil {
			return nil
		}
		var keys []string
		mr := multipart.NewReader(bytes.NewReader(body), params["boundary"])
		for {
			part, err := mr.NextPart()
			if err != nil {
				return keys
			}
			keys = append(keys, part.FormName())
		}
	default:
		values, err := url.ParseQuery(string(body))
		if err != nil {
			return nil
		}
		return queryKeys(values)
	}
}

