func DoHealthCheck(options *types.Options, flagSet *goflags.FlagSet) string {
	// RW permissions on config file
	cfgFilePath, _ := flagSet.GetConfigFilePath()
	var test strings.Builder
	_, _ = fmt.Fprintf(&test, "Version: %s\n", version)
	_, _ = fmt.Fprintf(&test, "Operative System: %s\n", runtime.GOOS)
	_, _ = fmt.Fprintf(&test, "Architecture: %s\n", runtime.GOARCH)
	_, _ = fmt.Fprintf(&test, "Go Version: %s\n", runtime.Version())
	_, _ = fmt.Fprintf(&test, "Compiler: %s\n", runtime.Compiler)

	var testResult string
	if permissionutil.IsRoot {
		testResult = "Ok"
	} else {
		testResult = "Ko"
	}
	_, _ = fmt.Fprintf(&test, "root: %s\n", testResult)

	ok, err := fileutil.IsReadable(cfgFilePath)
	if ok {
		testResult = "Ok"
	} else {
		testResult = "Ko"
	}
	if err != nil {
		testResult += fmt.Sprintf(" (%s)", err)
	}
	_, _ = fmt.Fprintf(&test, "Config file \"%s\" Read => %s\n", cfgFilePath, testResult)
	ok, err = fileutil.IsWriteable(cfgFilePath)
	if ok {
		testResult = "Ok"
	} else {
		testResult = "Ko"
	}
	if err != nil {
		testResult += fmt.Sprintf(" (%s)", err)
	}
	_, _ = fmt.Fprintf(&test, "Config file \"%s\" Write => %s\n", cfgFilePath, testResult)
	c4, err := net.Dial("tcp4", "scanme.sh:80")
	if err == nil && c4 != nil {
		_ = c4.Close()
	}
	testResult = "Ok"
	if err != nil {
		testResult = fmt.Sprintf("Ko (%s)", err)
	}
	_, _ = fmt.Fprintf(&test, "TCP IPv4 connectivity to scanme.sh:80 => %s\n", testResult)
	c6, err := net.Dial("tcp6", "scanme.sh:80")
	if err == nil && c6 != nil {
		_ = c6.Close()
	}
	testResult = "Ok"
	if err != nil {
		testResult = fmt.Sprintf("Ko (%s)", err)
	}
	_, _ = fmt.Fprintf(&test, "TCP IPv6 connectivity to scanme.sh:80 => %s\n", testResult)
	u4, err := net.Dial("udp4", "scanme.sh:53")
	if err == nil && u4 != nil {
		_ = u4.Close()
	}
	testResult = "Ok"
	if err != nil {
		testResult = fmt.Sprintf("Ko (%s)", err)
	}
	_, _ = fmt.Fprintf(&test, "UDP IPv4 connectivity to scanme.sh:80 => %s\n", testResult)
	u6, err := net.Dial("udp6", "scanme.sh:80")
	if err == nil && u6 != nil {
		_ = u6.Close()
	}
	testResult = "Ok"
	if err != nil {
		testResult = fmt.Sprintf("Ko (%s)", err)
	}
	_, _ = fmt.Fprintf(&test, "UDP IPv6 connectivity to scanme.sh:80 => %s\n", testResult)

	// attempt to identify if chome is installed locally
	if chromePath, err := exec.LookPath("chrome"); err == nil {
		_, _ = fmt.Fprintf(&test, "Potential chrome binary path (linux/osx) => %s\n", chromePath)
	}
	if chromePath, err := exec.LookPath("chrome.exe"); err == nil {
		_, _ = fmt.Fprintf(&test, "Potential chrome.exe binary path (windows) => %s\n", chromePath)
	}

	return test.String()
}

package runner

import (
	"bufio"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/gologger/formatter"
	"github.com/projectdiscovery/katana/pkg/engine/headless/auth"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/katana/pkg/utils"
	"github.com/projectdiscovery/utils/errkit"
	fileutil "github.com/projectdiscovery/utils/file"
	"gopkg.in/yaml.v3"
)

// validateOptions validates the provided options for crawler
func validateOptions(options *types.Options) error {
	if options.Interactive {
		if options.HeadlessHybrid {
			return errkit.New("interactive mode requires pure headless mode; -hh is not supported")
		}
		options.Headless = true
		if options.InteractionDepth < 1 || options.InteractionMaxStates < 0 || options.InteractionMaxActions < 0 || options.InteractionSettle < 0 || options.InteractionDuration < 0 {
			return errkit.New("invalid interactive limits: depth must be positive and other limits non-negative")
		}
	}
	if options.MaxDepth <= 0 && options.CrawlDuration.Seconds() <= 0 {
		return errkit.New("either max-depth or crawl-duration must be specified")
	}
	if len(options.URLs) == 0 && !fileutil.HasStdin() {
		return errkit.New("no inputs specified for crawler")
	}

	// Validate page load strategy
	if options.PageLoadStrategy != "" {
		validStrategies := []string{"heuristic", "load", "domcontentloaded", "networkidle", "none"}
		if !slices.Contains(validStrategies, options.PageLoadStrategy) {
			return errkit.New("invalid page-load-strategy: must be one of (heuristic, load, domcontentloaded, networkidle, none)")
		}
	} else {
		// Default to heuristic
		options.PageLoadStrategy = "heuristic"
	}

	// Disabling automatic form fill (-aff) for headless navigation due to incorrect implementation.
	// Form filling should be handled via headless actions within the page context
	if options.HeadlessHybrid && options.AutomaticFormFill {
		options.AutomaticFormFill = false
		gologger.Info().Msgf("Automatic form fill (-aff) has been disabled for headless navigation.")
	}

	// Disallow ambiguous engine selection
	if options.Headless && options.HeadlessHybrid {
		return errkit.New("flags -hl (headless) and -hh (hybrid) are mutually exclusive")
	}
	if err := options.ValidateAIProvider(); err != nil {
		return err
	}
	if options.AIProvider != "jev" && options.AIURL != "" && options.AIModel == "" {
		return errkit.New("-ai-url requires -ai-model")
	}
	if options.AIReplay != "" && (options.AILive() || options.AIRecord != "") {
		return errkit.New("-ai-replay cannot be combined with a live provider or -ai-record")
	}
	if options.AIRecord != "" && !options.AILive() {
		return errkit.New("-ai-record requires -ai-url or -ai-provider jev")
	}
	if options.MaxScrollSteps < 0 {
		return errkit.New("max-scroll-steps cannot be negative")
	}

	// Warn if -headless or -hh is used with -cwu (Chrome WebSocket URL)
	// The ChromeWSUrl takes precedence and pure headless engine will be used
	if options.Headless && options.ChromeWSUrl != "" {
		gologger.Warning().Msgf("Using -cwu with existing browser session. The -headless flag is redundant.")
		gologger.Info().Msgf("Connecting to Chrome at: %s", options.ChromeWSUrl)
	} else if options.HeadlessHybrid && options.ChromeWSUrl != "" {
		gologger.Warning().Msgf("Using -cwu forces pure headless engine. The -hh (hybrid) flag will be ignored.")
		gologger.Info().Msgf("Connecting to Chrome at: %s (using pure headless engine)", options.ChromeWSUrl)
	} else if options.ChromeWSUrl != "" {
		gologger.Info().Msgf("Connecting to Chrome at: %s (using pure headless engine)", options.ChromeWSUrl)
	}

	if options.AuthCredentials != "" {
		if !strings.Contains(options.AuthCredentials, ":") {
			return errkit.New("auth credentials must be in username:password format")
		}
		if !options.Headless && !options.HeadlessHybrid {
			options.Headless = true
			gologger.Info().Msgf("Headless mode enabled automatically for authenticated crawling.")
		}
	}

	if options.RecordedFlow != "" {
		if !fileutil.FileExists(options.RecordedFlow) {
			return errkit.New("recorded flow file does not exist")
		}
		// Recorded flows replay against the pure headless engine only.
		if options.HeadlessHybrid {
			options.HeadlessHybrid = false
			gologger.Warning().Msgf("Recorded flow (-rf) requires pure headless mode; disabling -hh.")
		}
		if !options.Headless {
			options.Headless = true
			gologger.Info().Msgf("Headless mode enabled automatically for recorded flow.")
		}

		username, password := "", ""
		if options.AuthCredentials != "" {
			parts := strings.SplitN(options.AuthCredentials, ":", 2)
			username = parts[0]
			if len(parts) > 1 {
				password = parts[1]
			}
		}
		steps, err := auth.StepsFromFile(options.RecordedFlow, username, password)
		if err != nil {
			return errkit.Wrap(err, "invalid recorded flow")
		}
		if auth.NeedsCredentials(steps) && options.AuthCredentials == "" {
			return errkit.New("recorded flow requires -auto-login username:password for credential placeholders")
		}
		replaySteps, loginURL := auth.StepsAfterFirstNavigateURL(steps)
		if loginURL == "" {
			return errkit.New("recorded flow requires an absolute http(s) navigate step")
		}
		if len(replaySteps) == 0 {
			return errkit.New("recorded flow requires at least one action after its navigate step")
		}
	}

	// Checked after -al and -rf, which enable pure headless mode themselves.
	if options.MaxScrollSteps > 0 && !options.Headless && options.ChromeWSUrl == "" {
		return errkit.New("headless (-hl) mode is required if -max-scroll-steps is set")
	}
	if (options.HeadlessOptionalArguments != nil || options.HeadlessNoSandbox || options.SystemChromePath != "" || options.UseInstalledChrome) &&
		!options.Headless && !options.HeadlessHybrid {
		return errkit.New("headless (-hl) or hybrid (-hh) mode is required if -ho, -nos, -sc or -scp are set")
	}
	if options.SystemChromePath != "" {
		if !fileutil.FileExists(options.SystemChromePath) {
			return errkit.New("specified system chrome binary does not exist")
		}
	}
	if options.StatsInterval != 0 {
		options.ShowStatistics = true
	}
	if options.ShowStatistics && options.StatsInterval <= 0 {
		options.StatsInterval = 5
	}
	if options.StoreResponseDir != "" && !options.StoreResponse {
		gologger.Debug().Msgf("store response directory specified, enabling \"sr\" flag automatically\n")
		options.StoreResponse = true
	}
	for _, mr := range options.OutputMatchRegex {
		cr, err := regexp.Compile(mr)
		if err != nil {
			return errkit.Wrap(err, "Invalid value for match regex option")
		}
		options.MatchRegex = append(options.MatchRegex, cr)
	}
	for _, fr := range options.OutputFilterRegex {
		cr, err := regexp.Compile(fr)
		if err != nil {
			return errkit.Wrap(err, "Invalid value for filter regex option")
		}
		options.FilterRegex = append(options.FilterRegex, cr)
	}
	if options.KnownFiles != "" && options.MaxDepth < 3 {
		gologger.Info().Msgf("Depth automatically set to 3 to accommodate the `--known-files` option (originally set to %d).", options.MaxDepth)
		options.MaxDepth = 3
	}
	gologger.DefaultLogger.SetFormatter(formatter.NewCLI(options.NoColors))
	return nil
}

// readCustomFormConfig reads custom form fill config
func readCustomFormConfig(formConfig string) error {
	file, err := os.Open(formConfig)
	if err != nil {
		return errkit.Wrap(err, "could not read form config")
	}
	defer func() {
		if err := file.Close(); err != nil {
			gologger.Error().Msgf("Error closing file: %v\n", err)
		}
	}()

	var data utils.FormFillData
	if err := yaml.NewDecoder(file).Decode(&data); err != nil {
		return errkit.Wrap(err, "could not decode form config")
	}
	data.Resolve()
	utils.FormData = data
	return nil
}

// parseInputs parses the inputs returning a slice of URLs
func (r *Runner) parseInputs() []string {
	values := make(map[string]struct{})
	for _, url := range r.options.URLs {
		if url == "" {
			continue
		}
		value := normalizeInput(url)
		if _, ok := values[value]; !ok {
			values[value] = struct{}{}
		}
	}
	if r.stdin {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			value := normalizeInput(scanner.Text())
			if _, ok := values[value]; !ok {
				values[value] = struct{}{}
			}
		}
	}
	final := make([]string, 0, len(values))
	for k := range values {
		final = append(final, k)
	}
	return final
}

func normalizeInput(value string) string {
	return strings.TrimSpace(value)
}

func initExampleFormFillConfig() error {
	homedir, err := os.UserHomeDir()
	if err != nil {
		return errkit.Wrap(err, "could not get home directory")
	}
	defaultConfig := filepath.Join(homedir, ".config", "katana", "form-config.yaml")

	if fileutil.FileExists(defaultConfig) {
		return readCustomFormConfig(defaultConfig)
	}
	if err := os.MkdirAll(filepath.Dir(defaultConfig), 0775); err != nil {
		return err
	}
	exampleConfig, err := os.Create(defaultConfig)
	if err != nil {
		return errkit.Wrap(err, "could not get home directory")
	}
	defer func() {
		if err := exampleConfig.Close(); err != nil {
			gologger.Error().Msgf("Error closing example config: %v\n", err)
		}
	}()

	err = yaml.NewEncoder(exampleConfig).Encode(utils.DefaultFormFillData)
	return err
}

