func newTestOptions() *types.Options {
	return &types.Options{
		MaxDepth: 2,
		URLs:     []string{"https://example.com"},
	}
}

func TestValidatePageLoadStrategy(t *testing.T) {
	t.Run("valid strategies are accepted", func(t *testing.T) {
		for _, strategy := range []string{"heuristic", "load", "domcontentloaded", "networkidle", "none"} {
			opts := newTestOptions()
			opts.PageLoadStrategy = strategy
			err := validateOptions(opts)
			require.NoError(t, err, "strategy %q should be valid", strategy)
			require.Equal(t, strategy, opts.PageLoadStrategy)
		}
	})

	t.Run("empty strategy defaults to heuristic", func(t *testing.T) {
		opts := newTestOptions()
		opts.PageLoadStrategy = ""
		err := validateOptions(opts)
		require.NoError(t, err)
		require.Equal(t, "heuristic", opts.PageLoadStrategy)
	})

	t.Run("invalid strategy is rejected", func(t *testing.T) {
		opts := newTestOptions()
		opts.PageLoadStrategy = "invalid"
		err := validateOptions(opts)
		require.Error(t, err)
		require.Contains(t, err.Error(), "invalid page-load-strategy")
	})
}

func TestValidateHeadlessFlags(t *testing.T) {
	t.Run("headless and hybrid are mutually exclusive", func(t *testing.T) {
		opts := newTestOptions()
		opts.Headless = true
		opts.HeadlessHybrid = true
		err := validateOptions(opts)
		require.Error(t, err)
		require.Contains(t, err.Error(), "mutually exclusive")
	})

	t.Run("no-sandbox without headless mode fails", func(t *testing.T) {
		opts := newTestOptions()
		opts.HeadlessNoSandbox = true
		err := validateOptions(opts)
		require.Error(t, err)
		require.Contains(t, err.Error(), "headless")
	})

	t.Run("no-sandbox with headless mode succeeds", func(t *testing.T) {
		opts := newTestOptions()
		opts.Headless = true
		opts.HeadlessNoSandbox = true
		err := validateOptions(opts)
		require.NoError(t, err)
	})

	t.Run("lazy scrolling requires pure headless mode", func(t *testing.T) {
		opts := newTestOptions()
		opts.MaxScrollSteps = 4
		err := validateOptions(opts)
		require.ErrorContains(t, err, "headless")
	})

	t.Run("lazy scrolling is accepted in pure headless mode", func(t *testing.T) {
		opts := newTestOptions()
		opts.Headless = true
		opts.MaxScrollSteps = 4
		require.NoError(t, validateOptions(opts))
	})

	t.Run("lazy scrolling is accepted when auto-login enables headless", func(t *testing.T) {
		opts := newTestOptions()
		opts.AuthCredentials = "user:pass"
		opts.MaxScrollSteps = 4
		require.NoError(t, validateOptions(opts))
		require.True(t, opts.Headless)
	})

	t.Run("lazy scrolling still requires pure headless with hybrid auto-login", func(t *testing.T) {
		opts := newTestOptions()
		opts.HeadlessHybrid = true
		opts.AuthCredentials = "user:pass"
		opts.MaxScrollSteps = 4
		require.ErrorContains(t, validateOptions(opts), "max-scroll-steps")
	})

	t.Run("negative lazy scroll limit is rejected", func(t *testing.T) {
		opts := newTestOptions()
		opts.Headless = true
		opts.MaxScrollSteps = -1
		require.ErrorContains(t, validateOptions(opts), "cannot be negative")
	})

	t.Run("system-chrome without headless or hybrid mode fails", func(t *testing.T) {
		opts := newTestOptions()
		opts.UseInstalledChrome = true
		err := validateOptions(opts)
		require.Error(t, err)
		require.Contains(t, err.Error(), "headless")
	})

	t.Run("system-chrome with headless mode succeeds", func(t *testing.T) {
		opts := newTestOptions()
		opts.Headless = true
		opts.UseInstalledChrome = true
		err := validateOptions(opts)
		require.NoError(t, err)
	})

	t.Run("system-chrome with hybrid mode succeeds", func(t *testing.T) {
		opts := newTestOptions()
		opts.HeadlessHybrid = true
		opts.UseInstalledChrome = true
		err := validateOptions(opts)
		require.NoError(t, err)
	})
}

func TestValidateRecordedFlow(t *testing.T) {
	writeFlow := func(t *testing.T, contents string) string {
		t.Helper()
		path := t.TempDir() + "/flow.json"
		require.NoError(t, os.WriteFile(path, []byte(contents), 0o600))
		return path
	}

	t.Run("missing file is rejected", func(t *testing.T) {
		opts := newTestOptions()
		opts.RecordedFlow = "/no/such/recorded-flow.json"
		err := validateOptions(opts)
		require.Error(t, err)
		require.Contains(t, err.Error(), "does not exist")
	})

	t.Run("forces headless and accepts chrome recording with credentials", func(t *testing.T) {
		flow := `{
		  "title": "login",
		  "steps": [
		    {"type": "navigate", "url": "https://example.com/login"},
		    {"type": "change", "value": "dave", "selectors": [["#email"]]},
		    {"type": "change", "value": "secret", "selectors": [["#password"]]},
		    {"type": "click", "selectors": [["#submit"]]}
		  ]
		}`
		opts := newTestOptions()
		opts.RecordedFlow = writeFlow(t, flow)
		opts.AuthCredentials = "dave:secret"
		err := validateOptions(opts)
		require.NoError(t, err)
		require.True(t, opts.Headless, "recorded flow should enable headless")
	})

	t.Run("requires credentials when placeholders remain", func(t *testing.T) {
		flow := `{
		  "steps": [
		    {"type": "change", "value": "x", "selectors": [["#password"]]}
		  ]
		}`
		opts := newTestOptions()
		opts.RecordedFlow = writeFlow(t, flow)
		err := validateOptions(opts)
		require.Error(t, err)
		require.Contains(t, err.Error(), "auto-login")
	})

	t.Run("disables hybrid when recorded flow is set", func(t *testing.T) {
		flow := `{"steps":[{"action":"navigate","value":"https://example.com"},{"action":"click","selector":"#submit"}]}`
		opts := newTestOptions()
		opts.HeadlessHybrid = true
		opts.RecordedFlow = writeFlow(t, flow)
		err := validateOptions(opts)
		require.NoError(t, err)
		require.False(t, opts.HeadlessHybrid)
		require.True(t, opts.Headless)
	})

	t.Run("requires absolute web navigation", func(t *testing.T) {
		opts := newTestOptions()
		opts.RecordedFlow = writeFlow(t, `{"steps":[{"action":"navigate","value":"about:blank"},{"action":"click","selector":"#submit"}]}`)
		err := validateOptions(opts)
		require.ErrorContains(t, err, "absolute http(s) navigate step")
	})

	t.Run("rejects invalid explicit action before launching browser", func(t *testing.T) {
		opts := newTestOptions()
		opts.RecordedFlow = writeFlow(t, `{"steps":[{"action":"navigate","value":"https://example.com"},{"action":"evaluate","value":"alert(1)"}]}`)
		err := validateOptions(opts)
		require.ErrorContains(t, err, "unknown action")
	})

	t.Run("requires an action after navigation", func(t *testing.T) {
		opts := newTestOptions()
		opts.RecordedFlow = writeFlow(t, `{"steps":[{"action":"navigate","value":"https://example.com"}]}`)
		err := validateOptions(opts)
		require.ErrorContains(t, err, "at least one action")
	})
}

