	baseURL = strings.TrimRight(baseURL, "/")
	return fmt.Sprintf(`{
  "title": "authlab simple login",
  "steps": [
    {"type": "setViewport", "width": 1280, "height": 720},
    {"type": "navigate", "url": %q},
