package authlab

import (
	"io"
	"net/http"
	"net/http/cookiejar"
	"net/url"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestLab_GatesSecretAndAcceptsFormLogin(t *testing.T) {
	lab, err := Start()
	require.NoError(t, err)
	t.Cleanup(func() { _ = lab.Close() })

	resp, err := http.Get(lab.URL + "/app/secret")
	require.NoError(t, err)
	require.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	_ = resp.Body.Close()

	jar, err := cookiejar.New(nil)
	require.NoError(t, err)
	client := &http.Client{Jar: jar, CheckRedirect: func(req *http.Request, via []*http.Request) error {
		return http.ErrUseLastResponse
	}}

	form := url.Values{"email": {Username}, "password": {Password}}
	resp, err = client.PostForm(lab.URL+"/login", form)
	require.NoError(t, err)
	require.Equal(t, http.StatusFound, resp.StatusCode)
	_ = resp.Body.Close()

	client.CheckRedirect = nil
	resp, err = client.Get(lab.URL + "/app/secret")
	require.NoError(t, err)
	defer func() { _ = resp.Body.Close() }()
	require.Equal(t, http.StatusOK, resp.StatusCode)
	body, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	require.Contains(t, string(body), SecretMarker)
	require.GreaterOrEqual(t, lab.LoginPosts.Load(), int64(1))
	require.GreaterOrEqual(t, lab.SecretHits.Load(), int64(1))
}

func TestLab_APILogin(t *testing.T) {
	lab, err := Start()
	require.NoError(t, err)
	t.Cleanup(func() { _ = lab.Close() })

	jar, err := cookiejar.New(nil)
	require.NoError(t, err)
	client := &http.Client{Jar: jar}

	resp, err := client.Post(lab.URL+"/api/login", "application/json",
		strings.NewReader(`{"email":"`+Username+`","password":"`+Password+`"}`))
	require.NoError(t, err)
	require.Equal(t, http.StatusOK, resp.StatusCode)
	_ = resp.Body.Close()

	resp, err = client.Get(lab.URL + "/app/dashboard")
	require.NoError(t, err)
	defer func() { _ = resp.Body.Close() }()
	require.Equal(t, http.StatusOK, resp.StatusCode)
}

func TestRecordingHelpersProduceValidJSONShape(t *testing.T) {
	for name, raw := range map[string]string{
		"simple":   ChromeRecordingSimple("http://127.0.0.1:9"),
		"step":     ChromeRecordingStep("http://127.0.0.1:9"),
		"spa":      ChromeRecordingSPA("http://127.0.0.1:9"),
		"explicit": ExplicitStepsSimple("http://127.0.0.1:9"),
	} {
		t.Run(name, func(t *testing.T) {
			require.Contains(t, raw, "steps")
			require.Contains(t, raw, "/login")
			if name == "explicit" {
				require.Contains(t, raw, "{{username}}")
				require.Contains(t, raw, "{{password}}")
			} else {
				require.Contains(t, raw, Username)
			}
		})
	}
}

package testutils

func CompareOutput(input, expected []string) bool {
	if len(input) != len(expected) {
		return false
	}
	for i, v := range input {
		if v != expected[i] {
			return false
		}
	}
	return true
}

package testutils

import (
	"bytes"
	"fmt"
	"os/exec"
	"strings"
)

func RunKatanaBinaryAndGetResults(target string, katanaBinary string, debug bool, args []string) ([]string, error) {
	if debug {
		fmt.Printf("cmd: echo %s | %s %s\n", target, katanaBinary, strings.Join(args, " "))
	}

	cmd := exec.Command(katanaBinary, args...)
	cmd.Stdin = strings.NewReader(target + "\n")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("katana failed: %w\nstderr:\n%s\nstdout:\n%s", err, stderr.String(), stdout.String())
	}

	parts := []string{}
	for _, i := range strings.Split(stdout.String(), "\n") {
		if i != "" {
			parts = append(parts, i)
		}
	}
	return parts, nil
}

package testutils

import (
	"fmt"
	"net"
	"net/http"
)

// TestServer is a local HTTP server for functional tests.
type TestServer struct {
	mux      *http.ServeMux
	listener net.Listener
	URL      string
}

// NewTestServer starts a local HTTP server on a random port with
// a small site structure suitable for crawl testing.
func NewTestServer() (*TestServer, error) {
	mux := http.NewServeMux()

	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return nil, fmt.Errorf("failed to start test server: %w", err)
	}
	baseURL := fmt.Sprintf("http://127.0.0.1:%d", listener.Addr().(*net.TCPAddr).Port)

	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html>
<head><title>Test Home</title></head>
<body>
	<a href="%s/about">About</a>
	<a href="%s/contact">Contact</a>
	<a href="%s/blog">Blog</a>
	<script src="%s/static/app.js"></script>
</body>
</html>`, baseURL, baseURL, baseURL, baseURL)
	})

	mux.HandleFunc("/about", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html>
<head><title>About</title></head>
<body>
	<a href="%s/">Home</a>
	<a href="%s/team">Team</a>
</body>
</html>`, baseURL, baseURL)
	})

	mux.HandleFunc("/contact", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html>
<head><title>Contact</title></head>
<body>
	<a href="%s/">Home</a>
	<form action="%s/submit" method="POST">
		<input type="email" name="email">
		<input type="submit" value="Send">
	</form>
</body>
</html>`, baseURL, baseURL)
	})

	mux.HandleFunc("/blog", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html>
<head><title>Blog</title></head>
<body>
	<a href="%s/">Home</a>
	<a href="%s/blog/post-1">First Post</a>
	<a href="%s/blog/post-2">Second Post</a>
</body>
</html>`, baseURL, baseURL, baseURL)
	})

	mux.HandleFunc("/blog/post-1", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html><head><title>Post 1</title></head>
<body><a href="%s/blog">Back to Blog</a></body>
</html>`, baseURL)
	})

	mux.HandleFunc("/blog/post-2", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html><head><title>Post 2</title></head>
<body><a href="%s/blog">Back to Blog</a></body>
</html>`, baseURL)
	})

	mux.HandleFunc("/team", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, `<!DOCTYPE html>
<html><head><title>Team</title></head>
<body><a href="%s/about">About</a></body>
</html>`, baseURL)
	})

	mux.HandleFunc("/submit", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprint(w, `<!DOCTYPE html><html><head><title>Thanks</title></head><body>OK</body></html>`)
	})

	mux.HandleFunc("/static/app.js", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/javascript")
		_, _ = fmt.Fprintf(w, `// app.js
fetch("%s/api/data").then(r => r.json());`, baseURL)
	})

	mux.HandleFunc("/api/data", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = fmt.Fprint(w, `{"status":"ok"}`)
	})

	go func() {
		_ = http.Serve(listener, mux)
	}()

	return &TestServer{
		mux:      mux,
		listener: listener,
		URL:      baseURL,
	}, nil
}

// Close shuts down the test server.
func (ts *TestServer) Close() error {
	return ts.listener.Close()
}

