	shared.warnBlocked("a.com", "Akamai")
	shared.warnBlocked("a.com", "Akamai")
	shared.warnBlocked("b.com", "Akamai")

	hosts := 0
	shared.blockWarned.Range(func(_, _ any) bool { hosts++; return true })
	require.Equal(t, 2, hosts)
}

