package common

import (
	"context"
	"crypto/tls"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/projectdiscovery/fastdialer/fastdialer"
	"github.com/projectdiscovery/fastdialer/fastdialer/ja3/impersonate"
	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/utils/errkit"
	proxyutil "github.com/projectdiscovery/utils/proxy"
)

type RedirectCallback func(resp *http.Response, depth int)
type ScopeValidator func(u *url.URL) bool

// BuildHttpClient builds a http client based on a profile
func BuildHttpClient(dialer *fastdialer.Dialer, options *types.Options, redirectCallback RedirectCallback, scopeValidator ...ScopeValidator) (*retryablehttp.Client, *fastdialer.Dialer, error) {
	// Single Host
	retryablehttpOptions := retryablehttp.DefaultOptionsSingle
	retryablehttpOptions.RetryMax = options.Retries
	transport := &http.Transport{
		DialContext: dialer.Dial,
		DialTLSContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			if options.TlsImpersonate {
				return dialer.DialTLSWithConfigImpersonate(ctx, network, addr, &tls.Config{InsecureSkipVerify: true, MinVersion: tls.VersionTLS10}, impersonate.Random, nil)
			}
			return dialer.DialTLS(ctx, network, addr)
		},
		MaxIdleConns:        100,
		MaxIdleConnsPerHost: 10,
		MaxConnsPerHost:     100,
		TLSClientConfig: &tls.Config{
			Renegotiation:      tls.RenegotiateOnceAsClient,
			InsecureSkipVerify: true,
		},
		DisableKeepAlives: false,
	}

	// Attempts to overwrite the dial function with the socks proxied version
	if proxyURL, err := url.Parse(options.Proxy); options.Proxy != "" && err == nil {
		if ok, err := proxyutil.IsBurp(options.Proxy); err == nil && ok {
			transport.TLSClientConfig.MaxVersion = tls.VersionTLS12
		}
		transport.Proxy = http.ProxyURL(proxyURL)
	}

	client := retryablehttp.NewWithHTTPClient(&http.Client{
		Transport: transport,
		Timeout:   time.Duration(options.Timeout) * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if options.DisableRedirects {
				return http.ErrUseLastResponse
			}
			if len(via) == 10 {
				return errkit.New("stopped after 10 redirects")
			}
			depth, ok := req.Context().Value(navigation.Depth{}).(int)
			if !ok {
				depth = 2
			}
			if redirectCallback != nil {
				redirectCallback(req.Response, depth)
			}
			if len(scopeValidator) > 0 && scopeValidator[0] != nil {
				if !scopeValidator[0](req.URL) {
					customHeaders := options.ParseCustomHeaders()
					for k := range customHeaders {
						delete(req.Header, k)
						req.Header.Del(k)
					}
					req.Header.Del("Cookie")
				}
			}
			return nil
		},
	}, retryablehttpOptions)
	client.CheckRetry = retryablehttp.HostSprayRetryPolicy()
	return client, dialer, nil
}

package common

import (
	"net/url"
	"strings"
	"unicode"

	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/utils/queue"
)

// surfaceWords are path segments that usually lead to more attack surface
// than an average page, so the priority strategy visits them first.
var surfaceWords = map[string]struct{}{
	"admin": {}, "administrator": {}, "api": {}, "graphql": {}, "rest": {},
	"upload": {}, "uploads": {}, "file": {}, "files": {}, "download": {},
	"import": {}, "export": {}, "backup": {},
	"auth": {}, "login": {}, "signin": {}, "signup": {}, "register": {},
	"oauth": {}, "sso": {}, "token": {}, "password": {}, "reset": {},
	"account": {}, "user": {}, "users": {}, "profile": {},
	"dashboard": {}, "manage": {}, "console": {}, "config": {}, "settings": {},
	"debug": {}, "internal": {},
}

// priority returns the queue priority of a request, lower is visited first.
// With the priority strategy each score point is worth one level of depth,
// so a promising link a level deeper still goes ahead of a plain one.
func (s *Shared) priority(nr *navigation.Request) int {
	if s.Options.Options.Strategy != queue.Priority.String() {
		return nr.Depth
	}
	return nr.Depth - surfaceScore(nr)
}

func surfaceScore(nr *navigation.Request) int {
	parsed, err := url.Parse(nr.URL)
	if err != nil {
		return 0
	}
	score := 0
	for _, word := range strings.FieldsFunc(strings.ToLower(parsed.Path), isWordSeparator) {
		if _, ok := surfaceWords[word]; ok {
			score += 2
			break
		}
	}
	if parsed.RawQuery != "" {
		score++
	}
	if nr.Method != "" && nr.Method != "GET" {
		score++
	}
	return score
}

func isWordSeparator(r rune) bool {
	return !unicode.IsLetter(r) && !unicode.IsDigit(r)
}

