	})

	t.Run("explicit strategy is preserved", func(t *testing.T) {
		for _, strategy := range []string{"none", "load", "domcontentloaded", "networkidle", "heuristic"} {
			l, err := NewLauncher(LauncherOptions{
				MaxBrowsers:      1,
				PageLoadStrategy: strategy,
			})
			require.NoError(t, err)
			require.Equal(t, strategy, l.opts.PageLoadStrategy)
		}
	})

	t.Run("zero DOMWaitTime defaults to 5", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
		})
		require.NoError(t, err)
		require.Equal(t, 5, l.opts.DOMWaitTime)
	})

	t.Run("negative DOMWaitTime defaults to 5", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			DOMWaitTime: -1,
		})
		require.NoError(t, err)
		require.Equal(t, 5, l.opts.DOMWaitTime)
	})

	t.Run("positive DOMWaitTime is preserved", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			DOMWaitTime: 10,
		})
		require.NoError(t, err)
		require.Equal(t, 10, l.opts.DOMWaitTime)
	})

	t.Run("ChromeWSUrl is passed through", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			ChromeWSUrl: "ws://localhost:9222/devtools/browser/abc",
		})
		require.NoError(t, err)
		require.Equal(t, "ws://localhost:9222/devtools/browser/abc", l.opts.ChromeWSUrl)
	})
}

func TestLauncherIncognitoAndProfilePreservation(t *testing.T) {
	t.Run("incognito remains enabled by default", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{MaxBrowsers: 1})
		require.NoError(t, err)
		require.True(t, l.shouldUseIncognito())
	})

	t.Run("incognito is disabled when requested", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			NoIncognito: true,
			UserDataDir: "/tmp/profile",
		})
		require.NoError(t, err)
		require.False(t, l.shouldUseIncognito())
	})

	t.Run("profile preserving mode skips conflicting flags", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			NoIncognito: true,
			UserDataDir: "/tmp/profile",
		})
		require.NoError(t, err)

		for _, flagName := range []string{"use-mock-keychain", "password-store", "disable-extensions", "enable-automation"} {
			require.True(t, l.shouldSkipHeadlessFlag(flagName), "expected %s to be skipped", flagName)
		}
		require.False(t, l.shouldSkipHeadlessFlag("disable-gpu"))
	})

	t.Run("default mode keeps standard headless flags", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			UserDataDir: "/tmp/profile",
		})
		require.NoError(t, err)
		require.False(t, l.shouldSkipHeadlessFlag("use-mock-keychain"))
	})

	t.Run("only exact user supplied profile directory is preserved", func(t *testing.T) {
		profileDir := filepath.Join(t.TempDir(), "profile")
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			UserDataDir: profileDir,
		})
		require.NoError(t, err)

		require.True(t, l.shouldPreserveUserDataDir(profileDir))
		require.False(t, l.shouldPreserveUserDataDir(filepath.Join(profileDir, "nested")))
		require.False(t, l.shouldPreserveUserDataDir(""))
	})
}

func TestLauncherSystemChromeResolution(t *testing.T) {
	origLookPath := lookPath
	t.Cleanup(func() {
		lookPath = origLookPath
	})

	t.Run("system chrome enabled and chrome is discovered", func(t *testing.T) {
		lookPath = func() (string, bool) {
			return "/usr/bin/mock-chromium", true
		}

		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers:        1,
			UseInstalledChrome: true,
		})
		require.NoError(t, err)

		cl, err := l.createChromeLauncher(t.TempDir())
		require.NoError(t, err)
		require.Equal(t, "/usr/bin/mock-chromium", cl.Get(flags.Bin))
	})

	t.Run("system chrome enabled and chrome not found returns error", func(t *testing.T) {
		lookPath = func() (string, bool) {
			return "", false
		}

		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers:        1,
			UseInstalledChrome: true,
		})
		require.NoError(t, err)

		cl, err := l.createChromeLauncher(t.TempDir())
		require.Error(t, err)
		require.Nil(t, cl)
		require.Contains(t, err.Error(), "the chrome browser is not installed")
	})

	t.Run("explicit chromium path takes precedence over lookpath", func(t *testing.T) {
		lookPath = func() (string, bool) {
			return "/usr/bin/should-not-use", true
		}

		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers:        1,
			UseInstalledChrome: true,
			ChromiumPath:       "/custom/path/to/chrome",
		})
		require.NoError(t, err)

		cl, err := l.createChromeLauncher(t.TempDir())
		require.NoError(t, err)
		require.Equal(t, "/custom/path/to/chrome", cl.Get(flags.Bin))
	})

	t.Run("explicit chromium path works without system chrome flag", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers:  1,
			ChromiumPath: "/custom/path/to/chrome",
		})
		require.NoError(t, err)

		cl, err := l.createChromeLauncher(t.TempDir())
		require.NoError(t, err)
		require.Equal(t, "/custom/path/to/chrome", cl.Get(flags.Bin))
	})

	t.Run("use installed chrome option is preserved in launcher", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers:        1,
			UseInstalledChrome: true,
		})
		require.NoError(t, err)
		require.True(t, l.opts.UseInstalledChrome)
	})
}

func TestUserDataDirCleanup(t *testing.T) {
	t.Run("tracked temporary directory is removed on Close", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
		})
		require.NoError(t, err)

		tempDir, err := os.MkdirTemp("", "katana-chrome-data-test-*")
		require.NoError(t, err)

		l.mu.Lock()
		l.tempDirs[tempDir] = struct{}{}
		l.mu.Unlock()

		require.DirExists(t, tempDir)

		l.Close()

		require.NoDirExists(t, tempDir)
	})

	t.Run("user provided directory is preserved on Close", func(t *testing.T) {
		userDir := t.TempDir()

		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
			UserDataDir: userDir,
		})
		require.NoError(t, err)

		l.mu.Lock()
		l.tempDirs[userDir] = struct{}{}
		l.mu.Unlock()

		l.Close()

		require.DirExists(t, userDir)
	})

	t.Run("tracked page is cleaned up on Close", func(t *testing.T) {
		l, err := NewLauncher(LauncherOptions{
			MaxBrowsers: 1,
		})
		require.NoError(t, err)

		tempDir, err := os.MkdirTemp("", "katana-chrome-data-test-*")
		require.NoError(t, err)

		bp := &BrowserPage{
			userDataDir: tempDir,
			launcher:    l,
			cancel:      func() {},
		}
		l.mu.Lock()
		l.pages[bp] = struct{}{}
		l.tempDirs[tempDir] = struct{}{}
		l.mu.Unlock()

		require.DirExists(t, tempDir)

		l.Close()

		require.NoDirExists(t, tempDir)
		require.Empty(t, bp.userDataDir)
	})
}

// Package cookie implements cookie consent handling for the
// crawler. Its a partial port of I-Still-Dont-Care-About-Cookies.
package cookie

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"

	"github.com/projectdiscovery/rod/lib/proto"
)

type CookieConsentBlockRequest struct {
	ID        int       `json:"id"`
	Priority  int       `json:"priority"`
	Condition Condition `json:"condition,omitempty"`
}

type Action struct {
	Type string `json:"type"`
}

type Condition struct {
	URLFilter                string   `json:"urlFilter"`
	ResourceTypes            []string `json:"resourceTypes"`
	InitiatorDomains         []string `json:"initiatorDomains"`
	ExcludedInitiatorDomains []string `json:"excludedInitiatorDomains"`
}

//go:embed rules.json
var rules []byte

var cookieConsentBlockRequests []CookieConsentBlockRequest

func init() {
	err := json.Unmarshal(rules, &cookieConsentBlockRequests)
	if err != nil {
		panic(err)
	}

	sort.SliceStable(cookieConsentBlockRequests, func(i, j int) bool {
		return cookieConsentBlockRequests[i].Priority > cookieConsentBlockRequests[j].Priority
	})
}

// ShouldBlockRequest determines if a request should be blocked based on cookie consent rules
func ShouldBlockRequest(url string, resourceType proto.NetworkResourceType, initiatorDomain string) bool {
	resourceTypeStr := getResourceType(resourceType)
	for _, rule := range cookieConsentBlockRequests {
		if matchesRule(rule, url, resourceTypeStr, initiatorDomain) {
			return true
		}
	}
	return false
}

// matchesRule checks if a request matches a specific cookie consent block rule
func matchesRule(rule CookieConsentBlockRequest, url string, resourceType string, initiatorDomain string) bool {
	if !strings.Contains(url, rule.Condition.URLFilter) {
		return false
	}

	if len(rule.Condition.ResourceTypes) > 0 {
		matched := false
		for _, rt := range rule.Condition.ResourceTypes {
			if rt == resourceType {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}

	if len(rule.Condition.InitiatorDomains) > 0 {
		matched := false
		for _, domain := range rule.Condition.InitiatorDomains {
			if strings.Contains(initiatorDomain, domain) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}

	if len(rule.Condition.ExcludedInitiatorDomains) > 0 {
		for _, domain := range rule.Condition.ExcludedInitiatorDomains {
			if strings.Contains(initiatorDomain, domain) {
				return false
			}
		}
	}

	return true
}

func getResourceType(resourceType proto.NetworkResourceType) string {
	switch resourceType {
	case proto.NetworkResourceTypeStylesheet:
		return "stylesheet"
	case proto.NetworkResourceTypeScript:
		return "script"
	case proto.NetworkResourceTypeImage:
		return "image"
	case proto.NetworkResourceTypeFont:
		return "font"
	case proto.NetworkResourceTypeXHR:
		return "xmlhttprequest"
	case proto.NetworkResourceTypePing:
		return "ping"
	case proto.NetworkResourceTypeCSPViolationReport:
		return "csp_report"
	case proto.NetworkResourceTypeMedia:
		return "media"
	case proto.NetworkResourceTypeWebSocket:
		return "websocket"
	case proto.NetworkResourceTypeOther:
		return "other"
	}
	return string(resourceType)
}

package cookie

import (
	"testing"

	"github.com/projectdiscovery/rod/lib/proto"
)

func TestShouldBlockRequest(t *testing.T) {
	tests := []struct {
		name            string
		url             string
		resourceType    proto.NetworkResourceType
		initiatorDomain string
		want            bool
	}{
		{
			name:            "should block trustarc consent notice",
			url:             "https://consent.trustarc.com/notice?domain=hackerone.com",
			resourceType:    proto.NetworkResourceTypeScript,
			initiatorDomain: "hackerone.com",
			want:            true,
		},
		{
			name:            "should not block trustarc for excluded domain",
			url:             "https://consent.trustarc.com/notice",
			resourceType:    proto.NetworkResourceTypeScript,
			initiatorDomain: "forbes.com",
			want:            false,
		},
		{
			name:            "should not block non-matching URL",
			url:             "https://example.com/other-path",
			resourceType:    proto.NetworkResourceTypeScript,
			initiatorDomain: "hackerone.com",
			want:            false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := ShouldBlockRequest(tt.url, tt.resourceType, tt.initiatorDomain)
			if got != tt.want {
				t.Errorf("ShouldBlockRequest() = %v, want %v", got, tt.want)
			}
		})
	}
}

