package browser

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/launcher"
	"github.com/projectdiscovery/rod/lib/proto"
	"github.com/stretchr/testify/require"
)

func TestPutBrowserToPoolWithChromeWSUrl(t *testing.T) {
	skipIfNoBrowser(t)

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = fmt.Fprintf(w, "<html><body>%s</body></html>", r.URL.Path)
	}))
	defer server.Close()

	tests := []struct {
		name        string
		features    string
		popupClosed bool
	}{
		{name: "popup", popupClosed: true},
		// noopener popups report no opener, so they cannot be told apart from
		// the user's tabs; only katana's page coming back to front is checked.
		{name: "noopener popup", features: "noopener"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			chrome := launcher.New().Headless(true).NoSandbox(true)
			wsURL, err := chrome.Launch()
			require.NoError(t, err)
			defer chrome.Kill()

			user := rod.New().ControlURL(wsURL)
			require.NoError(t, user.Connect())
			defer func() { _ = user.Close() }()
			_, err = user.Page(proto.TargetCreateTarget{URL: server.URL + "/user"})
			require.NoError(t, err)

			l, err := NewLauncher(LauncherOptions{MaxBrowsers: 1, NoSandbox: true, ChromeWSUrl: wsURL})
			require.NoError(t, err)
			defer l.Close()

			page, err := l.GetPageFromPool()
			require.NoError(t, err)
			require.NoError(t, page.Navigate(server.URL+"/crawl"))
			require.NoError(t, page.WaitLoad())
			_, err = page.Eval(`(url, features) => { window.open(url, "_blank", features) }`, server.URL+"/popup", tt.features)
			require.NoError(t, err)
			require.Eventually(t, func() bool { return hasPage(t, user, "/popup") }, 5*time.Second, 100*time.Millisecond)

			l.PutBrowserToPool(page)

			require.True(t, hasPage(t, user, "/user"), "user tab must survive")
			require.True(t, hasPage(t, user, "/crawl"), "katana's pooled page must survive")
			if tt.popupClosed {
				require.False(t, hasPage(t, user, "/popup"), "popup opened by katana must be closed")
			}
			// visibilityState updates asynchronously after BringToFront returns.
			require.Eventually(t, func() bool {
				visibility, err := page.Eval(`() => document.visibilityState`)
				return err == nil && visibility.Value.Str() == "visible"
			}, 2*time.Second, 50*time.Millisecond, "a backgrounded page stalls repaint waits")
		})
	}
}

func hasPage(t *testing.T, b *rod.Browser, path string) bool {
	t.Helper()
	targets, err := proto.TargetGetTargets{}.Call(b)
	require.NoError(t, err)
	for _, target := range targets.TargetInfos {
		if target.Type == proto.TargetTargetInfoTypePage && strings.HasSuffix(target.URL, path) {
			return true
		}
	}
	return false
}

package browser

import (
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/katana/pkg/engine/headless/types"
)

const (
	// buttonsCSSSelector is the css selector for all buttons
	buttonsCSSSelector = "button, input[type='button'], input[type='submit']"
	// linksCSSSelector is the css selector for all anchor tags
	linksCSSSelector = "a"
)

type pageScrollMetrics struct {
	Top      float64 `json:"top"`
	Height   float64 `json:"height"`
	Viewport float64 `json:"viewport"`
}

const readScrollMetricsScript = `() => {
  const root = document.scrollingElement || document.documentElement;
  const bodyHeight = document.body ? document.body.scrollHeight : 0;
  return {
    top: window.scrollY || root.scrollTop || 0,
    height: Math.max(root.scrollHeight || 0, bodyHeight),
    viewport: window.innerHeight || root.clientHeight || 0,
  };
}`

// RevealLazyContent performs a bounded number of viewport-sized scrolls before
// navigation discovery. This activates common infinite-scroll and lazy-render
// handlers while retaining a hard work limit for pages that never stop growing.
func (b *BrowserPage) RevealLazyContent(maxSteps int, settle time.Duration) (int, error) {
	if maxSteps <= 0 {
		return 0, nil
	}
	if settle < 0 {
		settle = 0
	}

	steps := 0
	for steps < maxSteps {
		before, err := b.readScrollMetrics()
		if err != nil {
			return steps, err
		}
		if before.Height <= before.Viewport+lazyScrollPixelTolerance {
			// Nothing to scroll, so no scroll handlers can fire.
			break
		}
		if _, err := b.Eval(`() => {
  const root = document.scrollingElement || document.documentElement;
  const viewport = window.innerHeight || root.clientHeight || 1;
  window.scrollBy(0, Math.max(1, viewport - 64));
}`); err != nil {
			return steps, err
		}
		steps++

		if err := b.waitSettle(settle); err != nil {
			return steps, err
		}
		after, err := b.readScrollMetrics()
		if err != nil {
			return steps, err
		}
		if shouldStopLazyScroll(before, after) {
			stable, err := b.lazyContentStable(after, settle)
			if err != nil {
				return steps, err
			}
			if stable {
				break
			}
		}
	}
	return steps, nil
}

// lazyScrollStableChecks is how many extra settle periods the page must stay
// unchanged at the bottom before scrolling stops, so lazy-load responses that
// land after the first settle are still revealed before discovery.
const lazyScrollStableChecks = 2

// lazyContentStable re-samples a page that looks fully scrolled and reports
// whether it stayed at the bottom without growing. These checks do not count
// as scroll steps.
func (b *BrowserPage) lazyContentStable(last pageScrollMetrics, settle time.Duration) (bool, error) {
	for i := 0; i < lazyScrollStableChecks; i++ {
		if err := b.waitSettle(settle); err != nil {
			return false, err
		}
		current, err := b.readScrollMetrics()
		if err != nil {
			return false, err
		}
		if !shouldStopLazyScroll(last, current) {
			return false, nil
		}
	}
	return true, nil
}

func (b *BrowserPage) waitSettle(settle time.Duration) error {
	if settle <= 0 {
		return nil
	}
	timer := time.NewTimer(settle)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-b.GetContext().Done():
		return b.GetContext().Err()
	}
}

func (b *BrowserPage) readScrollMetrics() (pageScrollMetrics, error) {
	value, err := b.Eval(readScrollMetricsScript)
	if err != nil {
		return pageScrollMetrics{}, err
	}
	var metrics pageScrollMetrics
	if err := value.Value.Unmarshal(&metrics); err != nil {
		return pageScrollMetrics{}, err
	}
	return metrics, nil
}

const lazyScrollPixelTolerance = 2

func shouldStopLazyScroll(before, after pageScrollMetrics) bool {
	atBottom := after.Top+after.Viewport >= after.Height-lazyScrollPixelTolerance
	heightDidNotGrow := after.Height <= before.Height+lazyScrollPixelTolerance
	return atBottom && heightDidNotGrow
}

// isElementDisabled checks if a button element is disabled
func isElementDisabled(element *types.HTMLElement) bool {
	if element.Attributes == nil {
		return false
	}

	// Standard HTML disabled attribute
	if _, disabled := element.Attributes["disabled"]; disabled {
		return true
	}

	// Tailwind or framework class-based detection
	if classAttr, ok := element.Attributes["class"]; ok {
		classList := strings.Fields(classAttr)
		for _, class := range classList {
			if class == "cursor-not-allowed" || class == "pointer-events-none" {
				return true
			}
		}
	}

	// Optionally support ARIA disabled
	if aria, ok := element.Attributes["aria-disabled"]; ok && (aria == "true" || aria == "1") {
		return true
	}

	return false
}

// FindNavigation attempts to find more navigations on the page which could
// be done to find more links and pages.
//
// This includes the following -
//  1. Forms
//  2. Buttons
//  3. Links
//  4. Elements with event listeners
//
// The navigations found are unique across the page. The caller
// needs to ensure they are unique globally before doing further actions with details.
func (b *BrowserPage) FindNavigations() ([]*types.Action, error) {
	unique := make(map[string]struct{})

	navigations := make([]*types.Action, 0)

	forms, err := b.GetAllForms()
	if err != nil {
		return nil, errors.Wrap(err, "could not get forms")
	}
	for _, form := range forms {
		for _, element := range form.Elements {
			if element.TagName != "BUTTON" {
				continue
			}
			// TODO: Check if this button is already in the unique map
			// and if so remove it
			unique[element.Hash()] = struct{}{}
		}
		hash := form.Hash()
		if _, found := unique[hash]; found {
			continue
		}
		unique[hash] = struct{}{}

		navigations = append(navigations, &types.Action{
			Type: types.ActionTypeFillForm,
			Form: form,
		})
	}

	buttons, err := b.GetAllElements(buttonsCSSSelector)
	if err != nil {
		return nil, errors.Wrap(err, "could not get buttons")
	}
	for _, button := range buttons {
		if isElementDisabled(button) {
			continue
		}

		hash := button.Hash()
		button.MD5Hash = hash

		if _, found := unique[hash]; found {
			continue
		}
		unique[hash] = struct{}{}
		navigations = append(navigations, &types.Action{
			Type:    types.ActionTypeLeftClick,
			Element: button,
		})
	}

	scopeValidator := b.launcher.ScopeValidator()
	links, err := b.GetAllElements(linksCSSSelector)
	if err != nil {
		return nil, errors.Wrap(err, "could not get links")
	}
	info, err := b.Info()
	if err != nil {
		return nil, errors.Wrap(err, "could not get page info")
	}
	for _, link := range links {
		href := link.Attributes["href"]
		if href == "" {
			continue
		}

		resolvedHref, err := resolveURL(info.URL, href)
		if err != nil {
			continue
		}

		u, err := url.Parse(resolvedHref)
		if err != nil {
			continue
		}
		if u.Scheme != "http" && u.Scheme != "https" {
			continue
		}
		if !scopeValidator(resolvedHref) {
			continue
		}

		hash := link.Hash()
		link.MD5Hash = hash

		if _, found := unique[hash]; found {
			continue
		}
		unique[hash] = struct{}{}
		navigations = append(navigations, &types.Action{
			Type:    types.ActionTypeLeftClick,
			Element: link,
		})
	}

	eventListeners, err := b.GetEventListeners()
	if err != nil {
		return nil, errors.Wrap(err, "could not get event listeners")
	}
	for _, listener := range eventListeners {
		if _, found := relevantEventListeners[listener.Type]; !found {
			continue
		}
		if listener.Element == nil {
			continue
		}
		hash := listener.Element.Hash()
		listener.Element.MD5Hash = hash
		if _, found := unique[hash]; found {
			continue
		}
		unique[hash] = struct{}{}
		navigations = append(navigations, types.ActionFromEventListener(listener))
	}

	navLinks, err := b.GetNavigatedLinks()
	if err == nil {
		for _, link := range navLinks {
			if link.URL == "" {
				continue
			}
			resolved, err := resolveURL(info.URL, link.URL)
			if err != nil {
				continue
			}
			if _, found := unique[resolved]; found {
				continue
			}
			unique[resolved] = struct{}{}
			navigations = append(navigations, &types.Action{
				Type:  types.ActionTypeLoadURL,
				Input: resolved,
			})
		}
	}

	return navigations, nil
}

