func TestShouldStopLazyScroll(t *testing.T) {
	tests := []struct {
		name   string
		before pageScrollMetrics
		after  pageScrollMetrics
		stop   bool
	}{
		{
			name:   "stable bottom",
			before: pageScrollMetrics{Top: 500, Height: 1000, Viewport: 500},
			after:  pageScrollMetrics{Top: 500, Height: 1000, Viewport: 500},
			stop:   true,
		},
		{
			name:   "lazy content grew",
			before: pageScrollMetrics{Top: 500, Height: 1000, Viewport: 500},
			after:  pageScrollMetrics{Top: 500, Height: 1500, Viewport: 500},
			stop:   false,
		},
		{
			name:   "not at bottom",
			before: pageScrollMetrics{Top: 0, Height: 2000, Viewport: 500},
			after:  pageScrollMetrics{Top: 436, Height: 2000, Viewport: 500},
			stop:   false,
		},
		{
			name:   "subpixel tolerance",
			before: pageScrollMetrics{Top: 499, Height: 1000, Viewport: 500},
			after:  pageScrollMetrics{Top: 499.5, Height: 1000.5, Viewport: 500},
			stop:   true,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			require.Equal(t, test.stop, shouldStopLazyScroll(test.before, test.after))
		})
	}
}

package browser

import (
	"net/url"
	"strings"

	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/proto"
)

// applyBrowserHeaders seeds Cookie via the browser cookie jar (scoped to
// cookieURL) and returns the remaining custom headers for per-request
// injection. Page-wide SetExtraHeaders is intentionally avoided so values
// like Authorization are not leaked to CDN or other third-party hosts.
func applyBrowserHeaders(page *rod.Page, headers map[string]string, cookieURL string) (map[string]string, error) {
	cookies, extra := splitCustomHeaders(headers, cookieURL)
	if len(cookies) > 0 {
		if err := page.SetCookies(cookies); err != nil {
			return nil, err
		}
	}
	return extra, nil
}

// splitCustomHeaders separates Cookie (jar-scoped) from other -H values.
func splitCustomHeaders(headers map[string]string, cookieURL string) ([]*proto.NetworkCookieParam, map[string]string) {
	if len(headers) == 0 {
		return nil, nil
	}
	extra := make(map[string]string)
	var cookies []*proto.NetworkCookieParam
	for name, value := range headers {
		if strings.EqualFold(name, "Cookie") {
			cookies = append(cookies, parseCookieHeader(value, cookieURL)...)
			continue
		}
		extra[name] = value
	}
	if len(extra) == 0 {
		extra = nil
	}
	return cookies, extra
}

func parseCookieHeader(raw, targetURL string) []*proto.NetworkCookieParam {
	var cookies []*proto.NetworkCookieParam
	for _, pair := range strings.Split(raw, ";") {
		name, value, found := strings.Cut(strings.TrimSpace(pair), "=")
		name = strings.TrimSpace(name)
		if !found || name == "" {
			continue
		}
		cookies = append(cookies, &proto.NetworkCookieParam{
			Name: name, Value: strings.TrimSpace(value), URL: targetURL, Path: "/",
		})
	}
	return cookies
}

// shouldAttachExtraHeaders reports whether non-cookie custom headers go with
// reqURL. Like the standard engine, they follow the crawl scope, so third-party
// resources the page loads never receive them. Without a scope validator they
// stay on the root URL's origin.
func shouldAttachExtraHeaders(reqURL string, validate ScopeValidator, rootURL string) bool {
	if validate != nil {
		return validate(reqURL)
	}
	return rootURL != "" && sameOrigin(rootURL, reqURL)
}

// sameOrigin compares scheme, hostname, and effective port (defaulting
// http/ws→80, https/wss→443 when the port is omitted).
func sameOrigin(baseURL, reqURL string) bool {
	base, err := url.Parse(baseURL)
	if err != nil || base.Hostname() == "" || base.Scheme == "" {
		return false
	}
	req, err := url.Parse(reqURL)
	if err != nil || req.Hostname() == "" || req.Scheme == "" {
		return false
	}
	return strings.EqualFold(base.Scheme, req.Scheme) &&
		strings.EqualFold(base.Hostname(), req.Hostname()) &&
		effectivePort(base) == effectivePort(req)
}

func effectivePort(u *url.URL) string {
	if p := u.Port(); p != "" {
		return p
	}
	switch strings.ToLower(u.Scheme) {
	case "https", "wss":
		return "443"
	case "http", "ws":
		return "80"
	default:
		return ""
	}
}

// mergeRequestHeaders builds Fetch.continueRequest headers: existing request
// headers with extra overlayed. A non-nil Headers value replaces the whole set.
func mergeRequestHeaders(existing proto.NetworkHeaders, extra map[string]string) []*proto.FetchHeaderEntry {
	if len(extra) == 0 {
		return nil
	}
	out := make([]*proto.FetchHeaderEntry, 0, len(existing)+len(extra))
	seen := make(map[string]struct{}, len(extra))
	for name, value := range extra {
		out = append(out, &proto.FetchHeaderEntry{Name: name, Value: value})
		seen[strings.ToLower(name)] = struct{}{}
	}
	for name, value := range existing {
		if _, ok := seen[strings.ToLower(name)]; ok {
			continue
		}
		out = append(out, &proto.FetchHeaderEntry{Name: name, Value: value.Str()})
	}
	return out
}

// isFetchRequestStage is true for Fetch pauses before the request is sent.
func isFetchRequestStage(e *proto.FetchRequestPaused) bool {
	return e != nil && e.ResponseStatusCode == nil && e.ResponseErrorReason == ""
}

package browser

import (
	"strings"
	"testing"

	"github.com/projectdiscovery/rod/lib/proto"
	"github.com/stretchr/testify/require"
	"github.com/ysmood/gson"
)

func TestParseCookieHeaderScopesToRootURL(t *testing.T) {
	cookies := parseCookieHeader("session=abc=123; theme=dark; invalid", "https://app.example.test/dashboard")
	require.Len(t, cookies, 2)
	require.Equal(t, "session", cookies[0].Name)
	require.Equal(t, "abc=123", cookies[0].Value)
	require.Equal(t, "https://app.example.test/dashboard", cookies[0].URL)
	require.Equal(t, "/", cookies[0].Path)
	require.Equal(t, "theme", cookies[1].Name)
}

func TestSplitCustomHeadersKeepsCookieScopedAndExtraSeparate(t *testing.T) {
	cookies, extra := splitCustomHeaders(map[string]string{
		"Cookie":        "session=ok",
		"Authorization": "Bearer secret",
		"X-Trace":       "1",
	}, "https://app.example.test/")
	require.Len(t, cookies, 1)
	require.Equal(t, "session", cookies[0].Name)
	require.Equal(t, "https://app.example.test/", cookies[0].URL)
	require.Equal(t, map[string]string{
		"Authorization": "Bearer secret",
		"X-Trace":       "1",
	}, extra)
	require.False(t, shouldAttachExtraHeaders("https://cdn.third-party.test/lib.js", nil, "https://app.example.test/"))
	require.True(t, shouldAttachExtraHeaders("https://app.example.test/api", nil, "https://app.example.test/"))
}

func TestShouldAttachExtraHeadersFollowsScope(t *testing.T) {
	inScope := func(u string) bool { return strings.Contains(u, "example.test") }
	rootURL := "http://app.example.test/"
	require.True(t, shouldAttachExtraHeaders("http://app.example.test/api", inScope, rootURL))
	require.True(t, shouldAttachExtraHeaders("https://api.example.test/v1", inScope, rootURL))
	require.False(t, shouldAttachExtraHeaders("https://cdn.third-party.test/lib.js", inScope, rootURL))
}

func TestShouldAttachExtraHeadersWithoutScopeKeepsRootOrigin(t *testing.T) {
	rootURL := "https://app.example.test/"
	require.True(t, shouldAttachExtraHeaders("https://app.example.test/api", nil, rootURL))
	require.True(t, shouldAttachExtraHeaders("https://app.example.test:443/api", nil, rootURL))
	require.False(t, shouldAttachExtraHeaders("https://app.example.test:8443/api", nil, rootURL))
	require.False(t, shouldAttachExtraHeaders("https://cdn.third-party.test/lib.js", nil, rootURL))
	require.False(t, shouldAttachExtraHeaders("https://app.example.test/api", nil, ""))
}

func TestSameOrigin(t *testing.T) {
	require.True(t, sameOrigin("https://a.test/", "https://a.test/path"))
	require.True(t, sameOrigin("https://a.test/", "https://a.test:443/path"))
	require.False(t, sameOrigin("https://a.test/", "https://a.test:8443/path"))
	require.False(t, sameOrigin("https://a.test/", "http://a.test/path"))
	require.False(t, sameOrigin("https://a.test/", "https://b.test/path"))
	require.False(t, sameOrigin("", "https://a.test/"))
}

func TestMergeRequestHeadersOverlaysExtraWithoutDroppingOthers(t *testing.T) {
	existing := proto.NetworkHeaders{
		"Accept":        gson.New("text/html"),
		"Authorization": gson.New("stale"),
	}
	extra := map[string]string{"Authorization": "Bearer secret", "X-Trace": "1"}
	merged := mergeRequestHeaders(existing, extra)
	require.Len(t, merged, 3)

	got := map[string]string{}
	for _, h := range merged {
		got[h.Name] = h.Value
	}
	require.Equal(t, "Bearer secret", got["Authorization"])
	require.Equal(t, "1", got["X-Trace"])
	require.Equal(t, "text/html", got["Accept"])
}

func TestMergeRequestHeadersNilWhenNoExtra(t *testing.T) {
	require.Nil(t, mergeRequestHeaders(proto.NetworkHeaders{"Accept": gson.New("*/*")}, nil))
}

func TestIsFetchRequestStage(t *testing.T) {
	require.True(t, isFetchRequestStage(&proto.FetchRequestPaused{}))
	status := 200
	require.False(t, isFetchRequestStage(&proto.FetchRequestPaused{ResponseStatusCode: &status}))
	require.False(t, isFetchRequestStage(&proto.FetchRequestPaused{ResponseErrorReason: proto.NetworkErrorReasonFailed}))
	require.False(t, isFetchRequestStage(nil))
}

package browser

import (
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestGetPageFromPoolReleasesSlotWhenCreateFails(t *testing.T) {
	launcher, err := NewLauncher(LauncherOptions{
		MaxBrowsers:  1,
		ChromiumPath: "/nonexistent/chrome",
		NoSandbox:    true,
	})
	require.NoError(t, err)
	defer launcher.Close()

	_, err = launcher.GetPageFromPool()
	require.Error(t, err)
	require.Len(t, launcher.browserPool, 1)

	done := make(chan struct{})
	go func() {
		_, _ = launcher.GetPageFromPool()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("GetPageFromPool blocked after a failed page creation")
	}
}

func TestPutBrowserToPoolReplenishesDiscardedSlot(t *testing.T) {
	skipIfNoBrowser(t)

	launcher, err := NewLauncher(LauncherOptions{
		MaxBrowsers: 1,
		NoSandbox:   true,
	})
	require.NoError(t, err)
	defer launcher.Close()

	page, err := launcher.GetPageFromPool()
	require.NoError(t, err)
	require.Empty(t, launcher.browserPool)

	// Simulate a page whose action context hit a deadline. The discarded page
	// must release its pool slot; otherwise the next GetPageFromPool blocks.
	page.cancel()
	launcher.PutBrowserToPool(page)
	require.Len(t, launcher.browserPool, 1)

	replacement, err := launcher.GetPageFromPool()
	require.NoError(t, err)
	require.NotNil(t, replacement)
	launcher.PutBrowserToPool(replacement)
}

