func TestPerformAdditionalAnalysisHonorsJsluice(t *testing.T) {
	h := newTestHeadless(t, false, false)
	p := parser.NewResponseParser()
	p.InitWithOptions(&parser.Options{ScrapeJSLuiceResponses: true})
	h.options.Parser = p

	pageURL := "https://example.com/page"
	html := `<html><body><script>fetch("/api/jsluice_only");</script></body></html>`
	results := h.performAdditionalAnalysis(&output.Result{
		Request:  &navigation.Request{URL: pageURL},
		Response: makeResponse(t, pageURL, html),
	})

	found := false
	for _, r := range results {
		if r.Request != nil && r.Request.URL == "https://example.com/api/jsluice_only" {
			found = true
			break
		}
	}
	require.True(t, found, "-jsl inline script endpoint not extracted, got %v", results)
}

package headless

import (
	"net/http"
	"net/url"
	"strings"
	"testing"

	"github.com/PuerkitoBio/goquery"
	"github.com/projectdiscovery/katana/pkg/engine/parser"
	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/katana/pkg/utils"
	"github.com/projectdiscovery/katana/pkg/utils/filters"
	"github.com/stretchr/testify/require"
)

func newTestHeadless(t *testing.T, ignoreQueryParams, filterSimilar bool) *Headless {
	t.Helper()

	filter, err := filters.NewSimple()
	require.NoError(t, err)
	t.Cleanup(filter.Close)

	opts := &types.Options{
		IgnoreQueryParams: ignoreQueryParams,
		FilterSimilar:     filterSimilar,
	}
	crawlerOpts := &types.CrawlerOptions{
		Options:      opts,
		UniqueFilter: filter,
		Parser:       parser.NewResponseParser(),
	}
	h := &Headless{options: crawlerOpts}
	if filterSimilar {
		h.pathTrie = utils.NewPathTrie(opts.FilterSimilarThreshold)
	}
	return h
}

func TestIsUniqueURL(t *testing.T) {
	t.Run("first_call_returns_true", func(t *testing.T) {
		h := newTestHeadless(t, false, false)
		require.True(t, h.isUniqueURL("https://example.com/a"))
	})

	t.Run("second_call_same_url_returns_false", func(t *testing.T) {
		h := newTestHeadless(t, false, false)
		require.True(t, h.isUniqueURL("https://example.com/a"))
		require.False(t, h.isUniqueURL("https://example.com/a"))
	})

	t.Run("different_urls_both_unique", func(t *testing.T) {
		h := newTestHeadless(t, false, false)
		require.True(t, h.isUniqueURL("https://example.com/a"))
		require.True(t, h.isUniqueURL("https://example.com/b"))
	})

	t.Run("ignore_query_params", func(t *testing.T) {
		h := newTestHeadless(t, true, false)
		require.True(t, h.isUniqueURL("https://example.com/page?id=1"))
		require.False(t, h.isUniqueURL("https://example.com/page?id=2"),
			"same path and key with different value should be duplicate when IgnoreQueryParams is set")
	})

	t.Run("query_params_matter_when_not_ignored", func(t *testing.T) {
		h := newTestHeadless(t, false, false)
		require.True(t, h.isUniqueURL("https://example.com/page?id=1"))
		require.True(t, h.isUniqueURL("https://example.com/page?id=2"),
			"different query param values should be unique when IgnoreQueryParams is off")
	})
}

func TestRealRequestTakesPriority(t *testing.T) {
	h := newTestHeadless(t, false, false)

	targetURL := "https://example.com/target"

	// Simulate the reordered RequestCallback: real request registers first.
	isUnique := h.isUniqueURL(targetURL)
	require.True(t, isUnique, "real request should register as unique")

	// A later performAdditionalAnalysis call that discovers the same URL
	// should see it as already registered.
	require.False(t, h.isUniqueURL(targetURL),
		"synthetic discovery of same URL should be filtered after real request registered it")
}

func makeResponse(t *testing.T, pageURL, html string) *navigation.Response {
	t.Helper()
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(html))
	require.NoError(t, err)
	parsed, err := url.Parse(pageURL)
	require.NoError(t, err)
	return &navigation.Response{
		Body:   html,
		Reader: doc,
		Resp:   &http.Response{Request: &http.Request{URL: parsed}},
	}
}

func TestPerformAdditionalAnalysisDedups(t *testing.T) {
	h := newTestHeadless(t, false, false)

	html := `<html><body>
		<a href="https://example.com/link1">Link 1</a>
		<a href="https://example.com/link2">Link 2</a>
		<a href="https://example.com/link1">Link 1 again</a>
		<a href="https://example.com/page">Self</a>
	</body></html>`

	pageURL := "https://example.com/page"
	rr := &output.Result{
		Request:  &navigation.Request{URL: pageURL},
		Response: makeResponse(t, pageURL, html),
	}

	// Register the real request URL first (matching the reordered callback flow).
	h.isUniqueURL(rr.Request.URL)

	results := h.performAdditionalAnalysis(rr)

	// Count occurrences to verify dedup actually works (a map would hide duplicates).
	counts := make(map[string]int)
	for _, r := range results {
		counts[r.Request.URL]++
	}
	require.Equal(t, 1, counts["https://example.com/link1"], "link1 should appear exactly once")
	require.Equal(t, 1, counts["https://example.com/link2"], "link2 should appear exactly once")
	require.Equal(t, 0, counts["https://example.com/page"],
		"self-referencing page URL should be filtered since the real request already registered it")
	require.Len(t, results, 2, "only the two unique non-page links should be returned")
}

func TestAdditionalAnalysisStillRunsForDuplicateRequests(t *testing.T) {
	h := newTestHeadless(t, false, false)

	// Simulate page A discovering URL B via additional analysis.
	h.isUniqueURL("https://example.com/a")
	h.isUniqueURL("https://example.com/b") // as if discovered from A's analysis

	// Now the browser visits B. B is a duplicate, but its response body
	// contains a new URL C that we should still discover.
	html := `<html><body>
		<a href="https://example.com/c">New link</a>
	</body></html>`

	bURL := "https://example.com/b"
	rr := &output.Result{
		Request:  &navigation.Request{URL: bURL},
		Response: makeResponse(t, bURL, html),
	}

	// In the reordered callback, B is checked first (returns false = duplicate),
	// but additional analysis still runs.
	isUnique := h.isUniqueURL(rr.Request.URL)
	require.False(t, isUnique, "B should be a duplicate")

	results := h.performAdditionalAnalysis(rr)

	var foundC bool
	for _, r := range results {
		if r.Request.URL == "https://example.com/c" {
			foundC = true
		}
	}
	require.True(t, foundC, "new URL C should be discovered even though B was a duplicate request")
}

func TestPerformAdditionalAnalysisHonorsParserOptions(t *testing.T) {
	h := newTestHeadless(t, false, false)
	h.options.Options.ScrapeJSResponses = true
	p := parser.NewResponseParser()
	p.InitWithOptions(&parser.Options{ScrapeJSResponses: true})
	h.options.Parser = p

	pageURL := "https://example.com/page"
	html := `<html><body><script>var cfg = {endpoint: "/api/inline_secret"};</script></body></html>`
	resp := makeResponse(t, pageURL, html)
	resp.Resp.StatusCode = http.StatusFound
	resp.Resp.Header = http.Header{"Location": []string{"/redirected"}}

	results := h.performAdditionalAnalysis(&output.Result{
		Request:  &navigation.Request{URL: pageURL},
		Response: resp,
	})

	found := map[string]bool{}
	for _, r := range results {
		found[r.Request.URL] = true
	}
	require.True(t, found["https://example.com/api/inline_secret"], "-jc inline script endpoint not extracted, got %v", found)
	require.True(t, found["https://example.com/redirected"], "Location header not extracted, got %v", found)
}

package headless

import "github.com/projectdiscovery/katana/pkg/engine/headless/crawler"

// Hooks re-exports crawler.Hooks so library users can configure headless
// lifecycle callbacks without importing the internal crawler sub-package.
// See crawler.Hooks for field-level documentation and semantics.
type Hooks = crawler.Hooks

// SetHooks installs lifecycle callbacks on the headless engine. The supplied
// struct is copied, so mutating it after SetHooks returns has no effect on the
// engine; call SetHooks again to change the installed hooks. Passing nil clears
// any previously installed hooks. SetHooks is not safe to call concurrently
// with Crawl on the same engine.
func (h *Headless) SetHooks(hooks *Hooks) {
	if hooks == nil {
		h.hooks = Hooks{}
		return
	}
	h.hooks = *hooks
}

package headless

import (
	"testing"

	"github.com/projectdiscovery/katana/pkg/engine/headless/browser"
	"github.com/projectdiscovery/katana/pkg/engine/headless/types"
	"github.com/stretchr/testify/assert"
)

// TestSetHooks_SnapshotsCallerStruct guards the contract that SetHooks copies
// the supplied Hooks value: mutating the caller's struct after SetHooks
// returns must not affect the engine's installed hooks.
func TestSetHooks_SnapshotsCallerStruct(t *testing.T) {
	original := func(_ *browser.BrowserPage, _ *types.Action) error { return nil }
	mutated := func(_ *browser.BrowserPage, _ *types.Action) error { return assert.AnError }

	hooks := &Hooks{BeforeAction: original}
	h := &Headless{}
	h.SetHooks(hooks)

	hooks.BeforeAction = mutated

	require := assert.New(t)
	require.NotNil(h.hooks.BeforeAction, "BeforeAction should still be installed")
	require.NoError(
		h.hooks.BeforeAction(nil, nil),
		"engine must keep the snapshot taken at SetHooks time, not the caller's mutated pointer",
	)
}

// TestSetHooks_NilClears verifies that passing nil resets the engine to the
// zero-value Hooks, which is in turn safe to invoke at every callback site.
func TestSetHooks_NilClears(t *testing.T) {
	h := &Headless{}
	h.SetHooks(&Hooks{BeforeAction: func(_ *browser.BrowserPage, _ *types.Action) error { return nil }})
	h.SetHooks(nil)

	assert.Equal(t, Hooks{}, h.hooks, "passing nil to SetHooks should clear all installed hooks")
}

package headless_test

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/katana/pkg/engine/headless/crawler"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/stretchr/testify/require"
)

func TestInteractiveCrawlFourLevelsWithScopedHeaders(t *testing.T) {
	skipIfNoBrowser(t)
	var thirdPartyAuth atomic.Bool
	thirdParty := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") != "" {
			thirdPartyAuth.Store(true)
		}
		w.Header().Set("Content-Type", "application/javascript")
		_, _ = fmt.Fprint(w, `window.thirdParty = true;`)
	}))
	defer thirdParty.Close()

	var mu sync.Mutex
	served := map[string]bool{}
	authed := map[string]bool{}
	lab := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		served[r.URL.Path] = true
		if r.Header.Get("Authorization") == "Bearer secret" {
			authed[r.URL.Path] = true
		}
		mu.Unlock()
		if r.URL.Path == "/" {
			if cookie, err := r.Cookie("session"); err != nil || cookie.Value != "ok" {
				http.Error(w, "cookie missing", http.StatusForbidden)
				return
			}
			w.Header().Set("Content-Type", "text/html")
			_, _ = fmt.Fprintf(w, `<html><body><button id="next" onclick="advance()">next 0</button><button id="sibling" onclick="showSibling()">sibling</button><button id="popup" onclick="window.open('/popup')">popup</button><script src="%s/lib.js"></script><script type="module" src="/main.js"></script></body></html>`, thirdParty.URL)
			return
		}
		if r.URL.Path == "/popup" {
			w.Header().Set("Content-Type", "text/html")
			_, _ = fmt.Fprint(w, `<html><body><button id="popup-next" onclick="openNested()">open nested</button><script type="module" src="/popup.js"></script></body></html>`)
			return
		}
		w.Header().Set("Content-Type", "application/javascript")
		switch r.URL.Path {
		case "/main.js":
			_, _ = fmt.Fprint(w, `window.advance = async () => { const d = Number(document.body.dataset.depth || 0) + 1; await import('/chunk' + d + '.js'); document.body.dataset.depth = d; document.querySelector('#next').textContent = 'next ' + d; document.querySelector('#sibling')?.remove(); document.querySelector('#popup')?.remove(); }; window.showSibling = async () => { await import('/sibling.js'); document.body.dataset.sibling = 'opened'; };`)
		case "/popup.js":
			_, _ = fmt.Fprint(w, `window.openNested = async () => { await import('/popup-chunk.js'); document.querySelector('#popup-next').textContent = 'opened'; };`)
		default:
			if strings.HasSuffix(r.URL.Path, ".js") {
				_, _ = fmt.Fprint(w, `export const chunk = true;`)
				return
			}
			http.NotFound(w, r)
		}
	}))
	defer lab.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 75*time.Second)
	defer cancel()
	c, err := crawler.New(crawler.Options{
		Context: ctx, MaxBrowsers: 1, MaxDepth: 1, PageMaxTimeout: 15 * time.Second, NoSandbox: true,
		RootURL:       lab.URL,
		CustomHeaders: map[string]string{"Cookie": "session=ok", "Authorization": "Bearer secret"},
		Interactive:   true, InteractionDepth: 4,
		InteractionSelector: "button", InteractionMaxStates: 20,
		InteractionMaxActions: 20, InteractionSettle: time.Second,
		ScopeValidator: func(u string) bool { return strings.HasPrefix(u, lab.URL) },
		Logger:         slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo})),
	})
	require.NoError(t, err)
	defer c.Close()
	require.NoError(t, c.Crawl(lab.URL))

	mu.Lock()
	defer mu.Unlock()
	for _, path := range []string{"/main.js", "/chunk1.js", "/chunk2.js", "/chunk3.js", "/chunk4.js", "/sibling.js", "/popup.js", "/popup-chunk.js"} {
		require.True(t, served[path], "interactive crawl did not load %s", path)
		// A popup's first fetches can leave before its tab is attached; the
		// re-navigation after adoption must carry the header.
		require.True(t, authed[path], "custom header missing on %s", path)
	}
	require.False(t, thirdPartyAuth.Load(), "custom header leaked to out-of-scope host")
}

func TestInteractiveDurationContinuesQueuedCrawl(t *testing.T) {
	skipIfNoBrowser(t)
	lab := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = fmt.Fprint(w, `<html><body>queued crawl</body></html>`)
	}))
	defer lab.Close()
	var observed atomic.Bool
	c, err := crawler.New(crawler.Options{
		Context: context.Background(), MaxBrowsers: 1, MaxDepth: 1, NoSandbox: true,
		MaxCrawlDuration: 20 * time.Second, PageMaxTimeout: 5 * time.Second,
		RootURL: lab.URL, Interactive: true, InteractionDepth: 4,
		InteractionSelector: "button", InteractionDuration: time.Millisecond,
		RequestCallback: func(result *output.Result) {
			if result != nil && result.Request != nil && result.Request.URL == lab.URL+"/" {
				observed.Store(true)
			}
		},
		Logger: slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo})),
	})
	require.NoError(t, err)
	defer c.Close()
	require.NoError(t, c.Crawl(lab.URL+"/"))
	require.True(t, observed.Load(), "ordinary crawl did not run after UI time limit")
}

package js

import (
	_ "embed"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/rod"
)

var (
	//go:embed utils.js
	utilsJavascriptBundle string

	//go:embed page-init.js
	pageInitJavascriptBundle string
)

// InitJavascriptEnv injects the necessary javascript code into the browser
func InitJavascriptEnv(page *rod.Page) error {
	return InitJavascriptEnvWithHooks(page, false)
}

// InitJavascriptEnvWithHooks enables listener discovery only for the opt-in
// interactive crawler; instrumenting every listener slows ordinary crawls.
func InitJavascriptEnvWithHooks(page *rod.Page, hooks bool) error {
	if _, err := page.EvalOnNewDocument(utilsJavascriptBundle); err != nil {
		return errors.Wrap(err, "failed to inject utils.js")
	}
	if hooks {
		if _, err := page.EvalOnNewDocument(`window.__katanaHooksOptions = { hooked: true };`); err != nil {
			return errors.Wrap(err, "failed to enable interaction hooks")
		}
	}
	if _, err := page.EvalOnNewDocument(pageInitJavascriptBundle); err != nil {
		return errors.Wrap(err, "failed to inject page-init.js")
	}
	return nil
}

// This script initializes the page and hooks up event listeners
// and other interesting stuff needed to make the crawling work.
//
// Actions performed:
//
// 1. Hook addTargetListener to capture all the event listeners added on the page.
//    These are accessible via window.__eventListeners
// 2. Hook window.open to capture all the opened pages.
//    These are accessible via window.__navigatedLinks
// 3. Hook setTimeout and setInterval to speed up delayed actions
// 4. Hook form reset to prevent the form from being reset
// 5. Hook window.close to prevent the page from being closed
// 6. Hook history pushState and replaceState for new links
// 7. Add event listener for hashchange to identify new navigations
// 8. TODO: Hook inline event listeners so that layer0 event listeners can be tracked as well
(function pageInitAndHook() {
    const markElementReadonlyProperties = {
      writable: false,
      configurable: false,
    };

    // hookNavigatedLinkSinks hooks the navigated link sinks
    // on the page to capture all the navigated links.
    function hookNavigatedLinkSinks() {
      window.__navigatedLinks = [];

      // Hook history.pushState and history.replaceState to capture all the navigated links
      const __origPushState = window.history.pushState.bind(window.history);
      const __origReplaceState = window.history.replaceState.bind(window.history);
      function __wrappedPushState(a, b, c) {
        try { window.__navigatedLinks.push({ url: c, source: "history.pushState" }); } catch (_) {}
        return __origPushState(a, b, c);
      }
      function __wrappedReplaceState(a, b, c) {
        try { window.__navigatedLinks.push({ url: c, source: "history.replaceState" }); } catch (_) {}
        return __origReplaceState(a, b, c);
      }
      Object.defineProperty(window.history, "pushState", { value: __wrappedPushState, writable: false, configurable: false });
      Object.defineProperty(window.history, "replaceState", { value: __wrappedReplaceState, writable: false, configurable: false });
      // Hook window.open to capture all the opened pages
      const __origOpen = window.open.bind(window);
      function __wrappedOpen(url, ...rest) {
        try { window.__navigatedLinks.push({ url, source: "window.open" }); } catch (_) {}
        return __origOpen(url, ...rest);
      }
      Object.defineProperty(window, "open", { value: __wrappedOpen, writable: false, configurable: false });

      // Add event listener for hashchange
      window.addEventListener("hashchange", function () {
        window.__navigatedLinks.push({
          url: document.location.href,
          source: "hashchange",
        });
      });

      const __OrigWebSocket = window.WebSocket;
      function __WrappedWebSocket(url, protocols) {
        try { window.__navigatedLinks.push({ url, source: "websocket" }); } catch (_) {}
        return Reflect.construct(__OrigWebSocket, [url, protocols], new.target || __WrappedWebSocket);
      }
      __WrappedWebSocket.prototype = __OrigWebSocket.prototype;
      Object.setPrototypeOf(__WrappedWebSocket, __OrigWebSocket);
      Object.defineProperty(window, "WebSocket", { value: __WrappedWebSocket, writable: false, configurable: false });

      const __OrigEventSource = window.EventSource;
      function __WrappedEventSource(url, eventSourceInitDict) {
        try { window.__navigatedLinks.push({ url, source: "eventsource" }); } catch (_) {}
        return Reflect.construct(__OrigEventSource, [url, eventSourceInitDict], new.target || __WrappedEventSource);
      }
      __WrappedEventSource.prototype = __OrigEventSource.prototype;
      Object.setPrototypeOf(__WrappedEventSource, __OrigEventSource);
      Object.defineProperty(window, "EventSource", { value: __WrappedEventSource, writable: false, configurable: false });

      const __origFetch = window.fetch.bind(window);
      function __wrappedFetch(...args) {
        const url = args[0] instanceof Request ? args[0].url : args[0];
        try { window.__navigatedLinks.push({ url: url, source: "fetch" }); } catch (_) {}
        return __origFetch(...args);
      }
      Object.defineProperty(window, "fetch", { value: __wrappedFetch, writable: false, configurable: false });
    }

    // hookMiscellaneousUtilities performs miscellaneous hooks
    // on the page to prevent certain actions from happening
    // and to speed up certain actions.
    function hookMiscellaneousUtilities() {
      // Hook form reset to conditionally prevent the form from being reset
      const __origFormReset = HTMLFormElement.prototype.reset;
      const __wrappedFormReset = function (...args) {
        if (window.__katanaHooksOptions?.preventFormReset === true) {
          try { console.log("[hook] cancel reset form"); } catch (_) {}
          return;
        }
        return __origFormReset.apply(this, args);
      };
      Object.defineProperty(
        HTMLFormElement.prototype,
        "reset",
        { value: __wrappedFormReset, writable: false, configurable: false }
      );

      // Hook window.close to prevent the page from being closed
      const __wrappedClose = function () {
        console.log("[hook] trying to close page.");
      };
      Object.defineProperty(window, "close", { value: __wrappedClose, writable: false, configurable: false });

      // Hook setTimeout and setInterval to speed up delayed actions
      // on the page. This is useful where there is some request happening
      // on the page after a delay or some animation happening after a delay.
      const __origSetTimeout = window.setTimeout;
      const __origSetInterval = window.setInterval;

      const speedUpFactor = 0.1;

      function __wrappedSetTimeout(callback, delay, ...args) {
        return __origSetTimeout(callback, delay * speedUpFactor, ...args);
      }
      function __wrappedSetInterval(callback, delay, ...args) {
        return __origSetInterval(callback, delay * speedUpFactor, ...args);
      }
      Object.defineProperty(window, "setTimeout", { value: __wrappedSetTimeout, writable: false, configurable: false });
      Object.defineProperty(window, "setInterval", { value: __wrappedSetInterval, writable: false, configurable: false });
    }

    // hookAddEventListener hooks the addTargetListener to capture
    // all the event listeners added on the page
    function hookAddEventListener() {
      const originalAddEventListener = Element.prototype.addEventListener;

      window.__eventListeners = [];
      Element.prototype.addEventListener = function (type, listener, options) {
        // Ensure `this` is a valid element and has the necessary properties
        if (!this || !this.tagName) {
          return originalAddEventListener.call(this, type, listener, options);
        }

        if (this.tagName == "BODY") {
          return originalAddEventListener.call(this, type, listener, options);
        }
        let item = {
          element: {
            tagName: this.tagName,
            id: this.id,
            classes: this.className,
            outerHTML: this.outerHTML.slice(0, 100), // Capture a snippet of the element's outerHTML
            xpath: window.getXPath(this),
            cssSelector: window.getCssPath(this),
            attributes: window.getElementAttributes(this),
            textContent: this.textContent.trim(),
            hidden: this.hidden,
            name: this.name,
            type: this.type,
            value: this.value,
          },
          type: type,
          listener: listener.toString(),
          options: options || {},
        };
        window.__eventListeners.push(item);
        return originalAddEventListener.call(this, type, listener, options);
      };
    }

    // Main hook initialization part
    const __opts = window.__katanaHooksOptions || { hooked: false };
    try { if (__opts.hooked === true) hookAddEventListener(); } catch (_) {}
    try { if (__opts.hooked === true) hookNavigatedLinkSinks(); } catch (_) {}
    try { if (__opts.hooked === true) hookMiscellaneousUtilities(); } catch (_) {}
  })();

// This file contains utility JS functions that are utilised by
// the main crawling JS code to perform actions.
(function initUtilityFunctions() {
    // getElementAttributes returns the attributes of an element
    window.getElementAttributes = function (element) {
      const attrs = {};
      for (let attr of element.attributes) {
        attrs[attr.name] = attr.value;
      }
      return attrs;
    };

    // _elementDataFromElement returns the data for an element
    window._elementDataFromElement = function (el) {
      return {
        tagName: el.tagName,
        id: el.id,
        classes: typeof el.className === 'string' ? el.className : Array.from(el.classList).join(' '),
        attributes: window.getElementAttributes(el),
        hidden: el.hidden,
        outerHTML: el.outerHTML,
        name: el.name,
        type: el.type,
        value: el.value != null ? String(el.value) : '',
        textContent: el.textContent.trim(),
        xpath: window.getXPath(el),
        cssSelector: window.getCssPath(el),
      };
    };

    // getAllElements returns all the elements for a query
    // selector on the page
    window.getAllElements = function (selector) {
      try {
        const nodes = document.querySelectorAll(selector);
        return Array.from(nodes).map((el) => _elementDataFromElement(el));
      } catch (_) {
        return [];
      }
    };

    window.getInteractiveElements = function (selector, exclude) {
      const nodes = document.querySelectorAll(selector);
      return Array.from(nodes)
        .filter((el) => !exclude || !el.closest(exclude))
        .map((el) => _elementDataFromElement(el));
    };

    window.getClickListenerElements = function () {
      const elements = (window.__eventListeners || [])
        .filter((listener) => listener.type === 'click' && listener.element)
        .map((listener) => listener.element);
      for (const el of document.querySelectorAll('*')) {
        if (el !== document.body && el !== document.documentElement && typeof el.onclick === 'function') {
          elements.push(_elementDataFromElement(el));
        }
      }
      return elements;
    };

    window.getElementFromXPath = function (xpath) {
      try {
        const element = document
          .evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null)
          .singleNodeValue;
        return element ? _elementDataFromElement(element) : null;
      } catch (_) {
        return null;
      }
    }

    // getAllElementsWithEventListeners returns all the elements
    // on the page along with their event listeners
    // TODO: Is it optimized? or do we need to do something else?
    window.getAllElementsWithEventListeners = function () {
      const elements = document.querySelectorAll("*");
      const elementsWithListeners = [];
      for (let el of elements) {
        const listeners = getEventListeners(el);
        if (listeners && listeners.length) {
          elementsWithListeners.push({
            element: _elementDataFromElement(el),
            listeners: listeners,
          });
        }
      }
      return elementsWithListeners;
    };

    // getEventListeners returns all the event listeners
    // attached to an element
    function getEventListeners(element) {
      const listeners = [];
      for (let event in element) {
        if (event.startsWith("on")) {
          const listener = element[event];
          if (typeof listener === "function") {
            listeners.push({
              type: event,
              listener: listener.toString(),
            });
          }
        }
      }
      return listeners;
    }

    // A form field named id, action or method shadows that form property,
    // so read them from the prototype, as the browser does on submit.
    function formProperty(form, name) {
      if (!(form instanceof HTMLFormElement)) return form[name];
      return Object.getOwnPropertyDescriptor(HTMLFormElement.prototype, name).get.call(form);
    }

    // getAllForms returns all the forms on the page
    // along with their elements
    window.getAllForms = function () {
      const forms = document.querySelectorAll("form");
      const pseudoForms = document.querySelectorAll("div.form");

      const allForms = [...forms, ...pseudoForms];
      return Array.from(allForms).map((form) => ({
        tagName: form.tagName,
        id: form.getAttribute('id') || '',
        classes: typeof form.className === 'string' ? form.className : Array.from(form.classList).join(' '),
        attributes: window.getElementAttributes(form),
        outerHTML: form.outerHTML,
        action: formProperty(form, 'action') ? String(formProperty(form, 'action')) : '',
        method: formProperty(form, 'method'),
        xpath: window.getXPath(form),
        cssSelector: window.getCssPath(form),
        elements: form.elements ? 
          Array.from(form.elements).map((el) => _elementDataFromElement(el)) :
          Array.from(form.querySelectorAll('input, select, textarea, button')).map((el) => _elementDataFromElement(el))
      }));
    };

    // Copyright (C) Chrome Authors
    // The below code is part of the Chrome DevTools project
    // and is adapted from there.

    // Utility to get the CSS selector path for an element.
    window.getCssPath = function (node, optimized = false) {
      if (node.nodeType !== Node.ELEMENT_NODE) return "";

      const steps = [];
      let contextNode = node;
      while (contextNode) {
        const step = window._cssPathStep(
          contextNode,
          optimized,
          contextNode === node
        );
        if (!step) break; // Error - bail out early.
        steps.push(step.value);
        if (step.optimized) break;
        contextNode = contextNode.parentNode;
      }

      steps.reverse();
      return steps.join(" > ");
    };

    // Utility to get the XPath for an element.
    window.getXPath = function (node, optimized = false) {
      if (node.nodeType === Node.DOCUMENT_NODE) return "/";

      const steps = [];
      let contextNode = node;
      while (contextNode) {
        const step = window._xPathValue(contextNode, optimized);
        if (!step) break; // Error - bail out early.
        steps.push(step.value);
        if (step.optimized) break;
        contextNode = contextNode.parentNode;
      }

      steps.reverse();
      return (steps.length && steps[0].optimized ? "" : "/") + steps.join("/");
    };

    // Helper to create a step in the CSS path.
    window._cssPathStep = function (node, optimized, isTargetNode) {
      if (node.nodeType !== Node.ELEMENT_NODE) return null;

      const id = node.getAttribute("id");
      if (optimized) {
        if (id) return {
          value: `#${window.escapeIdentifierIfNeeded(id)}`,
          optimized: true,
        };
        const nodeNameLower = node.nodeName.toLowerCase();
        if (
          nodeNameLower === "body" ||
          nodeNameLower === "head" ||
          nodeNameLower === "html"
        )
          return { value: node.nodeName, optimized: true };
      }
      const nodeName = node.nodeName;

      if (id) return {
        value: `${nodeName}#${window.escapeIdentifierIfNeeded(id)}`,
        optimized: true,
      };
      const parent = node.parentNode;
      if (!parent || parent.nodeType === Node.DOCUMENT_NODE)
        return { value: nodeName, optimized: true };

      const prefixedOwnClassNamesArray = window.prefixedElementClassNames(node);
      let needsClassNames = false;
      let needsNthChild = false;
      let ownIndex = -1;
      let elementIndex = -1;
      const siblings = parent.children;
      for (
        let i = 0;
        (ownIndex === -1 || !needsNthChild) && i < siblings.length;
        ++i
      ) {
        const sibling = siblings[i];
        if (sibling.nodeType !== Node.ELEMENT_NODE) continue;
        elementIndex += 1;
        if (sibling === node) {
          ownIndex = elementIndex;
          continue;
        }
        if (needsNthChild) continue;
        if (sibling.nodeName.toLowerCase() !== nodeName.toLowerCase()) continue;

        needsClassNames = true;
        const ownClassNames = new Set(prefixedOwnClassNamesArray);
        if (!ownClassNames.size) {
          needsNthChild = true;
          continue;
        }
        const siblingClassNamesArray = window.prefixedElementClassNames(sibling);
        for (let j = 0; j < siblingClassNamesArray.length; ++j) {
          const siblingClass = siblingClassNamesArray[j];
          if (!ownClassNames.has(siblingClass)) continue;
          ownClassNames.delete(siblingClass);
          if (!ownClassNames.size) {
            needsNthChild = true;
            break;
          }
        }
      }

      let result = nodeName;
      if (
        isTargetNode &&
        nodeName.toLowerCase() === "input" &&
        node.getAttribute("type") &&
        !node.getAttribute("id") &&
        !node.getAttribute("class")
      )
        result += '[type="' + node.getAttribute("type") + '"]';
      if (needsNthChild) {
        result += `:nth-child(${ownIndex + 1})`;
      } else if (needsClassNames) {
        for (const prefixedName of prefixedOwnClassNamesArray)
          result += "." + window.escapeIdentifierIfNeeded(prefixedName.substr(1));
      }

      return { value: result, optimized: false };
    };

    // Helper to get class names prefixed with '$' for mapping purposes.
    window.prefixedElementClassNames = function (node) {
      const classAttribute = node.getAttribute("class");
      if (!classAttribute) return [];

      return classAttribute
        .split(/\s+/g)
        .filter(Boolean)
        .map(function (name) {
          return "$" + name;
        });
    };

    // Helper to escape identifiers for use in CSS selectors.
    window.escapeIdentifierIfNeeded = function (ident) {
      if (window.isCSSIdentifier(ident)) return ident;
      const shouldEscapeFirst = /^(?:[0-9]|-[0-9-]?)/.test(ident);
      const lastIndex = ident.length - 1;
      return ident.replace(/./g, function (c, i) {
        return (shouldEscapeFirst && i === 0) || !window.isCSSIdentChar(c)
          ? window.escapeAsciiChar(c, i === lastIndex)
          : c;
      });
    };

    // Helper to determine if a character is valid in a CSS identifier.
    window.isCSSIdentChar = function (c) {
      if (/[a-zA-Z0-9_-]/.test(c)) return true;
      return c.charCodeAt(0) >= 0xa0;
    };

    // Helper to determine if a string is a valid CSS identifier.
    window.isCSSIdentifier = function (value) {
      return /^-{0,2}[a-zA-Z_][a-zA-Z0-9_-]*$/.test(value);
    };

    // Helper to escape ASCII characters for use in CSS selectors.
    window.escapeAsciiChar = function (c, isLast) {
      return (
        "\\" + c.charCodeAt(0).toString(16).padStart(2, "0") + (isLast ? "" : " ")
      );
    };

    // Helper to get the XPath step for a node.
    window._xPathValue = function (node, optimized) {
      let ownValue;
      const ownIndex = window._xPathIndex(node);
      if (ownIndex === -1) return null;

      switch (node.nodeType) {
        case Node.ELEMENT_NODE:
          if (optimized && node.getAttribute("id"))
            return {
              value: `//*[@id="${node.getAttribute("id")}"]`,
              optimized: true,
            };
          ownValue = node.localName;
          break;
        case Node.ATTRIBUTE_NODE:
          ownValue = "@" + node.nodeName;
          break;
        case Node.TEXT_NODE:
        case Node.CDATA_SECTION_NODE:
          ownValue = "text()";
          break;
        case Node.PROCESSING_INSTRUCTION_NODE:
          ownValue = "processing-instruction()";
          break;
        case Node.COMMENT_NODE:
          ownValue = "comment()";
          break;
        case Node.DOCUMENT_NODE:
          ownValue = "";
          break;
        default:
          ownValue = "";
          break;
      }

      if (ownIndex > 0) ownValue += `[${ownIndex}]`;

      return { value: ownValue, optimized: node.nodeType === Node.DOCUMENT_NODE };
    };

    // Helper to get the XPath index for a node.
    window._xPathIndex = function (node) {
      function areNodesSimilar(left, right) {
        if (left === right) return true;

        if (
          left.nodeType === Node.ELEMENT_NODE &&
          right.nodeType === Node.ELEMENT_NODE
        )
          return left.localName === right.localName;

        if (left.nodeType === right.nodeType) return true;

        const leftType =
          left.nodeType === Node.CDATA_SECTION_NODE
            ? Node.TEXT_NODE
            : left.nodeType;
        const rightType =
          right.nodeType === Node.CDATA_SECTION_NODE
            ? Node.TEXT_NODE
            : right.nodeType;
        return leftType === rightType;
      }

      const siblings = node.parentNode ? node.parentNode.children : null;
      if (!siblings) return 0;
      let hasSameNamedElements = false;
      for (let i = 0; i < siblings.length; ++i) {
        if (areNodesSimilar(node, siblings[i]) && siblings[i] !== node) {
          hasSameNamedElements = true;
          break;
        }
      }
      if (!hasSameNamedElements) return 0;
      let ownIndex = 1;
      for (let i = 0; i < siblings.length; ++i) {
        if (areNodesSimilar(node, siblings[i])) {
          if (siblings[i] === node) return ownIndex;
          ++ownIndex;
        }
      }
      return -1;
    };
  })();

package headless_test

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/projectdiscovery/katana/pkg/engine/headless/crawler"
	"github.com/stretchr/testify/require"
)

// lazyLinksPage renders a feed whose links appear only after the visitor
// scrolls to the bottom, loadDelayMs after the scroll. Scroll restoration is
// manual, as in many SPAs, so going back does not reload the feed by itself.
const lazyLinksPage = `<!doctype html><html><head><title>feed</title></head><body>
<div style="height:4000px">feed</div>
<div id="more"></div>
<script>
history.scrollRestoration = 'manual';
let requested = false;
window.addEventListener('scroll', () => {
  if (requested) return;
  if (window.scrollY + window.innerHeight < document.body.scrollHeight - 200) return;
  requested = true;
  setTimeout(() => {
    const more = document.getElementById('more');
    for (let n = 1; n <= 20; n++) {
      const item = document.createElement('article');
      item.innerHTML = '<h2>Story ' + n + '</h2><p>Summary text for story number ' + n + '</p>';
      if (n <= 3) {
        const a = document.createElement('a');
        a.id = 'lazy-' + n;
        a.href = '/lazy/' + n;
        a.textContent = 'lazy ' + n;
        item.appendChild(a);
      }
      more.appendChild(item);
    }
  }, %d);
});
</script></body></html>`

func TestE2E_Crawl_FollowsLazyLoadedLinks(t *testing.T) {
	skipIfNoBrowser(t)

	tests := []struct {
		name        string
		loadDelayMs int
	}{
		{name: "immediate", loadDelayMs: 0},
		// Slower than one 300ms settle period, within the stability window.
		{name: "delayed", loadDelayMs: 500},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			var mu sync.Mutex
			hits := map[string]int{}
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				mu.Lock()
				hits[r.URL.Path]++
				mu.Unlock()
				w.Header().Set("Content-Type", "text/html")
				if r.URL.Path == "/" {
					// no-store keeps the feed out of the back/forward cache, so a
					// history navigation reloads it without the scrolled-in links.
					w.Header().Set("Cache-Control", "no-store")
					_, _ = fmt.Fprintf(w, lazyLinksPage, test.loadDelayMs)
					return
				}
				_, _ = fmt.Fprintf(w, "<html><head><title>%s</title></head><body>%s</body></html>", r.URL.Path, r.URL.Path)
			}))
			t.Cleanup(server.Close)

			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
			defer cancel()

			c, err := crawler.New(crawler.Options{
				Context:          ctx,
				MaxBrowsers:      1,
				MaxDepth:         3,
				MaxCrawlDuration: 60 * time.Second,
				PageMaxTimeout:   15 * time.Second,
				NoSandbox:        true,
				MaxScrollSteps:   10,
				Logger:           slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelError})),
				ScopeValidator:   func(u string) bool { return strings.HasPrefix(u, server.URL) },
			})
			require.NoError(t, err)
			t.Cleanup(c.Close)

			require.NoError(t, c.Crawl(server.URL+"/"))

			mu.Lock()
			defer mu.Unlock()
			for _, path := range []string{"/lazy/1", "/lazy/2", "/lazy/3"} {
				require.Positive(t, hits[path], "lazy link %s was never followed, hits=%v", path, hits)
			}
		})
	}
}

package headless

import (
	"errors"
	"testing"

	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/stretchr/testify/require"
)

type stubWriter struct{ err error }

func (w *stubWriter) Close() error                 { return nil }
func (w *stubWriter) Write(*output.Result) error   { return w.err }
func (w *stubWriter) WriteErr(*output.Error) error { return nil }
func (w *stubWriter) GetResultCount() int64        { return 0 }

func TestWriteResultCallsOnResult(t *testing.T) {
	result := &output.Result{Request: &navigation.Request{URL: "https://example.com/a"}}

	t.Run("written", func(t *testing.T) {
		var got []string
		h := &Headless{options: &types.CrawlerOptions{
			OutputWriter: &stubWriter{},
			Options:      &types.Options{OnResult: func(r output.Result) { got = append(got, r.Request.URL) }},
		}}
		require.NoError(t, h.writeResult(result))
		require.Equal(t, []string{"https://example.com/a"}, got)
	})

	t.Run("not_written", func(t *testing.T) {
		called := false
		h := &Headless{options: &types.CrawlerOptions{
			OutputWriter: &stubWriter{err: errors.New("filtered")},
			Options:      &types.Options{OnResult: func(output.Result) { called = true }},
		}}
		require.Error(t, h.writeResult(result))
		require.False(t, called)
	})
}

package types

import (
	"crypto/md5"
	"encoding/hex"
	"fmt"
	"os"
	"sort"
	"strings"
)

var (
	IsDiagnosticEnabled = false
)

// PageState represents a page in the state of the
// web application as determined by the crawler.
// It represents the vertex of the crawl graph
type PageState struct {
	UniqueID    string `json:"unique_id,omitempty"`
	SimHash     uint64 `json:"sim_hash,omitempty"`
	OriginID    string `json:"origin_id,omitempty"`
	URL         string `json:"url,omitempty"`
	Title       string `json:"title,omitempty"`
	DOM         string `json:"dom,omitempty"`
	StrippedDOM string `json:"stripped_dom,omitempty"`
	Depth       int    `json:"depth,omitempty"`
	IsRoot      bool   `json:"is_root,omitempty"`

	// NavigationAction is actions taken to reach this state
	NavigationAction *Action `json:"navigation_actions,omitempty"`
}

// Action is a action taken in the browser
type Action struct {
	OriginID string       `json:"origin_id,omitempty"`
	Type     ActionType   `json:"type,omitempty"`
	Input    string       `json:"input,omitempty"`
	Element  *HTMLElement `json:"element,omitempty"`
	Form     *HTMLForm    `json:"form,omitempty"`
	Depth    int          `json:"depth,omitempty"`
	ResultID string       `json:"result_id,omitempty"`
}

func (a *Action) Hash() string {
	if a.Element != nil {
		return a.Element.Hash()
	}
	if a.Form != nil {
		return a.Form.Hash()
	}
	return string(a.Type) + "|" + a.Input + "|" + a.OriginID
}

func (a *Action) String() string {
	var builder strings.Builder
	builder.WriteString(string(a.Type))
	if a.Type == ActionTypeLoadURL {
		_, _ = fmt.Fprintf(&builder, " %s", a.Input)
	}
	if a.Element != nil {
		_, _ = fmt.Fprintf(&builder, " on %s", a.Element)
	}
	value := builder.String()
	return value
}

type ActionType string

const (
	ActionTypeUnknown         ActionType = "unknown"
	ActionTypeLoadURL         ActionType = "load_url"
	ActionTypeExecuteJS       ActionType = "execute_js"
	ActionTypeLeftClick       ActionType = "left_click"
	ActionTypeLeftClickDown   ActionType = "left_click_down"
	ActionTypeLeftClickUp     ActionType = "left_click_up"
	ActionTypeRightClick      ActionType = "right_click"
	ActionTypeDoubleClick     ActionType = "double_click"
	ActionTypeScroll          ActionType = "scroll"
	ActionTypeSendKeys        ActionType = "send_keys"
	ActionTypeKeyUp           ActionType = "key_up"
	ActionTypeKeyDown         ActionType = "key_down"
	ActionTypeHover           ActionType = "hover"
	ActionTypeFocus           ActionType = "focus"
	ActionTypeBlur            ActionType = "blur"
	ActionTypeMouseOverAndOut ActionType = "mouse_over_and_out"
	ActionTypeMouseWheel      ActionType = "mouse_wheel"
	ActionTypeFillForm        ActionType = "fill_form"
	ActionTypeWait            ActionType = "wait"
	ActionTypeRedirect        ActionType = "redirect"
	ActionTypeSubRequest      ActionType = "sub_request"
)

func ActionFromEventListener(listener *EventListener) *Action {
	var actionType ActionType

	switch listener.Type {
	case "click":
		actionType = ActionTypeLeftClick
	case "mousedown":
		actionType = ActionTypeLeftClickDown
	case "mouseup":
		actionType = ActionTypeLeftClickUp
	case "keydown":
		actionType = ActionTypeKeyDown
	case "keyup":
		actionType = ActionTypeKeyUp
	case "focus":
		actionType = ActionTypeFocus
	case "blur":
		actionType = ActionTypeBlur
	case "scroll":
		actionType = ActionTypeScroll
	case "dblclick":
		actionType = ActionTypeDoubleClick
	case "contextmenu":
		actionType = ActionTypeRightClick
	case "mouseover", "mouseout":
		actionType = ActionTypeMouseOverAndOut
	case "wheel":
		actionType = ActionTypeMouseWheel
	default:
		actionType = ActionTypeUnknown
	}

	return &Action{
		Type:    actionType,
		Element: listener.Element,
	}
}

// HTMLElement represents a DOM element
type HTMLElement struct {
	TagName     string            `json:"tagName,omitempty"`
	ID          string            `json:"id,omitempty"`
	Classes     string            `json:"classes,omitempty"`
	Attributes  map[string]string `json:"attributes,omitempty"`
	Hidden      bool              `json:"hidden,omitempty"`
	OuterHTML   string            `json:"outerHTML,omitempty"`
	Type        string            `json:"type,omitempty"`
	Value       string            `json:"value,omitempty"`
	CSSSelector string            `json:"cssSelector,omitempty"`
	XPath       string            `json:"xpath,omitempty"`
	TextContent string            `json:"textContent,omitempty"`
	MD5Hash     string            `json:"md5Hash,omitempty"`
}

func (e *HTMLElement) String() string {
	var builder strings.Builder
	builder.WriteString(e.TagName)
	if e.ID != "" {
		_, _ = fmt.Fprintf(&builder, "#%s", e.ID)
	}
	if e.Classes != "" {
		_, _ = fmt.Fprintf(&builder, ".%s", e.Classes)
	}
	if e.TextContent != "" {
		trimmedContent := strings.Trim(e.TextContent, " \n\r\t")
		_, _ = fmt.Fprintf(&builder, " (%s)", trimmedContent)
	}
	value := builder.String()
	return value
}

func (e *HTMLElement) Hash() string {
	hasher := md5.New()

	var parts []string
	// Use stable identifiers
	parts = append(parts, e.TagName)

	if e.ID != "" {
		parts = append(parts, "id:"+e.ID)
	}
	if e.Classes != "" {
		parts = append(parts, "class:"+e.Classes)
	}

	// Add stable attributes
	stableAttrs := getStableAttributes(e.Attributes)
	for _, k := range stableAttrs {
		parts = append(parts, fmt.Sprintf("%s:%s", k, e.Attributes[k]))
	}

	hashInput := strings.Join(parts, "|")
	if IsDiagnosticEnabled {
		fmt.Fprintf(os.Stderr, "[diagnostic] Element hash input: %s\n", hashInput)
	}
	hasher.Write([]byte(hashInput))
	return hex.EncodeToString(hasher.Sum(nil))
}

// HTMLForm represents a form element
type HTMLForm struct {
	TagName     string            `json:"tagName,omitempty"`
	ID          string            `json:"id,omitempty"`
	Classes     string            `json:"classes,omitempty"`
	Attributes  map[string]string `json:"attributes,omitempty"`
	Hidden      bool              `json:"hidden,omitempty"`
	OuterHTML   string            `json:"outerHTML,omitempty"`
	Action      string            `json:"action,omitempty"`
	Method      string            `json:"method,omitempty"`
	Elements    []*HTMLElement    `json:"elements,omitempty"`
	CSSSelector string            `json:"cssSelector,omitempty"`
	XPath       string            `json:"xpath,omitempty"`
}

func (f *HTMLForm) Hash() string {
	hasher := md5.New()

	var parts []string
	parts = append(parts, f.TagName)

	if f.ID != "" {
		parts = append(parts, "id:"+f.ID)
	}
	if f.Classes != "" {
		parts = append(parts, "class:"+f.Classes)
	}

	// Add stable attributes
	stableAttrs := getStableAttributes(f.Attributes)
	for _, k := range stableAttrs {
		parts = append(parts, fmt.Sprintf("%s:%s", k, f.Attributes[k]))
	}
	parts = append(parts, fmt.Sprintf("action:%s", f.Action), fmt.Sprintf("method:%s", f.Method))

	// Include hashes of form elements
	for _, element := range f.Elements {
		parts = append(parts, element.Hash())
	}

	hashInput := strings.Join(parts, "|")
	if IsDiagnosticEnabled {
		fmt.Fprintf(os.Stderr, "[diagnostic] Form hash input: %s\n", hashInput)
	}
	hasher.Write([]byte(hashInput))
	return hex.EncodeToString(hasher.Sum(nil))
}

// getStableAttributes returns a sorted slice of attribute keys that are considered stable.
func getStableAttributes(attrs map[string]string) []string {
	stableKeys := map[string]struct{}{
		"id":          {},
		"name":        {},
		"type":        {},
		"href":        {},
		"src":         {},
		"action":      {},
		"method":      {},
		"placeholder": {},
		"onclick":     {},
	}

	var stableAttrs []string
	for key := range attrs {
		if _, exists := stableKeys[key]; exists {
			stableAttrs = append(stableAttrs, key)
		}
	}

	// Sort the attributes to ensure consistent order for hashing.
	sort.Strings(stableAttrs)

	return stableAttrs
}

type EventListener struct {
	Element  *HTMLElement `json:"element,omitempty"`
	Type     string       `json:"type,omitempty"`
	Listener string       `json:"listener,omitempty"`
}

// NavigationType represents the type of navigation
type NavigationType string

const (
	// NavigationTypeForm represents a form navigation
	NavigationTypeForm NavigationType = "form"
	// NavigationTypeButton represents a button navigation
	NavigationTypeButton NavigationType = "button"
	// NavigationTypeLink represents a link navigation
	NavigationTypeLink NavigationType = "link"
	// NavigationTypeEventListener represents an event listener navigation
	NavigationTypeEventListener NavigationType = "eventlistener"
)

package hybrid

import (
