func TestShouldParseSubresourceOncePerBody(t *testing.T) {
	newCrawler := func(t *testing.T, disableUnique bool) *Crawler {
		t.Helper()
		filter, err := filters.NewSimple()
		require.NoError(t, err)
		t.Cleanup(filter.Close)
		return &Crawler{Shared: &common.Shared{Options: &types.CrawlerOptions{
			Options:      &types.Options{DisableUniqueFilter: disableUnique},
			UniqueFilter: filter,
		}}}
	}
	script := []byte(`fetch("/api/v1/users")`)
	const scriptURL = "https://example.com/static/app.js"

	t.Run("repeated subresource body parsed once", func(t *testing.T) {
		c := newCrawler(t, false)
		require.True(t, c.shouldParse(false, scriptURL, nil, script))
		require.False(t, c.shouldParse(false, scriptURL, nil, script))
		require.True(t, c.shouldParse(false, scriptURL, nil, []byte(`fetch("/api/v2")`)))
	})
	t.Run("same body at another URL is parsed", func(t *testing.T) {
		c := newCrawler(t, false)
		require.True(t, c.shouldParse(false, "https://example.com/a.js", nil, script))
		require.True(t, c.shouldParse(false, "https://cdn.example.com/a.js", nil, script))
	})
	t.Run("same body with another Link header is parsed", func(t *testing.T) {
		c := newCrawler(t, false)
		first := map[string][]string{"Link": {`</a>; rel="preload"`}}
		second := map[string][]string{"link": {`</b>; rel="preload"`}}
		require.True(t, c.shouldParse(false, scriptURL, first, script))
		require.True(t, c.shouldParse(false, scriptURL, second, script))
		require.False(t, c.shouldParse(false, scriptURL, first, script))
	})
	t.Run("same body with another Location header is parsed", func(t *testing.T) {
		c := newCrawler(t, false)
		first := map[string][]string{"Location": {"/a"}}
		second := map[string][]string{"location": {"/b"}}
		require.True(t, c.shouldParse(false, scriptURL, first, script))
		require.True(t, c.shouldParse(false, scriptURL, second, script))
		require.False(t, c.shouldParse(false, scriptURL, first, script))
	})
	t.Run("empty subresource body always parsed", func(t *testing.T) {
		c := newCrawler(t, false)
		require.True(t, c.shouldParse(false, scriptURL, nil, nil))
		require.True(t, c.shouldParse(false, scriptURL, nil, nil))
	})
	t.Run("unique filter disabled", func(t *testing.T) {
		c := newCrawler(t, true)
		require.True(t, c.shouldParse(false, scriptURL, nil, script))
		require.True(t, c.shouldParse(false, scriptURL, nil, script))
	})
	t.Run("repeated main document skipped", func(t *testing.T) {
		c := newCrawler(t, false)
		html := []byte("<html>a</html>")
		require.True(t, c.shouldParse(true, "https://example.com/a", nil, html))
		require.False(t, c.shouldParse(true, "https://example.com/b", nil, html))
	})
}

// A blank page never fires FirstMeaningfulPaint, which used to stall the
// default and networkidle strategies until the request timed out.
func TestBlankPageDoesNotTimeOut(t *testing.T) {
	if path, _ := launcher.LookPath(); path == "" {
		t.Skip("chrome/chromium not found, skipping browser test")
	}

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte(`<html><body></body></html>`))
	}))
	defer srv.Close()

	for _, strategy := range []string{"heuristic", "networkidle"} {
		t.Run(strategy, func(t *testing.T) {
			var results []output.Result
			options, err := types.NewCrawlerOptions(&types.Options{
				MaxDepth:          1,
				FieldScope:        "rdn",
				BodyReadSize:      math.MaxInt,
				Timeout:           8,
				TimeStable:        1,
				Concurrency:       1,
				Parallelism:       1,
				RateLimit:         150,
				Strategy:          "depth-first",
				PageLoadStrategy:  strategy,
				Headless:          true,
				HeadlessNoSandbox: true,
				OnResult:          func(r output.Result) { results = append(results, r) },
			})
			require.NoError(t, err)
			t.Cleanup(func() { _ = options.Close() })

			crawler, err := New(options)
			require.NoError(t, err)
			t.Cleanup(func() { _ = crawler.Close() })

			require.NoError(t, crawler.Crawl(srv.URL))
			require.NotEmpty(t, results)
			require.Empty(t, results[0].Error)
		})
	}
}

// Enabling lifecycle events replays the previous document's networkIdle, and
// an iframe goes idle before its parent; neither may end the wait.
func TestLoadWaitIgnoresStaleAndChildFrameEvents(t *testing.T) {
	_, page := setupBrowserTest(t)
	const slow = 2 * time.Second
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		switch r.URL.Path {
		case "/":
			_, _ = w.Write([]byte(`<html><body><iframe src="/frame"></iframe><img src="/slow"></body></html>`))
		case "/frame":
			_, _ = w.Write([]byte(`<html><body><h1>frame content</h1></body></html>`))
		case "/slow":
			time.Sleep(slow)
		}
	}))
	defer srv.Close()

	start := time.Now()
	wait := waitAnyLifecycleEvent(page, proto.PageLifecycleEventNameFirstMeaningfulPaint, proto.PageLifecycleEventNameNetworkIdle)
	require.NoError(t, page.Navigate(srv.URL))
	wait()
	require.GreaterOrEqual(t, time.Since(start), slow, "wait ended before the main frame loaded")
}

func TestIsStreamingResponse(t *testing.T) {
	tests := []struct {
		name         string
		resourceType proto.NetworkResourceType
		headers      []*proto.FetchHeaderEntry
		expected     bool
	}{
		{
			name:         "EventSource resource type",
			resourceType: proto.NetworkResourceTypeEventSource,
			expected:     true,
		},
		{
			name:         "WebSocket resource type",
			resourceType: proto.NetworkResourceTypeWebSocket,
			expected:     true,
		},
		{
			name:         "SSE text/event-stream content-type",
			resourceType: proto.NetworkResourceTypeXHR,
			headers: []*proto.FetchHeaderEntry{
				{Name: "Content-Type", Value: "text/event-stream"},
			},
			expected: true,
		},
		{
			name:         "SSE with charset parameter",
			resourceType: proto.NetworkResourceTypeFetch,
			headers: []*proto.FetchHeaderEntry{
				{Name: "content-type", Value: "text/event-stream; charset=utf-8"},
			},
			expected: true,
		},
		{
			name:         "Streaming JSON application/stream+json",
			resourceType: proto.NetworkResourceTypeFetch,
			headers: []*proto.FetchHeaderEntry{
				{Name: "Content-Type", Value: "application/stream+json"},
			},
			expected: true,
		},
		{
			name:         "NDJSON application/x-ndjson",
			resourceType: proto.NetworkResourceTypeXHR,
			headers: []*proto.FetchHeaderEntry{
				{Name: "Content-Type", Value: "application/x-ndjson"},
			},
			expected: true,
		},
		{
			name:         "Standard HTML response",
			resourceType: proto.NetworkResourceTypeDocument,
			headers: []*proto.FetchHeaderEntry{
				{Name: "Content-Type", Value: "text/html; charset=utf-8"},
			},
			expected: false,
		},
		{
			name:         "Standard JSON response",
			resourceType: proto.NetworkResourceTypeFetch,
			headers: []*proto.FetchHeaderEntry{
				{Name: "Content-Type", Value: "application/json"},
			},
			expected: false,
		},
		{
			name:         "JavaScript response",
			resourceType: proto.NetworkResourceTypeScript,
			headers: []*proto.FetchHeaderEntry{
				{Name: "Content-Type", Value: "application/javascript"},
			},
			expected: false,
		},
		{
			name:         "Empty headers",
			resourceType: proto.NetworkResourceTypeOther,
			headers:      nil,
			expected:     false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := isStreamingResponse(tt.resourceType, tt.headers)
			require.Equal(t, tt.expected, got)
		})
	}
}

// A page that opens an EventSource used to keep the hijack body read running
// after the visit had already hit -timeout.
func TestEventSourceVisitDoesNotOutliveTimeout(t *testing.T) {
	if path, _ := launcher.LookPath(); path == "" {
		t.Skip("chrome/chromium not found, skipping browser test")
	}

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/events" {
			w.Header().Set("Content-Type", "text/event-stream")
			w.Header().Set("Cache-Control", "no-cache")
			flusher, ok := w.(http.Flusher)
			if !ok {
				return
			}
			ticker := time.NewTicker(50 * time.Millisecond)
			defer ticker.Stop()
			for {
				select {
				case <-r.Context().Done():
					return
				case <-ticker.C:
					_, _ = w.Write([]byte("data: ping\n\n"))
					flusher.Flush()
				}
			}
		}
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte(`<html><body><script>new EventSource("/events")</script>ok</body></html>`))
	}))
	t.Cleanup(srv.Close)

	const timeoutSeconds = 12
	options, err := types.NewCrawlerOptions(&types.Options{
		MaxDepth:          1,
		FieldScope:        "rdn",
		BodyReadSize:      math.MaxInt,
		Timeout:           timeoutSeconds,
		TimeStable:        1,
		Concurrency:       1,
		Parallelism:       1,
		RateLimit:         150,
		Strategy:          "depth-first",
		PageLoadStrategy:  "load",
		Headless:          true,
		HeadlessNoSandbox: true,
		OnResult:          func(output.Result) {},
	})
	require.NoError(t, err)
	t.Cleanup(func() { _ = options.Close() })

	crawler, err := New(options)
	require.NoError(t, err)
	t.Cleanup(func() { _ = crawler.Close() })

	done := make(chan error, 1)
	start := time.Now()
	go func() { done <- crawler.Crawl(srv.URL) }()

	// load does not wait for the open stream. Past this, the visit is stuck
	// in the body read until -timeout.
	limit := 10 * time.Second
	select {
	case err := <-done:
		if err != nil && !errors.Is(err, context.DeadlineExceeded) && !errors.Is(err, context.Canceled) {
			t.Fatal(err)
		}
		if elapsed := time.Since(start); elapsed > limit {
			t.Fatalf("visit took %s, past %s", elapsed, limit)
		}
	case <-time.After(limit):
		t.Fatalf("event stream held the visit open for %s", time.Since(start))
	}
}

// Package hybrid implements the functionality for a hybrid-headless crawler.
// It uses both headless browser and net/http for making requests, and goquery for processing rawand dom-rendered web page HTML.
package hybrid

package hybrid

import (
	"encoding/base64"

	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/proto"
)

// NewHijack create hijack from page.
func NewHijack(page *rod.Page) *Hijack {
	return &Hijack{
		page:    page,
		disable: &proto.FetchDisable{},
	}
}

// HijackHandler type
type HijackHandler = func(e *proto.FetchRequestPaused) error

// Hijack is a hijack handler
type Hijack struct {
	page    *rod.Page
	enable  *proto.FetchEnable
	disable *proto.FetchDisable
	cancel  func()
}

// SetPattern set pattern directly
func (h *Hijack) SetPattern(pattern *proto.FetchRequestPattern) {
	h.enable = &proto.FetchEnable{
		Patterns: []*proto.FetchRequestPattern{pattern},
	}
}

// Start hijack.
func (h *Hijack) Start(handler HijackHandler) func() error {
	if h.enable == nil {
		panic("hijack pattern not set")
	}

	p, cancel := h.page.WithCancel()
	h.cancel = cancel

	err := h.enable.Call(p)
	if err != nil {
		return func() error { return err }
	}

	wait := p.EachEvent(func(e *proto.FetchRequestPaused) {
		if handler != nil {
			err = handler(e)
		}
	})

	return func() error {
		wait()
		return err
	}
}

// Stop
func (h *Hijack) Stop() error {
	if h.cancel != nil {
		h.cancel()
	}
	return h.disable.Call(h.page)
}

// FetchGetResponseBody get request body.
func FetchGetResponseBody(page *rod.Page, e *proto.FetchRequestPaused) ([]byte, error) {
	m := proto.FetchGetResponseBody{
		RequestID: e.RequestID,
	}
	r, err := m.Call(page)
	if err != nil {
		return nil, err
	}

	if !r.Base64Encoded {
		return []byte(r.Body), nil
	}

	bs, err := base64.StdEncoding.DecodeString(r.Body)
	if err != nil {
		return nil, err
	}
	return bs, nil
}

// FetchContinueRequest continue request
func FetchContinueRequest(page *rod.Page, e *proto.FetchRequestPaused) error {
	m := proto.FetchContinueRequest{
		RequestID: e.RequestID,
	}
	return m.Call(page)
}

package hybrid

import (
	"context"

	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/utils/errkit"
)

// Hooks bundles optional per-page lifecycle callbacks invoked by the hybrid
// crawler for every navigated page. All fields are optional; nil callbacks are
// skipped, so the zero value changes nothing.
//
// Both callbacks run synchronously on the goroutine that navigates the page and
// block it for their duration. If Crawl is invoked concurrently on the same
// crawler, the callbacks must themselves be safe for concurrent use.
//
// page is the crawler's own tab, bound to the crawl session's context (it is
// cancelled with the crawl). ctx is cancelled with the crawl and carries a
// -timeout deadline: for BeforeNavigate it is the navigation's own context;
// AfterLoad gets a fresh -timeout budget, so a page that loaded slowly does
// not leave it an almost-expired context. Use page.Context(ctx) or
// page.Timeout(d) to bound any CDP call made from a callback. The page is closed by the crawler
// as soon as the callback returns: callbacks must not retain it, close it, or
// navigate it.
//
// A non-nil error from a callback aborts that request: it is reported exactly
// like any other navigation error (an output.Result carrying the error, plus
// the error writer), and the crawl continues with the next request. Return nil
// for failures that should not cost the page. Callbacks must not panic.
type Hooks struct {
	// BeforeNavigate is invoked after the tab is created and the configured
	// headers/user agent are applied, and before request interception starts
	// and the page navigates to req.URL. It is the place for per-page setup
	// such as page.SetCookies or page.EvalOnNewDocument.
	BeforeNavigate func(ctx context.Context, page *rod.Page, req *navigation.Request) error

	// AfterLoad is invoked once the page has loaded according to the
	// page-load strategy, its rendered HTML has been captured into resp, and
	// before the page is closed. It is only called when resp is non-nil and
	// the request has not already failed. The callback may read the live page
	// (evaluate scripts, take a screenshot) and may attach data to the result
	// via resp.Extra, which is delivered to OnResult and the output writers.
	AfterLoad func(ctx context.Context, page *rod.Page, req *navigation.Request, resp *navigation.Response) error
}

// SetHooks installs per-page lifecycle callbacks on the hybrid crawler. The
// supplied struct is copied, so mutating it after SetHooks returns has no
// effect; call SetHooks again to change the installed hooks. Passing nil clears
// any previously installed hooks. SetHooks is not safe to call concurrently
// with Crawl on the same crawler.
func (c *Crawler) SetHooks(hooks *Hooks) {
	if hooks == nil {
		c.hooks = Hooks{}
		return
	}
	c.hooks = *hooks
}

// runBeforeNavigate invokes hooks.BeforeNavigate when set, wrapping its error
// so the reported failure names the hook and the URL.
func runBeforeNavigate(ctx context.Context, hooks Hooks, page *rod.Page, req *navigation.Request) error {
	cb := hooks.BeforeNavigate
	if cb == nil {
		return nil
	}
	if err := cb(ctx, page, req); err != nil {
		return errkit.Wrap(err, "hybrid: BeforeNavigate hook failed for "+requestURL(req))
	}
	return nil
}

// runAfterLoad invokes hooks.AfterLoad when set, wrapping its error so the
// reported failure names the hook and the URL.
func runAfterLoad(ctx context.Context, hooks Hooks, page *rod.Page, req *navigation.Request, resp *navigation.Response) error {
	cb := hooks.AfterLoad
	if cb == nil {
		return nil
	}
	if err := cb(ctx, page, req, resp); err != nil {
		return errkit.Wrap(err, "hybrid: AfterLoad hook failed for "+requestURL(req))
	}
	return nil
}

func requestURL(req *navigation.Request) string {
	if req == nil {
		return "<nil request>"
	}
	return req.URL
}

