type resultSink struct {
	mu      sync.Mutex
	results []output.Result
}

func (s *resultSink) add(r output.Result) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.results = append(s.results, r)
}

func (s *resultSink) forURL(u string) (output.Result, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, r := range s.results {
		if r.Request != nil && strings.TrimSuffix(r.Request.URL, "/") == strings.TrimSuffix(u, "/") {
			return r, true
		}
	}
	return output.Result{}, false
}

// TestHooks_SeedBeforeNavigateAndReadAfterLoad covers both callbacks on a real
// crawl: a cookie set in BeforeNavigate must reach the server on the very first
// request, and data read from the live page in AfterLoad must arrive on the
// result via Response.Extra.
func TestHooks_SeedBeforeNavigateAndReadAfterLoad(t *testing.T) {
	var sawCookie atomic.Bool
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if c, err := r.Cookie("session"); err == nil && c.Value == "seeded" {
			sawCookie.Store(true)
		}
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte(`<html><body><script>window.__probe = "rendered";</script></body></html>`))
	}))
	defer srv.Close()

	sink := &resultSink{}
	crawler := newHookTestCrawler(t, sink.add)

	var beforeCalls, afterCalls atomic.Int32
	crawler.SetHooks(&Hooks{
		BeforeNavigate: func(ctx context.Context, page *rod.Page, req *navigation.Request) error {
			beforeCalls.Add(1)
			return page.Context(ctx).SetCookies([]*proto.NetworkCookieParam{{
				Name: "session", Value: "seeded", URL: srv.URL,
			}})
		},
		AfterLoad: func(ctx context.Context, page *rod.Page, req *navigation.Request, resp *navigation.Response) error {
			afterCalls.Add(1)
			obj, err := page.Context(ctx).Eval(`() => window.__probe`)
			if err != nil {
				return err
			}
			resp.Extra = map[string]any{"probe": obj.Value.Str(), "depth": req.Depth}
			return nil
		},
	})

	require.NoError(t, crawler.Crawl(srv.URL))

	require.True(t, sawCookie.Load(), "cookie seeded in BeforeNavigate must be sent with the first request")
	require.GreaterOrEqual(t, beforeCalls.Load(), int32(1))
	require.GreaterOrEqual(t, afterCalls.Load(), int32(1))

	res, ok := sink.forURL(srv.URL)
	require.True(t, ok, "expected a result for the seed URL")
	require.Empty(t, res.Error)
	require.NotNil(t, res.Response)
	require.Equal(t, "rendered", res.Response.Extra["probe"])
	require.Equal(t, 0, res.Response.Extra["depth"])
}

// TestHooks_BeforeNavigateErrorSkipsRequest verifies that a failing
// BeforeNavigate aborts the request before any traffic is sent and that the
// failure is reported on the result, naming the URL.
func TestHooks_BeforeNavigateErrorSkipsRequest(t *testing.T) {
	var hits atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits.Add(1)
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte(`<html><body>hi</body></html>`))
	}))
	defer srv.Close()

	sink := &resultSink{}
	crawler := newHookTestCrawler(t, sink.add)

	var afterCalled atomic.Bool
	crawler.SetHooks(&Hooks{
		BeforeNavigate: func(context.Context, *rod.Page, *navigation.Request) error {
			return errors.New("no session available")
		},
		AfterLoad: func(context.Context, *rod.Page, *navigation.Request, *navigation.Response) error {
			afterCalled.Store(true)
			return nil
		},
	})

	require.NoError(t, crawler.Crawl(srv.URL))

	require.Zero(t, hits.Load(), "no request may be sent when BeforeNavigate fails")
	require.False(t, afterCalled.Load(), "AfterLoad must not run for an aborted request")
	res, ok := sink.forURL(srv.URL)
	require.True(t, ok, "the aborted request must still be reported")
	require.Contains(t, res.Error, "BeforeNavigate hook failed")
	require.Contains(t, res.Error, "no session available")
	require.Contains(t, res.Error, srv.URL)
}

// TestHooks_AfterLoadErrorIsReported verifies that a failing AfterLoad is
// reported like any other navigation error.
func TestHooks_AfterLoadErrorIsReported(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte(`<html><body>hi</body></html>`))
	}))
	defer srv.Close()

	sink := &resultSink{}
	crawler := newHookTestCrawler(t, sink.add)
	crawler.SetHooks(&Hooks{
		AfterLoad: func(context.Context, *rod.Page, *navigation.Request, *navigation.Response) error {
			return errors.New("capture failed")
		},
	})

	require.NoError(t, crawler.Crawl(srv.URL))

	res, ok := sink.forURL(srv.URL)
	require.True(t, ok)
	require.Contains(t, res.Error, "AfterLoad hook failed")
	require.Contains(t, res.Error, "capture failed")
}

// TestHooks_AfterLoadGetsFreshTimeout verifies that AfterLoad receives its own
// full timeout budget rather than whatever the navigation left over. A slow
// page that loads just inside the timeout must not hand AfterLoad a context
// that is already (nearly) expired, or every hook call on it fails.
func TestHooks_AfterLoadGetsFreshTimeout(t *testing.T) {
	const slowLoad = 1500 * time.Millisecond
	// navigation alone takes about 2.4s locally, so a tight timeout fails on
	// slower CI runners before AfterLoad runs
	const timeout = 10 * time.Second
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(slowLoad)
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte(`<html><body>slow</body></html>`))
	}))
	defer srv.Close()

	if path, _ := launcher.LookPath(); path == "" {
		t.Skip("chrome/chromium not found, skipping browser test")
	}
	sink := &resultSink{}
	opts := hookTestOptions(sink.add)
	opts.Timeout = int(timeout.Seconds())
	options, err := types.NewCrawlerOptions(opts)
	require.NoError(t, err)
	t.Cleanup(func() { _ = options.Close() })
	crawler, err := New(options)
	require.NoError(t, err)
	t.Cleanup(func() { _ = crawler.Close() })

	var remaining atomic.Int64
	var ctxErr atomic.Value
	crawler.SetHooks(&Hooks{
		AfterLoad: func(ctx context.Context, _ *rod.Page, _ *navigation.Request, _ *navigation.Response) error {
			if deadline, ok := ctx.Deadline(); ok {
				remaining.Store(int64(time.Until(deadline)))
			}
			if err := ctx.Err(); err != nil {
				ctxErr.Store(err)
			}
			return nil
		},
	})

	require.NoError(t, crawler.Crawl(srv.URL))

	res, ok := sink.forURL(srv.URL)
	require.True(t, ok)
	require.Empty(t, res.Error)
	require.Nil(t, ctxErr.Load(), "AfterLoad context must be live")
	// The navigation consumed at least slowLoad of the timeout; a fresh budget
	// leaves well over what the navigation's own context could have left.
	require.Greater(t, time.Duration(remaining.Load()), timeout-slowLoad+250*time.Millisecond,
		"AfterLoad must get a fresh timeout, not the navigation's leftover")
}

package hybrid

import (
	"context"
	"fmt"
	"os"
	"time"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/katana/pkg/engine/common"
	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/cdp"
	"github.com/projectdiscovery/rod/lib/launcher"
	"github.com/projectdiscovery/rod/lib/launcher/flags"
	"github.com/projectdiscovery/rod/lib/proto"
	"github.com/projectdiscovery/utils/chromeshell"
	"github.com/projectdiscovery/utils/errkit"
	urlutil "github.com/projectdiscovery/utils/url"
)

// Crawler is a standard crawler instance
type Crawler struct {
	*common.Shared

	browser        *rod.Browser
	chromeLauncher *launcher.Launcher // nil when attached via ChromeWSUrl
	cdpWS          *cdp.WebSocket
	// TODO: Remove the Chrome PID kill code in favor of using Leakless(true).
	// This change will be made if there are no complaints about zombie Chrome processes.
	// References:
	// https://github.com/projectdiscovery/katana/issues/632
	// https://github.com/projectdiscovery/httpx/issues/1425
	// previousPIDs map[int32]struct{} // track already running PIDs
	tempDir string
	// hooks holds the optional per-page lifecycle callbacks; see SetHooks.
	hooks Hooks
}

// proxyBypassList returns the Chrome proxy bypass list to use for proxy.
//
// Chrome bypasses the proxy for localhost, 127.0.0.0/8, [::1] and link-local
// addresses by default, even when one is configured. "<-loopback>" is the
// documented way to SUBTRACT that implicit rule, so a configured proxy is
// honoured for local targets too -- the case where an intercepting proxy is
// most often used. Empty when no proxy is set, since there is nothing to
// bypass.
func proxyBypassList(proxy string) string {
	if proxy == "" {
		return ""
	}
	return "<-loopback>"
}

// New returns a new standard crawler instance
func New(options *types.CrawlerOptions) (*Crawler, error) {
	var dataStore string
	var err error
	if options.Options.ChromeDataDir != "" {
		dataStore = options.Options.ChromeDataDir
	} else {
		dataStore, err = os.MkdirTemp("", "katana-*")
		if err != nil {
			return nil, errkit.Wrap(err, "hybrid: could not create temporary directory")
		}
	}

	// previousPIDs := processutil.FindProcesses(processutil.IsChromeProcess)

	var launcherURL string
	var chromeLauncher *launcher.Launcher

	if options.Options.ChromeWSUrl != "" {
		launcherURL = options.Options.ChromeWSUrl
	} else {
		// create new chrome launcher instance
		chromeLauncher, err = buildChromeLauncher(options, dataStore)
		if err != nil {
			return nil, err
		}

		// launch chrome headless process
		launcherURL, err = chromeLauncher.Launch()
		if err != nil {
			return nil, err
		}
	}

	// Construct the CDP client here rather than using rod.New().ControlURL(...)
	// so the websocket handle survives into Close(). rod hides it in an
	// unexported field, and without it the connection can never be closed --
	// see Close() for why that leaks. StartWithURL, which Connect calls, is
	// exactly this.
	dialCtx, dialCancel := context.WithTimeout(context.Background(), 30*time.Second)
	cdpWS := &cdp.WebSocket{}
	wsErr := cdpWS.Connect(dialCtx, launcherURL, nil)
	dialCancel()
	if wsErr != nil {
		if chromeLauncher != nil {
			chromeLauncher.Kill()
		}
		return nil, errkit.Wrap(wsErr, fmt.Sprintf("hybrid: failed to connect to chrome instance at %s", launcherURL))
	}
	browser := rod.New().Client(cdp.New().Start(cdpWS))
	if browserErr := browser.Connect(); browserErr != nil {
		_ = cdpWS.Close()
		if chromeLauncher != nil {
			chromeLauncher.Kill()
		}
		return nil, errkit.Wrap(browserErr, fmt.Sprintf("hybrid: failed to connect to chrome instance at %s", launcherURL))
	}

	owned := false
	defer func() {
		if owned {
			return
		}
		if ownsBrowser(browser, chromeLauncher) {
			_ = browser.Close()
		}
		_ = cdpWS.Close()
		if chromeLauncher != nil {
			chromeLauncher.Kill()
		}
	}()

	// create a new browser instance (default to incognito mode)
	if !options.Options.HeadlessNoIncognito {
		// Create the browser context directly rather than via browser.Incognito():
		// rod's helper takes no proxy argument, and Options.Proxy otherwise never
		// reaches a browser attached through ChromeWSUrl, because the chrome
		// launcher -- its only proxy path -- does not run in that case.
		res, err := proto.TargetCreateBrowserContext{
			ProxyServer: options.Options.Proxy,
			// "<-loopback>" SUBTRACTS Chrome's implicit proxy bypass.
			//
			// Chrome always bypasses the proxy for localhost, 127.0.0.0/8,
			// [::1] and link-local, even when one is configured; the only way
			// to disable that built-in rule is to subtract it here. Without
			// this, `-proxy` is silently ignored for exactly the local targets
			// people most often put behind an intercepting proxy, and the
			// crawl still succeeds -- so the traffic simply never appears.
			//
			// Only applied when a proxy was actually requested: with no proxy
			// there is nothing to bypass, and the token would be meaningless.
			ProxyBypassList: proxyBypassList(options.Options.Proxy),
		}.Call(browser)
		if err != nil {
			return nil, errkit.Wrap(err, "hybrid: failed to create incognito browser")
		}
		incognito := *browser
		incognito.BrowserContextID = res.BrowserContextID
		browser = &incognito
	}

	shared, err := common.NewShared(options)
	if err != nil {
		return nil, errkit.Wrap(err, "hybrid")
	}

	crawler := &Crawler{
		Shared:         shared,
		browser:        browser,
		chromeLauncher: chromeLauncher,
		cdpWS:          cdpWS,
		// previousPIDs: previousPIDs,
		tempDir: dataStore,
	}
	owned = true

	return crawler, nil
}

func ownsBrowser(browser *rod.Browser, chromeLauncher *launcher.Launcher) bool {
	return chromeLauncher != nil || browser.BrowserContextID != ""
}

// BrowserContextID returns the id of the browser context this crawler created
// in New, or "" if it has no browser. It lets an embedding program dispose the
// context out of band: when a crawl dies without running Close, the context
// otherwise stays resident in a shared, long-lived browser.
func (c *Crawler) BrowserContextID() string {
	if c.browser == nil {
		return ""
	}
	return string(c.browser.BrowserContextID)
}

// Close closes the crawler process
func (c *Crawler) Close() error {
	c.CloseIdleConnections()
	if c.browser != nil && ownsBrowser(c.browser, c.chromeLauncher) {
		_ = c.browser.Close()
	}
	if c.cdpWS != nil {
		// Close AFTER browser.Close, which dispatches
		// Target.disposeBrowserContext over this same socket.
		//
		// rod's initEvents goroutine blocks on `for e := range client.Event()`,
		// and that channel closes only when cdp's read loop errors -- which
		// happens only when the CONNECTION closes, not on context cancellation
		// (the websocket Read is a blocking socket read). Disposing the browser
		// context does not close the connection, so against a browser attached
		// via ChromeWSUrl -- where there is no launcher to kill -- every crawl
		// left the socket and its goroutines behind for the browser's lifetime.
		_ = c.cdpWS.Close()
	}
	if c.chromeLauncher != nil {
		c.chromeLauncher.Kill()
	}
	if c.Options.Options.ChromeDataDir == "" {
		if err := os.RemoveAll(c.tempDir); err != nil {
			return err
		}
	}
	// processutil.CloseProcesses(processutil.IsChromeProcess, c.previousPIDs)
	return nil
}

// Crawl crawls a URL with the specified options
func (c *Crawler) Crawl(rootURL string) error {
	crawlSession, err := c.NewCrawlSessionWithURL(rootURL)
	if err != nil {
		return errkit.Wrap(err, "hybrid")
	}
	crawlSession.Browser = c.browser

	defer crawlSession.Close()

	gologger.Info().Msgf("Started headless crawling for => %v", rootURL)
	if err := c.Do(crawlSession, c.navigateRequest); err != nil {
		return errkit.Wrap(err, "hybrid")
	}
	return nil
}

// Do executes the crawling loop with browser-safe concurrency.
// Unlike the base implementation, this uses sequential processing (concurrency=1)
// because Chrome DevTools Protocol operations cannot safely run concurrently
// on the same browser instance. Multiple concurrent page operations cause
// race conditions, navigation conflicts, and network interception issues.
func (c *Crawler) Do(crawlSession *common.CrawlSession, doRequest common.DoRequestFunc) error {
	for item := range crawlSession.Queue.PopWithContext(crawlSession.Ctx) {
		if ctxErr := crawlSession.Ctx.Err(); ctxErr != nil {
			return ctxErr
		}

		if req, inScope, ok := c.AcceptRequest(crawlSession, item); ok {
			c.visit(crawlSession, req, inScope, doRequest)
		}
		crawlSession.Queue.Done()
	}
	return nil
}

// visit requests one page and enqueues its links.
func (c *Crawler) visit(crawlSession *common.CrawlSession, req *navigation.Request, inScope bool, doRequest common.DoRequestFunc) {
	// Race Take() against the session context so the loop doesn't
	// block on a limiter tick when the crawl has been cancelled.
	//
	// Note: when the session is cancelled mid-Take, this inner
	// goroutine outlives the loop iteration and stays blocked on
	// the limiter until the next tick or until RateLimit.Stop() is
	// called by CrawlerOptions.Close(). The leak is bounded by
	// Close() and acceptable.
	if crawlSession.Ctx.Err() != nil {
		return
	}
	reqHost := common.RequestHost(req.URL, crawlSession.Hostname)
	takeDone := make(chan struct{})
	go func() {
		if c.Options.HostRateLimit != nil {
			c.TakeHostRateLimit(reqHost)
		} else if c.Options.RateLimit != nil {
			c.Options.RateLimit.Take()
		}
		close(takeDone)
	}()
	select {
	case <-crawlSession.Ctx.Done():
		return
	case <-takeDone:
	}
	c.ApplyBackoff(reqHost)

	if crawlSession.Ctx.Err() != nil {
		return
	}

	if c.Options.Options.Delay > 0 {
		select {
		case <-crawlSession.Ctx.Done():
			return
		case <-time.After(time.Duration(c.Options.Options.Delay) * time.Second):
		}
	}

	if c.Options.Options.MaxDomainPages > 0 {
		counter := c.DomainCounter(crawlSession.Hostname)
		if counter.Add(1) > int64(c.Options.Options.MaxDomainPages) {
			return
		}
	}

	resp, err := doRequest(crawlSession, req)

	respHost := common.ResponseHost(resp, reqHost)
	if resp != nil && common.IsThrottled(resp.StatusCode) {
		c.RecordThrottle(respHost, resp.StatusCode)
	} else if resp != nil {
		c.RecordSuccess(respHost)
	}

	if inScope {
		c.Output(req, resp, err)
	}

	if resp != nil && c.StopForBlock(resp.Resp, req.URL) {
		return
	}
	if err != nil {
		gologger.Warning().Msgf("Could not request seed URL %s: %s\n", req.URL, err)
		outputError := &output.Error{
			Timestamp: time.Now(),
			Endpoint:  req.RequestURL(),
			Source:    req.Source,
			Error:     err.Error(),
		}
		_ = c.Options.OutputWriter.WriteErr(outputError)
		return
	}
	if resp == nil || resp.Resp == nil || resp.Reader == nil {
		return
	}
	if c.Options.Options.DisableRedirects && resp.IsRedirect() {
		return
	}

	navigationRequests := c.Options.Parser.ParseResponse(resp)
	c.Enqueue(crawlSession.Queue, navigationRequests...)
}

// buildChromeLauncher builds a new chrome launcher instance
func buildChromeLauncher(options *types.CrawlerOptions, dataStore string) (*launcher.Launcher, error) {
	chromeLauncher := launcher.New().
		Leakless(true).
		Set("disable-gpu", "true").
		Set("ignore-certificate-errors", "true").
		Set("ignore-certificate-errors", "1").
		Set("disable-crash-reporter", "true").
		Set("disable-notifications", "true").
		Set("hide-scrollbars", "true").
		Set("window-size", fmt.Sprintf("%d,%d", 1080, 1920)).
		Set("mute-audio", "true").
		Delete("use-mock-keychain").
		UserDataDir(dataStore)

	if options.Options.UseInstalledChrome {
		if options.Options.SystemChromePath != "" {
			chromeLauncher.Bin(options.Options.SystemChromePath)
		} else {
			if chromePath, hasChrome := launcher.LookPath(); hasChrome {
				chromeLauncher.Bin(chromePath)
			} else {
				return nil, errkit.New("hybrid: the chrome browser is not installed")
			}
		}
	} else if options.Options.SystemChromePath != "" {
		chromeLauncher.Bin(options.Options.SystemChromePath)
	} else if !options.Options.ShowBrowser && chromeshell.Supported() {
		// Prefer chrome-headless-shell on linux/amd64 for headless crawls; skip
		// when headed since the shell binary cannot show a UI.
		if shellPath, err := chromeshell.Ensure(); err == nil {
			chromeLauncher.Bin(shellPath)
		}
	}

	if options.Options.ShowBrowser {
		chromeLauncher = chromeLauncher.Headless(false)
	} else {
		chromeLauncher = chromeLauncher.Headless(true)
	}

	if options.Options.HeadlessNoSandbox {
		chromeLauncher.Set("no-sandbox", "true")
	}

	if options.Options.Proxy != "" {
		proxyURL, err := urlutil.Parse(options.Options.Proxy)
		if err != nil {
			return nil, err
		}
		chromeLauncher.Set("proxy-server", proxyURL.String())
		// Same implicit-bypass problem as the browser-context path above: without
		// this, a launched Chrome ignores the proxy for loopback targets.
		// Applied whenever a proxy is set, including -hh (Headless is mutually
		// exclusive with HeadlessHybrid, so the previous Headless guard never ran).
		chromeLauncher.Set("proxy-bypass-list", proxyBypassList(options.Options.Proxy))
	}

	for k, v := range options.Options.ParseHeadlessOptionalArguments() {
		chromeLauncher.Set(flags.Flag(k), v)
	}

	return chromeLauncher, nil
}

package hybrid

import "testing"

// Chrome bypasses the proxy for localhost/127.0.0.0/8/[::1]/link-local even
// when one is configured, so a proxy alone does not capture a crawl of a local
// target -- the exact setup used when pointing katana at an app through an
// intercepting proxy. "<-loopback>" subtracts that built-in rule.
func TestProxyBypassList(t *testing.T) {
	if got := proxyBypassList("http://127.0.0.1:8080"); got != "<-loopback>" {
		t.Errorf("proxyBypassList with a proxy = %q, want %q; without it Chrome silently skips the proxy for local targets", got, "<-loopback>")
	}
	// No proxy means nothing to bypass; sending the token anyway would be a
	// meaningless flag on every default crawl.
	if got := proxyBypassList(""); got != "" {
		t.Errorf("proxyBypassList without a proxy = %q, want empty", got)
	}
}

package hybrid

import (
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/katana/pkg/engine/common"
	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/katana/pkg/utils/extensions"
	"github.com/projectdiscovery/katana/pkg/utils/queue"
	"github.com/projectdiscovery/katana/pkg/utils/scope"
	"github.com/projectdiscovery/ratelimit"
	"github.com/stretchr/testify/require"
)

type nopOutputWriter struct{}

func (w *nopOutputWriter) Close() error                 { return nil }
func (w *nopOutputWriter) Write(*output.Result) error   { return nil }
func (w *nopOutputWriter) WriteErr(*output.Error) error { return nil }
func (w *nopOutputWriter) GetResultCount() int64        { return 0 }

func newTestHybridCrawler(ctx context.Context, limiter *ratelimit.AutoLimiter) *Crawler {
	scopeManager, _ := scope.NewManager(nil, nil, "", true)
	crawlerOpts := &types.CrawlerOptions{
		Options: &types.Options{
			MaxDepth: 2,
			Strategy: "depth-first",
			Context:  ctx,
		},
		OutputWriter:        &nopOutputWriter{},
		HostRateLimit:       limiter,
		ScopeManager:        scopeManager,
		ExtensionsValidator: extensions.NewValidator(nil, nil, true),
	}
	shared, err := common.NewShared(crawlerOpts)
	if err != nil {
		panic(err)
	}
	return &Crawler{Shared: shared}
}

func TestHybridVisitUsesRequestHost(t *testing.T) {
	t.Run("distinct request hosts do not share seed limiter", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()

		limiter := ratelimit.NewAutoLimiter(ctx, ratelimit.WithMaxCount(1), ratelimit.WithDuration(500*time.Millisecond))
		defer limiter.Stop()

		c := newTestHybridCrawler(ctx, limiter)
		q, err := queue.New("depth-first")
		require.NoError(t, err)
		for _, u := range []string{
			"https://alpha.example.com/1",
			"https://beta.example.com/1",
			"https://gamma.example.com/1",
		} {
			q.Push(&navigation.Request{
				Method:         http.MethodGet,
				URL:            u,
				Depth:          0,
				SkipValidation: true,
			}, 0)
		}

		session := &common.CrawlSession{
			Ctx:        ctx,
			CancelFunc: cancel,
			Hostname:   "seed.example.com",
			Queue:      q,
		}

		var count atomic.Int32
		start := time.Now()
		err = c.Do(session, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			count.Add(1)
			return &navigation.Response{StatusCode: http.StatusOK}, nil
		})
		elapsed := time.Since(start)

		require.NoError(t, err)
		require.Equal(t, int32(3), count.Load())
		require.Less(t, elapsed, 300*time.Millisecond)
	})

	t.Run("throttle applies to request host rather than seed host", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()

		c := newTestHybridCrawler(ctx, nil)

		q1, err := queue.New("depth-first")
		require.NoError(t, err)
		q1.Push(&navigation.Request{
			Method:         http.MethodGet,
			URL:            "https://throttled.example.com/api",
			Depth:          0,
			SkipValidation: true,
		}, 0)
		s1 := &common.CrawlSession{Ctx: ctx, CancelFunc: cancel, Hostname: "seed.example.com", Queue: q1}
		err = c.Do(s1, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			return &navigation.Response{StatusCode: http.StatusTooManyRequests}, nil
		})
		require.NoError(t, err)

		// Visiting the seed host afterwards must NOT be delayed by throttled.example.com's 429.
		q2, err := queue.New("depth-first")
		require.NoError(t, err)
		q2.Push(&navigation.Request{
			Method:         http.MethodGet,
			URL:            "https://seed.example.com/ok",
			Depth:          0,
			SkipValidation: true,
		}, 0)
		s2 := &common.CrawlSession{Ctx: ctx, CancelFunc: cancel, Hostname: "seed.example.com", Queue: q2}
		start := time.Now()
		err = c.Do(s2, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			return &navigation.Response{StatusCode: http.StatusOK}, nil
		})
		require.NoError(t, err)
		require.Less(t, time.Since(start), 200*time.Millisecond)

		// Visiting the throttled host again must incur backoff even under a clean session.
		q3, err := queue.New("depth-first")
		require.NoError(t, err)
		q3.Push(&navigation.Request{
			Method:         http.MethodGet,
			URL:            "https://throttled.example.com/retry",
			Depth:          0,
			SkipValidation: true,
		}, 0)
		s3 := &common.CrawlSession{Ctx: ctx, CancelFunc: cancel, Hostname: "seed.example.com", Queue: q3}
		start = time.Now()
		err = c.Do(s3, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			return &navigation.Response{StatusCode: http.StatusOK}, nil
		})
		require.NoError(t, err)
		require.GreaterOrEqual(t, time.Since(start), 900*time.Millisecond)
	})

	t.Run("redirected 429 attributes throttle to responding host", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()

		c := newTestHybridCrawler(ctx, nil)

		q1, err := queue.New("depth-first")
		require.NoError(t, err)
		q1.Push(&navigation.Request{
			Method:         http.MethodGet,
			URL:            "https://redirector.example.com/start",
			Depth:          0,
			SkipValidation: true,
		}, 0)
		s1 := &common.CrawlSession{Ctx: ctx, CancelFunc: cancel, Hostname: "seed.example.com", Queue: q1}
		err = c.Do(s1, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			return &navigation.Response{
				StatusCode: http.StatusTooManyRequests,
				Resp: &http.Response{
					StatusCode: http.StatusTooManyRequests,
					Request:    httptest.NewRequest(http.MethodGet, "https://Target.Example.COM/final", nil),
				},
			}, nil
		})
		require.NoError(t, err)

		// Redirector host should remain fast, while target host should incur backoff.
		q2, err := queue.New("depth-first")
		require.NoError(t, err)
		q2.Push(&navigation.Request{
			Method:         http.MethodGet,
			URL:            "https://redirector.example.com/next",
			Depth:          0,
			SkipValidation: true,
		}, 0)
		s2 := &common.CrawlSession{Ctx: ctx, CancelFunc: cancel, Hostname: "seed.example.com", Queue: q2}
		start := time.Now()
		err = c.Do(s2, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			return &navigation.Response{StatusCode: http.StatusOK}, nil
		})
		require.NoError(t, err)
		require.Less(t, time.Since(start), 200*time.Millisecond)

		q3, err := queue.New("depth-first")
		require.NoError(t, err)
		q3.Push(&navigation.Request{
			Method:         http.MethodGet,
			URL:            "https://target.example.com/retry",
			Depth:          0,
			SkipValidation: true,
		}, 0)
		s3 := &common.CrawlSession{Ctx: ctx, CancelFunc: cancel, Hostname: "seed.example.com", Queue: q3}
		start = time.Now()
		err = c.Do(s3, func(_ *common.CrawlSession, _ *navigation.Request) (*navigation.Response, error) {
			return &navigation.Response{StatusCode: http.StatusOK}, nil
		})
		require.NoError(t, err)
		require.GreaterOrEqual(t, time.Since(start), 900*time.Millisecond)
	})
}

