func TestDataURIFiltering(t *testing.T) {
	parsed, _ := urlutil.Parse("https://example.com/test")

	t.Run("data-uri-filtering", func(t *testing.T) {
		// Test various HTML elements with data URIs to ensure they're filtered out by ParseResponse
		htmlContent := `
			<img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg==">
			<a href="data:text/html,<h1>Hello</h1>">Data Link</a>
			<link href="data:text/css,body{color:red}">
			<script src="data:application/javascript,console.log('test')"></script>
			<iframe src="data:text/html,<p>Test</p>"></iframe>
			<object data="data:application/pdf,test"></object>
			<embed src="data:application/x-shockwave-flash,test">
			<audio src="data:audio/mp3,test"></audio>
			<video src="data:video/mp4,test"></video>
			<a href="mailto:test@example.com">Email Link</a>
			<a href="javascript:alert('test')">JS Link</a>
		`

		documentReader, _ := goquery.NewDocumentFromReader(strings.NewReader(htmlContent))
		resp := &navigation.Response{
			Resp:   &http.Response{Request: &http.Request{URL: parsed.URL}},
			Reader: documentReader,
		}

		// Test the main ParseResponse function to ensure all invalid URIs are filtered out
		responseParser := NewResponseParser()
		navigationRequests := responseParser.ParseResponse(resp)
		for _, req := range navigationRequests {
			require.False(t, strings.HasPrefix(req.URL, "data:"),
				"Found data URI in ParseResponse results: %s", req.URL)
			require.False(t, strings.HasPrefix(req.URL, "mailto:"),
				"Found mailto URI in ParseResponse results: %s", req.URL)
			require.False(t, strings.HasPrefix(req.URL, "javascript:"),
				"Found javascript URI in ParseResponse results: %s", req.URL)
		}

		// Ensure we have 0 requests since all should be filtered
		require.Equal(t, 0, len(navigationRequests), "Expected all invalid URIs to be filtered out")
	})
}

// A PNG's pixel bytes contain byte sequences that pageBodyRegex matches -- most
// commonly "./6" -- and the mined string then resolves against the image's own
// URL, so the crawler requests a sibling resource the site never served
// (e.g. /images/products/10.png -> /images/products/6, 404).
//
// katana's extension denylist cannot prevent this: it rejects the ".png" the
// noise came FROM, while the mined path is extensionless and passes.
func TestBodyScrapeEndpointsParser_ContentTypeGate(t *testing.T) {
	parsed, _ := urlutil.Parse("https://example.com/images/products/10.png")

	// Minimal PNG header plus a chunk of bytes containing the "./6" sequence
	// that a real image yields; the regex only needs the literal to be present
	// in the body.
	binaryBody := "\x89PNG\r\n\x1a\n\x00\x10\xff\xfe\"./6\"\x00\x01\x02\x03"

	t.Run("binary body is not scraped", func(t *testing.T) {
		resp := &navigation.Response{
			Resp: &http.Response{
				Request: &http.Request{URL: parsed.URL},
				Header:  http.Header{"Content-Type": []string{"image/png"}},
			},
			Body: binaryBody,
		}
		require.Empty(t, bodyScrapeEndpointsParser(resp), "a binary response body must not be mined for endpoints")
	})

	// No declared type: the BODY decides, not the absence of a header. Binary
	// content is still refused, by its magic bytes.
	t.Run("untyped binary body is not scraped", func(t *testing.T) {
		resp := &navigation.Response{
			Resp: &http.Response{Request: &http.Request{URL: parsed.URL}},
			Body: binaryBody,
		}
		require.Empty(t, bodyScrapeEndpointsParser(resp), "an untyped binary body must not be mined for endpoints")
	})

	// ... and untyped TEXT is still scraped. Servers on embedded devices and
	// appliance interfaces routinely omit Content-Type; skipping those would
	// trade one silent coverage gap for another.
	t.Run("untyped text body is scraped", func(t *testing.T) {
		htmlParsed, _ := urlutil.Parse("https://example.com/index.html")
		resp := &navigation.Response{
			Resp: &http.Response{Request: &http.Request{URL: htmlParsed.URL}},
			Body: `<html><body><a href="/x">y</a><script>var u = "./test/endpoint.php";</script></body></html>`,
		}
		navigationRequests := bodyScrapeEndpointsParser(resp)
		require.NotEmpty(t, navigationRequests, "an untyped HTML body must still be scraped")
		require.Equal(t, "https://example.com/test/endpoint.php", navigationRequests[0].URL, "could not get correct url")
	})

	// application/octet-stream is the generic "I do not know" default, so it
	// gets the same treatment as no header at all: sniff the body.
	t.Run("octet-stream text body is scraped", func(t *testing.T) {
		htmlParsed, _ := urlutil.Parse("https://example.com/app.js")
		resp := &navigation.Response{
			Resp: &http.Response{
				Request: &http.Request{URL: htmlParsed.URL},
				Header:  http.Header{"Content-Type": []string{"application/octet-stream"}},
			},
			Body: `window.location = "./test/endpoint.php";`,
		}
		require.NotEmpty(t, bodyScrapeEndpointsParser(resp), "a mislabelled text body must still be scraped")
	})

	t.Run("octet-stream binary body is not scraped", func(t *testing.T) {
		resp := &navigation.Response{
			Resp: &http.Response{
				Request: &http.Request{URL: parsed.URL},
				Header:  http.Header{"Content-Type": []string{"application/octet-stream"}},
			},
			Body: binaryBody,
		}
		require.Empty(t, bodyScrapeEndpointsParser(resp), "a mislabelled binary body must not be mined for endpoints")
	})

	// SVG is XML text carrying href/xlink:href and possibly a <script>, so it
	// is scraped despite the image/ prefix. Not an accident of the "+xml"
	// match -- pinned here on purpose.
	t.Run("image/svg+xml is scraped", func(t *testing.T) {
		svgParsed, _ := urlutil.Parse("https://example.com/logo.svg")
		resp := &navigation.Response{
			Resp: &http.Response{
				Request: &http.Request{URL: svgParsed.URL},
				Header:  http.Header{"Content-Type": []string{"image/svg+xml"}},
			},
			Body: `<svg xmlns="http://www.w3.org/2000/svg"><a href="./test/endpoint.php"/></svg>`,
		}
		var got []string
		for _, req := range bodyScrapeEndpointsParser(resp) {
			got = append(got, req.URL)
		}
		// The xmlns declaration is mined too, so assert membership rather than
		// position.
		require.Contains(t, got, "https://example.com/test/endpoint.php", "an SVG is XML text and must still be scraped")
	})

	// The parser must keep working for everything it is actually for.
	for _, contentType := range []string{
		"text/html; charset=utf-8",
		"text/plain",
		"application/javascript",
		"application/json",
		"application/xhtml+xml",
	} {
		t.Run(contentType+" is scraped", func(t *testing.T) {
			htmlParsed, _ := urlutil.Parse("https://example.com/index.html")
			resp := &navigation.Response{
				Resp: &http.Response{
					Request: &http.Request{URL: htmlParsed.URL},
					Header:  http.Header{"Content-Type": []string{contentType}},
				},
				Body: `window.location = "./test/endpoint.php";`,
			}
			navigationRequests := bodyScrapeEndpointsParser(resp)
			require.NotEmpty(t, navigationRequests, "a textual body must still be scraped")
			require.Equal(t, "https://example.com/test/endpoint.php", navigationRequests[0].URL, "could not get correct url")
		})
	}

	t.Run("application/jsonfoo is not scraped", func(t *testing.T) {
		resp := &navigation.Response{
			Resp: &http.Response{
				Request: &http.Request{URL: parsed.URL},
				Header:  http.Header{"Content-Type": []string{"application/jsonfoo"}},
			},
			Body: binaryBody,
		}
		require.Empty(t, bodyScrapeEndpointsParser(resp), "a type that only contains application/json as a prefix must not be mined")
	})

	t.Run("octet-stream with +json profile is sniffed", func(t *testing.T) {
		resp := &navigation.Response{
			Resp: &http.Response{
				Request: &http.Request{URL: parsed.URL},
				Header:  http.Header{"Content-Type": []string{`application/octet-stream; profile="+json"`}},
			},
			Body: binaryBody,
		}
		require.Empty(t, bodyScrapeEndpointsParser(resp), "a +json parameter on octet-stream must not force scraping")
	})
}

package standard

import (
	"bytes"
	"context"
	"io"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"

	"github.com/PuerkitoBio/goquery"
	"github.com/projectdiscovery/katana/pkg/engine/common"
	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/utils"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/utils/errkit"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

// makeRequest makes a request to a URL returning a response interface.
func (c *Crawler) makeRequest(s *common.CrawlSession, request *navigation.Request) (*navigation.Response, error) {
	response := &navigation.Response{
		Depth:        request.Depth + 1,
		RootHostname: s.Hostname,
	}
	ctx := context.WithValue(s.Ctx, navigation.Depth{}, request.Depth)
	httpReq, err := http.NewRequestWithContext(ctx, request.Method, request.URL, nil)
	if err != nil {
		return response, err
	}
	if request.Body != "" && request.Method != "GET" {
		httpReq.Body = io.NopCloser(strings.NewReader(request.Body))
	}
	req, err := retryablehttp.FromRequest(httpReq)
	if err != nil {
		return response, err
	}
	req.Header.Set("User-Agent", utils.WebUserAgent())

	// Set the headers for the request.
	for k, v := range request.Headers {
		req.Header.Set(k, v)
		if k == "Host" {
			req.Host = v
		}
	}

	for k, v := range c.Headers {
		req.Header.Set(k, v)
		if k == "Host" {
			req.Host = v
		}
	}

	// Apply cookies
	if c.Jar != nil {
		cookies := c.Jar.Cookies(req.Request.URL)
		for _, cookie := range cookies {
			req.AddCookie(cookie)
		}
	}

	resp, err := s.HttpClient.Do(req)
	if resp != nil {
		defer func() {
			if resp.Body != nil && resp.StatusCode != http.StatusSwitchingProtocols {
				_, _ = io.Copy(io.Discard, resp.Body)
			}
			_ = resp.Body.Close()
		}()
	}

	// Collect cookies from the response
	if c.Jar != nil && resp != nil {
		c.Jar.SetCookies(req.Request.URL, resp.Cookies())
	}

	rawRequestBytes, _ := req.Dump()
	request.Raw = string(rawRequestBytes)

	if err != nil {
		return response, err
	}

	// If the response is empty, perform a defensive return.
	if resp == nil {
		return response, errkit.New("standard: nil response from http client")
	}

	if resp.StatusCode == http.StatusSwitchingProtocols {
		return response, nil
	}

	limitReader := io.LimitReader(resp.Body, int64(c.Options.Options.BodyReadSize))
	data, err := io.ReadAll(limitReader)
	if err != nil {
		return response, err
	}

	// A repeated challenge body is not new content, but it is still a block.
	// Keep the response so the caller can say which host was blocked.
	if common.DetectBlock(resp) != "" {
		resp.Body = io.NopCloser(bytes.NewReader(data))
		rawResponseBytes, _ := httputil.DumpResponse(resp, true)
		response.Raw = string(rawResponseBytes)
		response.Resp = resp
		response.Body = string(data)
		response.StatusCode = resp.StatusCode
		response.Headers = utils.FlattenHeaders(resp.Header)
		return response, nil
	}

	// Skip unique content filtering if disabled
	if !c.Options.Options.DisableUniqueFilter {
		if !c.Options.UniqueFilter.UniqueContent(data) {
			return &navigation.Response{}, nil
		}
	}
	if c.Options.ContentSimilarity != nil && !c.Options.ContentSimilarity.Accept(data) {
		return &navigation.Response{}, nil
	}

	if c.Options.Wappalyzer != nil {
		technologies := c.Options.Wappalyzer.Fingerprint(resp.Header, data)
		response.Technologies = mapsutil.GetKeys(technologies)
	}

	response.KnowledgeBase = c.Options.BuildKnowledgeBase(string(data), resp.Request, resp)

	// Restore the read data to resp.Body for further use.
	resp.Body = io.NopCloser(strings.NewReader(string(data)))

	response.Body = string(data)
	response.Resp = resp

	// First, attempt to parse using goquery. If the parsing fails, simply return safely (to avoid accessing response.Reader before checking err).
	doc, err := goquery.NewDocumentFromReader(bytes.NewReader(data))
	if err != nil {
		// Even if the parsing fails, try to attach the original response for debugging purposes.
		rawResponseBytes, _ := httputil.DumpResponse(resp, true)
		response.Raw = string(rawResponseBytes)
		return response, errkit.Wrap(err, "standard: could not make document from reader")
	}
	// Only set the `response.Reader` and its URL after the parsing is successful to avoid accessing a nil pointer.
	response.Reader = doc
	response.Reader.Url, _ = url.Parse(request.URL)

	response.StatusCode = resp.StatusCode
	response.Headers = utils.FlattenHeaders(resp.Header)
	if c.Options.Options.FormExtraction {
		response.Forms = append(response.Forms, utils.ParseFormFields(response.Reader)...)
	}

	// Use the actual length of the read data as ContentLength
	resp.ContentLength = int64(len(data))
	response.ContentLength = resp.ContentLength

	rawResponseBytes, _ := httputil.DumpResponse(resp, true)
	response.Raw = string(rawResponseBytes)

	return response, nil
}

// Package standard implements the functionality for a non-headless crawler.
// It uses net/http for making requests and goquery for scraping web page HTML.
package standard

package standard

import (
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/katana/pkg/engine/common"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/projectdiscovery/utils/errkit"
)

// Crawler is a standard crawler instance
type Crawler struct {
	*common.Shared
}

// New returns a new standard crawler instance
func New(options *types.CrawlerOptions) (*Crawler, error) {
	shared, err := common.NewShared(options)
	if err != nil {
		return nil, errkit.Wrap(err, "standard")
	}
	return &Crawler{Shared: shared}, nil
}

// Close closes the crawler process
func (c *Crawler) Close() error {
	c.CloseIdleConnections()
	return nil
}

// Crawl crawls a URL with the specified options
func (c *Crawler) Crawl(rootURL string) error {
	crawlSession, err := c.NewCrawlSessionWithURL(rootURL)
	if err != nil {
		return errkit.Wrap(err, "standard")
	}
	defer crawlSession.Close()
	gologger.Info().Msgf("Started standard crawling for => %v", rootURL)
	if err := c.Do(crawlSession, c.makeRequest); err != nil {
		return errkit.Wrap(err, "standard")
	}
	return nil
}

package standard

import (
	"fmt"
	"math"
	"net"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
	"time"

	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/projectdiscovery/katana/pkg/types"
	"github.com/stretchr/testify/require"
)

// connTracker counts the server side connections that are still open.
type connTracker struct {
	mu   sync.Mutex
	open map[net.Conn]struct{}
}

func (c *connTracker) track(conn net.Conn, state http.ConnState) {
	c.mu.Lock()
	defer c.mu.Unlock()
	switch state {
	case http.StateNew:
		c.open[conn] = struct{}{}
	case http.StateClosed, http.StateHijacked:
		delete(c.open, conn)
	}
}

func (c *connTracker) count() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return len(c.open)
}

func newTrackedServer(t *testing.T) (*httptest.Server, *connTracker) {
	t.Helper()
	tracker := &connTracker{open: make(map[net.Conn]struct{})}
	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/robots.txt":
			w.Header().Set("Content-Type", "text/plain")
			_, _ = fmt.Fprint(w, "User-agent: *\nDisallow: /private\n")
		case "/":
			w.Header().Set("Content-Type", "text/html")
			_, _ = fmt.Fprint(w, `<html><body><a href="/next">next</a></body></html>`)
		default:
			w.Header().Set("Content-Type", "text/html")
			_, _ = fmt.Fprint(w, `<html><body>ok</body></html>`)
		}
	}))
	srv.Config.ConnState = tracker.track
	srv.Start()
	t.Cleanup(srv.Close)
	return srv, tracker
}

func newTestCrawler(t *testing.T, knownFiles string) *Crawler {
	t.Helper()
	options, err := types.NewCrawlerOptions(&types.Options{
		MaxDepth:     3,
		FieldScope:   "rdn",
		BodyReadSize: math.MaxInt,
		Timeout:      1,
		Retries:      1,
		Concurrency:  2,
		Parallelism:  2,
		RateLimit:    150,
		Strategy:     "breadth-first",
		KnownFiles:   knownFiles,
		Silent:       true,
		OnResult:     func(output.Result) {},
	})
	require.NoError(t, err)
	t.Cleanup(func() { _ = options.Close() })

	crawler, err := New(options)
	require.NoError(t, err)
	return crawler
}

func requireNoOpenConnections(t *testing.T, tracker *connTracker) {
	t.Helper()
	require.Eventually(t, func() bool { return tracker.count() == 0 }, 2*time.Second, 20*time.Millisecond,
		"connections still open: %d", tracker.count())
}

func TestCrawlClosesIdleConnections(t *testing.T) {
	srv, tracker := newTrackedServer(t)
	crawler := newTestCrawler(t, "")
	t.Cleanup(func() { _ = crawler.Close() })

	for i := 0; i < 3; i++ {
		require.NoError(t, crawler.Crawl(srv.URL))
		requireNoOpenConnections(t, tracker)
	}
}

func TestCloseClosesKnownFilesIdleConnections(t *testing.T) {
	srv, tracker := newTrackedServer(t)
	crawler := newTestCrawler(t, "robotstxt")

	require.NoError(t, crawler.Crawl(srv.URL))
	require.NoError(t, crawler.Close())
	requireNoOpenConnections(t, tracker)
}

// Package knowledgebase defines the Extractor interface implemented by
// per-class detectors that contribute structured facts to a response's
// KnowledgeBase map. Each extractor owns a single top-level key, named by
// Name(), to keep outputs collision-free across detectors.
package knowledgebase

import "net/http"

// Extractor mines structured facts from a crawled response. Extractors that
// only need the body can ignore req and resp; extractors that classify by
// request shape (method, headers, URL) use them.
//
// Implementations MUST treat body, req, and resp as read-only: do not mutate
// req/resp headers, URL, or body, and do not read resp.Body. The response
// body has already been drained upstream and is passed as the body argument;
// resp is supplied for status, header, and Request access only.
type Extractor interface {
	Name() string
	Extract(body string, req *http.Request, resp *http.Response) map[string]any
}

// Package endpoints is a knowledgebase.Extractor that classifies a crawled
// request as an API endpoint (REST, GraphQL, SOAP, AJAX/XHR) by inspecting
// method, URL, headers, and content types. Emits per-response, one entry
// per qualifying request.
//
// Output schema (all values strings unless noted):
//
//	class        : "rest" | "graphql" | "soap" | "xhr"
//	method       : uppercase HTTP verb
//	url          : request URL with userinfo and fragment stripped
//	content_type : lowercased media type without parameters (optional)
//	auth         : lowercased auth scheme, e.g. "bearer" / "basic" (optional)
//	params       : []string of query parameter names in first-seen order (optional)
//
// The extractor is read-only with respect to its inputs: it MUST NOT mutate
// req or resp (headers, body, URL).
package endpoints

import (
	"net/http"
	"net/url"
	"strings"
)

const Name = "endpoints"

type Extractor struct{}

func New() *Extractor { return &Extractor{} }

func (e *Extractor) Name() string { return Name }

func (e *Extractor) Extract(_ string, req *http.Request, resp *http.Response) map[string]any {
	if req == nil {
		return nil
	}

	method := strings.ToUpper(req.Method)
	urlStr := safeURLString(req.URL)
	pathLower := ""
	if req.URL != nil {
		pathLower = strings.ToLower(req.URL.Path)
	}
	reqCT := req.Header.Get("Content-Type")
	respCT := ""
	if resp != nil {
		respCT = resp.Header.Get("Content-Type")
	}
	soapAction := req.Header.Get("SOAPAction")

	class := classify(method, pathLower, reqCT, respCT, soapAction)
	if class == "" {
		return nil
	}

	out := map[string]any{
		"class":  class,
		"method": method,
		"url":    urlStr,
	}
	if ct := primaryContentType(respCT, reqCT); ct != "" {
		out["content_type"] = ct
	}
	if scheme := authScheme(req.Header.Get("Authorization")); scheme != "" {
		out["auth"] = scheme
	}
	if req.URL != nil {
		if params := paramNames(req.URL.RawQuery); len(params) > 0 {
			out["params"] = params
		}
	}
	return out
}

// classify decides which endpoint family a request belongs to. Decision tree
// (first match wins):
//
//  1. SOAPAction header or soap+xml content-type on either side -> "soap"
//  2. "graphql" path component or application/graphql content-type -> "graphql"
//  3. JSON/XML body and (mutating verb OR API-looking path)       -> "rest"
//  4. JSON GET to a non-API path                                  -> "xhr"
//  5. form-urlencoded or multipart on a mutating verb             -> "rest"
//  6. otherwise                                                   -> "" (skip)
//
// pathLower is the lowercased URL path (no scheme/host/query) so that
// substring/segment checks aren't fooled by hostnames or query params.
func classify(method, pathLower, reqCT, respCT, soapAction string) string {
	if soapAction != "" || containsAny(reqCT, "soap+xml") || containsAny(respCT, "soap+xml") {
		return "soap"
	}
	if hasPathSegment(pathLower, "graphql") ||
		containsAny(reqCT, "application/graphql") ||
		containsAny(respCT, "application/graphql") {
		return "graphql"
	}

	isJSON := containsAny(reqCT, "application/json") || containsAny(respCT, "application/json")
	isXML := containsAny(reqCT, "application/xml") || containsAny(respCT, "application/xml")
	isForm := containsAny(reqCT, "application/x-www-form-urlencoded") || containsAny(reqCT, "multipart/form-data")

	apiPath := matchesAPIPath(pathLower)
	mutating := isMutatingVerb(method)

	if (isJSON || isXML) && (mutating || apiPath) {
		return "rest"
	}
	if isJSON && method == "GET" {
		return "xhr"
	}
	if isForm && mutating {
		return "rest"
	}
	return ""
}

// apiPathSegments are substrings whose presence in the URL path strongly
// suggests an API endpoint. Kept intentionally generous; the classifier still
// requires a structured content-type or a mutating verb to actually return
// "rest", so individual false positives don't surface as endpoints on their
// own.
var apiPathSegments = []string{
	"/api/", "/v1/", "/v2/", "/v3/", "/rest/", "/rpc/",
	"/jsonrpc", "/.well-known/", "/oauth/", "/openapi",
}

func matchesAPIPath(pathLower string) bool {
	for _, seg := range apiPathSegments {
		if strings.Contains(pathLower, seg) {
			return true
		}
	}
	return false
}

// hasPathSegment reports whether name appears as a full "/"-separated segment
// of pathLower (e.g. "/graphql", "/api/graphql", but not "/notgraphql/blob").
func hasPathSegment(pathLower, name string) bool {
	for _, seg := range strings.Split(pathLower, "/") {
		if seg == name {
			return true
		}
	}
	return false
}

func isMutatingVerb(method string) bool {
	switch method {
	case "POST", "PUT", "PATCH", "DELETE":
		return true
	}
	return false
}

func containsAny(haystack, needle string) bool {
	if haystack == "" {
		return false
	}
	return strings.Contains(strings.ToLower(haystack), needle)
}

func primaryContentType(respCT, reqCT string) string {
	pick := respCT
	if pick == "" {
		pick = reqCT
	}
	if pick == "" {
		return ""
	}
	if i := strings.Index(pick, ";"); i >= 0 {
		pick = pick[:i]
	}
	return strings.TrimSpace(strings.ToLower(pick))
}

// authScheme returns the lowercased scheme of an Authorization header (the
// token before the first space, e.g. "bearer" or "basic"). Returns "" when
// the header is empty or doesn't follow the "<scheme> <credentials>" shape,
// in which case the auth field is omitted from the output to avoid emitting
// noise for non-RFC headers.
func authScheme(authHeader string) string {
	authHeader = strings.TrimSpace(authHeader)
	if authHeader == "" {
		return ""
	}
	if i := strings.Index(authHeader, " "); i > 0 {
		return strings.ToLower(authHeader[:i])
	}
	return ""
}

// paramNames returns the deduplicated names of query parameters in first-seen
// order. Dedup is intentionally case-sensitive: "Q" and "q" are kept as two
// names because most APIs treat parameter casing as significant.
func paramNames(rawQuery string) []string {
	if rawQuery == "" {
		return nil
	}
	seen := map[string]struct{}{}
	var out []string
	for _, kv := range strings.Split(rawQuery, "&") {
		if kv == "" {
			continue
		}
		name := kv
		if i := strings.Index(kv, "="); i >= 0 {
			name = kv[:i]
		}
		if name == "" {
			continue
		}
		if _, ok := seen[name]; ok {
			continue
		}
		seen[name] = struct{}{}
		out = append(out, name)
	}
	return out
}

// safeURLString returns u as a string with userinfo and fragment stripped so
// credentials embedded in the URL never reach knowledgebase output.
func safeURLString(u *url.URL) string {
	if u == nil {
		return ""
	}
	clone := *u
	clone.User = nil
	clone.Fragment = ""
	clone.RawFragment = ""
	return clone.String()
}

package endpoints

import (
	"net/http"
	"net/url"
	"reflect"
	"strings"
	"testing"
)

func mustRequest(t *testing.T, method, rawURL string, headers map[string]string) *http.Request {
	t.Helper()
	u, err := url.Parse(rawURL)
	if err != nil {
		t.Fatalf("parse URL: %v", err)
	}
	req := &http.Request{Method: method, URL: u, Header: http.Header{}}
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	return req
}

func responseWithCT(ct string) *http.Response {
	h := http.Header{}
	if ct != "" {
		h.Set("Content-Type", ct)
	}
	return &http.Response{Header: h}
}

func TestExtract_GraphQLByPath(t *testing.T) {
	e := New()
	req := mustRequest(t, "POST", "https://example.com/graphql", map[string]string{
		"Content-Type": "application/json",
	})
	out := e.Extract("", req, responseWithCT("application/json"))
	if out == nil {
		t.Fatal("expected entry, got nil")
	}
	if out["class"] != "graphql" {
		t.Errorf("class = %v, want graphql", out["class"])
	}
}

func TestExtract_SOAPByHeader(t *testing.T) {
	e := New()
	req := mustRequest(t, "POST", "https://example.com/ws/UserService", map[string]string{
