)

const (
	EnvEndpoint      = "KATANA_TRAFFIC_ENDPOINT"
	EnvToken         = "KATANA_TRAFFIC_TOKEN"
	EnvAttributes    = "KATANA_TRAFFIC_ATTRIBUTES"
	EnvAllowInsecure = "KATANA_TRAFFIC_ALLOW_INSECURE"
	// EnvIncludeCredentials set to 1 exports credential headers verbatim.
	EnvIncludeCredentials = "KATANA_TRAFFIC_INCLUDE_CREDENTIALS"

	batchSize = 100
	// maxBatchBytes flushes a batch early to stay under common request
	// body limits of collectors and proxies.
	maxBatchBytes = 1 << 20
	queueSize     = 2048
	maxBodyBytes  = 64 * 1024
	flushInterval = time.Second
	maxAttributes = 32
	maxAttrValue  = 1024

	redactedValue = "[REDACTED]"
)

var (
	retryDelays = []time.Duration{time.Second, 2 * time.Second, 4 * time.Second}
	// drainTimeout bounds how long Close waits for queued events to be sent.
	drainTimeout = 10 * time.Second
	attrKeyRule  = regexp.MustCompile(`^[a-z][a-z0-9_]{0,63}$`)
	// reservedKeys are event fields owned by the exporter.
	reservedKeys = map[string]struct{}{
		"id": {}, "timestamp": {}, "captured_at": {}, "source_type": {},
		"process": {}, "request": {}, "response": {},
	}
	// credentialHeaders are lower-cased header names redacted by default.
	credentialHeaders = map[string]struct{}{
		"authorization": {}, "proxy-authorization": {}, "cookie": {}, "set-cookie": {},
		"x-api-key": {}, "x-auth-token": {}, "x-csrf-token": {}, "x-xsrf-token": {},
	}
)

// Config controls an exporter. Endpoint and Token must come from trusted
// process configuration, never from crawled content.
type Config struct {
	Endpoint      string
	Token         string
	Attributes    map[string]string
	AllowInsecure bool
	// IncludeCredentials exports credential headers instead of redacting them.
	IncludeCredentials bool
	HTTPClient         *http.Client
}

type writer struct {
	output.Writer
	config     Config
	attributes []byte
	events     chan json.RawMessage
	done       chan struct{}
	// ctx is cancelled to abandon delivery once drainTimeout expires.
	ctx    context.Context
	cancel context.CancelFunc

	mu        sync.RWMutex
	closed    bool
	closeOnce sync.Once
	dropped   atomic.Int64
	err       error
}

type event struct {
	ID         string   `json:"id"`
	Timestamp  string   `json:"timestamp"`
	CapturedAt string   `json:"captured_at"`
	SourceType string   `json:"source_type"`
	Process    string   `json:"process"`
	Request    message  `json:"request"`
	Response   response `json:"response"`
}

type message struct {
	Method        string            `json:"method,omitempty"`
	FullURL       string            `json:"full_url,omitempty"`
	HTTPVersion   string            `json:"http_version"`
	Headers       map[string]string `json:"headers"`
	BodyPreview   string            `json:"body_preview,omitempty"`
	BodySHA256    string            `json:"body_sha256,omitempty"`
	BodySize      int64             `json:"body_size,omitempty"`
	BodyTruncated bool              `json:"body_truncated,omitempty"`
}

type response struct {
	Status      int    `json:"status"`
	StatusText  string `json:"status_text,omitempty"`
	ContentType string `json:"content_type,omitempty"`
	message
}

// Enabled reports whether traffic export is configured in the environment,
// even partially.
func Enabled() bool {
	return strings.TrimSpace(os.Getenv(EnvEndpoint)) != "" || strings.TrimSpace(os.Getenv(EnvToken)) != ""
}

// Wrap returns inner unchanged when export is not configured. On a
// configuration error it also returns inner, so a bad setting never breaks
// crawling output.
func Wrap(inner output.Writer) (output.Writer, error) {
	endpoint := strings.TrimSpace(os.Getenv(EnvEndpoint))
	token := strings.TrimSpace(os.Getenv(EnvToken))
	if endpoint == "" && token == "" {
		return inner, nil
	}
	if endpoint == "" || token == "" {
		return inner, fmt.Errorf("both %s and %s are required", EnvEndpoint, EnvToken)
	}
	var attributes map[string]string
	if raw := strings.TrimSpace(os.Getenv(EnvAttributes)); raw != "" {
		if err := json.Unmarshal([]byte(raw), &attributes); err != nil {
			return inner, fmt.Errorf("%s must be a JSON object of string values", EnvAttributes)
		}
	}
	w, err := New(inner, Config{
		Endpoint:           endpoint,
		Token:              token,
		Attributes:         attributes,
		AllowInsecure:      os.Getenv(EnvAllowInsecure) == "1",
		IncludeCredentials: os.Getenv(EnvIncludeCredentials) == "1",
	})
	if err != nil {
		return inner, err
	}
	return w, nil
}

// New wraps inner with an exporter for config.
func New(inner output.Writer, config Config) (output.Writer, error) {
	if err := validateEndpoint(config.Endpoint, config.AllowInsecure); err != nil {
		return nil, err
	}
	if config.Token == "" {
		return nil, errors.New("traffic export token is required")
	}
	attributes, err := encodeAttributes(config.Attributes)
	if err != nil {
		return nil, err
	}
	if config.HTTPClient == nil {
		transport := http.DefaultTransport.(*http.Transport).Clone()
		// Do not route the bearer token through an inherited HTTP_PROXY.
		transport.Proxy = nil
		config.HTTPClient = &http.Client{
			Transport: transport,
			Timeout:   15 * time.Second,
		}
	} else {
		// Copy so the caller's client keeps its own redirect policy.
		client := *config.HTTPClient
		config.HTTPClient = &client
	}
	// Never follow redirects: Go would resend the bearer token, even from
	// https to http on the same host.
	config.HTTPClient.CheckRedirect = func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	}
	ctx, cancel := context.WithCancel(context.Background())
	w := &writer{
		Writer:     inner,
		config:     config,
		attributes: attributes,
		events:     make(chan json.RawMessage, queueSize),
		done:       make(chan struct{}),
		ctx:        ctx,
		cancel:     cancel,
	}
	go w.run()
	return w, nil
}

func validateEndpoint(endpoint string, allowInsecure bool) error {
	parsed, err := url.Parse(endpoint)
	if err != nil || parsed.Hostname() == "" {
		return errors.New("invalid traffic export endpoint")
	}
	if parsed.User != nil || parsed.RawQuery != "" || parsed.Fragment != "" {
		return errors.New("traffic export endpoint cannot contain credentials, query, or fragment")
	}
	switch parsed.Scheme {
	case "https":
		return nil
	case "http":
		if allowInsecure || isLoopback(parsed.Hostname()) {
			return nil
		}
		return errors.New("plain http traffic export is allowed only for loopback unless explicitly enabled")
	default:
		return errors.New("traffic export endpoint must use http or https")
	}
}

func isLoopback(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// encodeAttributes validates attributes and returns them as JSON object
// members (without braces) to append to every event.
func encodeAttributes(attributes map[string]string) ([]byte, error) {
	if len(attributes) == 0 {
		return nil, nil
	}
	if len(attributes) > maxAttributes {
		return nil, fmt.Errorf("at most %d traffic export attributes are allowed", maxAttributes)
	}
	for key, value := range attributes {
		if _, reserved := reservedKeys[key]; reserved || !attrKeyRule.MatchString(key) {
			return nil, fmt.Errorf("invalid traffic export attribute %q", key)
		}
		if len(value) > maxAttrValue {
			return nil, fmt.Errorf("traffic export attribute %q exceeds %d bytes", key, maxAttrValue)
		}
	}
	encoded, err := json.Marshal(attributes)
	if err != nil {
		return nil, err
	}
	return encoded[1 : len(encoded)-1], nil
}

// Capture queues an observed exchange for export. It never blocks: when the
// queue is full the exchange is dropped and counted.
func (w *writer) Capture(result *output.Result) {
	encoded, ok := w.encode(result)
	if !ok {
		return
	}
	w.mu.RLock()
	defer w.mu.RUnlock()
	if w.closed {
		w.dropped.Add(1)
		return
	}
	select {
	case w.events <- encoded:
	default:
		w.dropped.Add(1)
	}
}

func (w *writer) Close() error {
	innerErr := w.Writer.Close()
	w.closeOnce.Do(func() {
		w.mu.Lock()
		w.closed = true
		close(w.events)
		w.mu.Unlock()
		timer := time.NewTimer(drainTimeout)
		defer timer.Stop()
		select {
		case <-w.done:
		case <-timer.C:
			// Abandon in-flight and queued batches rather than delay exit.
			w.cancel()
			<-w.done
		}
		w.cancel()
		if dropped := w.dropped.Load(); dropped > 0 {
			if w.err != nil {
				w.err = fmt.Errorf("traffic export incomplete: %d events dropped: %w", dropped, w.err)
			} else {
				w.err = fmt.Errorf("traffic export incomplete: %d events dropped", dropped)
			}
		}
	})
	if innerErr != nil {
		return innerErr
	}
	return w.err
}

func (w *writer) run() {
	defer close(w.done)
	ticker := time.NewTicker(flushInterval)
	defer ticker.Stop()
	batch := make([]json.RawMessage, 0, batchSize)
	batchBytes := 0
	flush := func() {
		if len(batch) == 0 {
			return
		}
		err := errDrainTimeout
		if w.ctx.Err() == nil {
			err = w.post(batch)
		}
		if err != nil {
			// Drop only this batch; later batches may still be delivered.
			w.dropped.Add(int64(len(batch)))
			if w.err == nil {
				w.err = err
				gologger.Error().Msgf("Traffic export batch failed: %s\n", err)
			}
		}
		batch = batch[:0]
		batchBytes = 0
	}
	for {
		select {
		case ev, ok := <-w.events:
			if !ok {
				flush()
				return
			}
			batch = append(batch, ev)
			batchBytes += len(ev)
			if len(batch) >= batchSize || batchBytes >= maxBatchBytes {
				flush()
			}
		case <-ticker.C:
			flush()
		}
	}
}

// encode serialises a result synchronously, since callers mutate it (omit
// flags) after Capture returns. Results without a real HTTP response,
// such as errors or URLs discovered but not fetched, are skipped.
func (w *writer) encode(result *output.Result) (json.RawMessage, bool) {
	if result == nil || result.Request == nil || !result.HasResponse() {
		return nil, false
	}
	req, resp := result.Request, result.Response
	timestamp := result.Timestamp
	if timestamp.IsZero() {
		timestamp = time.Now()
	}
	contentType := resp.Resp.Header.Get("Content-Type")
	responseBody := resp.Body
	if !isTextual(contentType) || !utf8.ValidString(responseBody) {
		// JSON cannot carry these bytes verbatim, so a preview would not
		// match body_sha256.
		responseBody = ""
	}
	requestVersion := "HTTP/1.1"
	if resp.Resp.Request != nil && resp.Resp.Request.Proto != "" {
		requestVersion = resp.Resp.Request.Proto
	}
	responseVersion := valueOr(resp.Resp.Proto, "HTTP/1.1")
	ev := event{
		ID:         uuid.NewString(),
		Timestamp:  timestamp.UTC().Format(time.RFC3339Nano),
		CapturedAt: time.Now().UTC().Format(time.RFC3339Nano),
		SourceType: "cli",
		Process:    "katana",
		Request:    newMessage(req.Method, req.URL, requestVersion, w.headers(req.Headers), req.Body),
		Response: response{
			Status:      resp.StatusCode,
			StatusText:  http.StatusText(resp.StatusCode),
			ContentType: contentType,
			message:     newMessage("", "", responseVersion, w.headers(resp.Headers), responseBody),
		},
	}
	if responseBody == "" && resp.Body != "" {
		// Binary or non-UTF-8 body: report its size and hash without a preview.
		ev.Response.BodySHA256 = sha256Hex(resp.Body)
		ev.Response.BodySize = int64(len(resp.Body))
		ev.Response.BodyTruncated = true
	}
	if resp.ContentLength > ev.Response.BodySize {
		ev.Response.BodySize = resp.ContentLength
		ev.Response.BodyTruncated = true
	}
	encoded, err := json.Marshal(ev)
	if err != nil {
		return nil, false
	}
	if len(w.attributes) > 0 {
		encoded = append(append(append(encoded[:len(encoded)-1], ','), w.attributes...), '}')
	}
	return encoded, true
}

// headers copies headers, redacting credential values unless the exporter
// is configured to include them.
func (w *writer) headers(headers map[string]string) map[string]string {
	copied := make(map[string]string, len(headers))
	for key, value := range headers {
		if _, ok := credentialHeaders[strings.ToLower(key)]; ok && !w.config.IncludeCredentials {
			value = redactedValue
		}
		copied[key] = value
	}
	return copied
}

func newMessage(method, fullURL, version string, headers map[string]string, body string) message {
	m := message{
		Method:      method,
		FullURL:     fullURL,
		HTTPVersion: version,
		Headers:     headers,
		BodySHA256:  sha256Hex(body),
		BodySize:    int64(len(body)),
	}
	switch {
	case !utf8.ValidString(body):
		m.BodyTruncated = true
	case len(body) > maxBodyBytes:
		// Cut on a rune boundary so the preview stays valid UTF-8.
		m.BodyPreview = strings.ToValidUTF8(body[:maxBodyBytes], "")
		m.BodyTruncated = true
	default:
		m.BodyPreview = body
	}
	return m
}

func (w *writer) post(events []json.RawMessage) error {
	payload, err := json.Marshal(struct {
		BatchID string            `json:"batch_id"`
		Events  []json.RawMessage `json:"events"`
	}{uuid.NewString(), events})
	if err != nil {
		return err
	}
	for attempt := 0; ; attempt++ {
		retryable, err := w.postOnce(payload)
		if err == nil {
			return nil
		}
		if w.ctx.Err() != nil {
			return errDrainTimeout
		}
		if !retryable || attempt >= len(retryDelays) {
			return err
		}
		timer := time.NewTimer(retryDelays[attempt])
		select {
		case <-timer.C:
		case <-w.ctx.Done():
			timer.Stop()
			return errDrainTimeout
		}
	}
}

var errDrainTimeout = errors.New("traffic export did not finish before shutdown deadline")

func (w *writer) postOnce(payload []byte) (retryable bool, err error) {
	ctx, cancel := context.WithTimeout(w.ctx, 15*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, w.config.Endpoint, bytes.NewReader(payload))
	if err != nil {
		return false, errors.New("could not create traffic export request")
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+w.config.Token)
	resp, err := w.config.HTTPClient.Do(req)
	if err != nil {
		return true, errors.New("traffic export request failed")
	}
	_, _ = io.Copy(io.Discard, resp.Body)
	_ = resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		retryable := resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= 500
		return retryable, fmt.Errorf("traffic collector rejected batch with status %d", resp.StatusCode)
	}
	return false, nil
}

func sha256Hex(value string) string {
	if value == "" {
		return ""
	}
	digest := sha256.Sum256([]byte(value))
	return hex.EncodeToString(digest[:])
}

func isTextual(contentType string) bool {
	if contentType == "" {
		return true
	}
	lower := strings.ToLower(contentType)
	for _, marker := range []string{"text/", "json", "xml", "javascript", "graphql", "x-www-form-urlencoded"} {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}

func valueOr(value, fallback string) string {
	if value == "" {
		return fallback
	}
	return value
}

package export

import (
	"encoding/json"
	"io"
	"net/http"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/output"
	"github.com/stretchr/testify/require"
)

const testEndpoint = "http://127.0.0.1:8080/traffic"

func TestWrapFromEnvironment(t *testing.T) {
	inner := &recordingWriter{}

	t.Run("disabled returns inner", func(t *testing.T) {
		t.Setenv(EnvEndpoint, "")
		t.Setenv(EnvToken, "")
		w, err := Wrap(inner)
		require.NoError(t, err)
		require.Same(t, inner, w)
	})

	t.Run("partial configuration keeps inner", func(t *testing.T) {
		t.Setenv(EnvEndpoint, "https://collector.example/traffic")
		t.Setenv(EnvToken, "")
		w, err := Wrap(inner)
		require.Error(t, err)
		require.Same(t, inner, w)
	})

	t.Run("invalid attributes keep inner", func(t *testing.T) {
		t.Setenv(EnvEndpoint, "https://collector.example/traffic")
		t.Setenv(EnvToken, "test-token")
		t.Setenv(EnvAttributes, `{"run":1}`)
		w, err := Wrap(inner)
		require.ErrorContains(t, err, EnvAttributes)
		require.Same(t, inner, w)
	})
}

func TestValidateEndpoint(t *testing.T) {
	tests := []struct {
		endpoint      string
		allowInsecure bool
		wantError     bool
	}{
		{endpoint: "https://collector.example/traffic"},
		{endpoint: "http://127.0.0.1:8080/traffic"},
		{endpoint: "http://localhost:8080/traffic"},
		{endpoint: "http://collector.internal/traffic", allowInsecure: true},
		{endpoint: "http://collector.example/traffic", wantError: true},
		{endpoint: "https://user@collector.example/traffic", wantError: true},
		{endpoint: "https://collector.example/traffic?next=elsewhere", wantError: true},
		{endpoint: "https://collector.example/traffic#fragment", wantError: true},
		{endpoint: "file:///traffic", wantError: true},
	}
	for _, test := range tests {
		t.Run(test.endpoint, func(t *testing.T) {
			err := validateEndpoint(test.endpoint, test.allowInsecure)
			if test.wantError {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
			}
		})
	}
}

func TestEncodeAttributes(t *testing.T) {
	_, err := encodeAttributes(map[string]string{"request": "x"})
	require.Error(t, err)
	_, err = encodeAttributes(map[string]string{"Bad-Key": "x"})
	require.Error(t, err)
	_, err = encodeAttributes(map[string]string{"run_id": strings.Repeat("a", maxAttrValue+1)})
	require.ErrorContains(t, err, "exceeds")
	encoded, err := encodeAttributes(nil)
	require.NoError(t, err)
	require.Nil(t, encoded)
}

func TestWriterCaptureAndDeliver(t *testing.T) {
	type delivery struct {
		path, auth, batchID string
		events              []map[string]any
	}
	received := make(chan delivery, 1)
	client := &http.Client{Transport: roundTripFunc(func(r *http.Request) (*http.Response, error) {
		var batch struct {
			BatchID string           `json:"batch_id"`
			Events  []map[string]any `json:"events"`
		}
		if err := json.NewDecoder(r.Body).Decode(&batch); err != nil {
			return nil, err
		}
		received <- delivery{path: r.URL.Path, auth: r.Header.Get("Authorization"), batchID: batch.BatchID, events: batch.Events}
		return &http.Response{StatusCode: http.StatusOK, Body: io.NopCloser(strings.NewReader(`{}`))}, nil
	})}

	inner := &recordingWriter{}
	w, err := New(inner, Config{
		Endpoint:   testEndpoint,
		Token:      "test-token",
		Attributes: map[string]string{"run_id": "run-1"},
		HTTPClient: client,
	})
	require.NoError(t, err)

	httpReq, _ := http.NewRequest(http.MethodPost, "https://target.example/api", nil)
	httpReq.Proto = "HTTP/2.0"
	body := strings.Repeat("a", maxBodyBytes+10)
	result := &output.Result{
		Timestamp: time.Date(2026, time.September, 24, 12, 30, 0, 0, time.UTC),
		Request: &navigation.Request{
			Method:  http.MethodPost,
			URL:     "https://target.example/api",
			Headers: map[string]string{"Content-Type": "application/json"},
			Body:    `{"key":"value"}`,
		},
		Response: &navigation.Response{
			StatusCode: http.StatusCreated,
			Headers:    navigation.Headers{"Content-Type": "application/json"},
			Body:       body,
			Resp: &http.Response{
				StatusCode: http.StatusCreated,
				Proto:      "HTTP/2.0",
				Header:     http.Header{"Content-Type": []string{"application/json"}},
				Request:    httpReq,
			},
		},
	}
	capturer := w.(interface{ Capture(*output.Result) })
	capturer.Capture(result)
	// Results without a fetched response are not exported.
	capturer.Capture(&output.Result{Request: &navigation.Request{Method: http.MethodGet, URL: "https://target.example/found"}})
	// Write only delegates to the inner writer.
	require.NoError(t, w.Write(result))
	require.NoError(t, w.Close())

	require.Len(t, inner.results, 1)
	require.True(t, inner.closed)

	got := <-received
	require.NotEmpty(t, got.batchID)
	require.Equal(t, "/traffic", got.path)
	require.Equal(t, "Bearer test-token", got.auth)
	require.Len(t, got.events, 1)
	ev := got.events[0]
	require.Equal(t, "run-1", ev["run_id"])
	require.Equal(t, "cli", ev["source_type"])
	require.Equal(t, "katana", ev["process"])
	require.Equal(t, "2026-09-24T12:30:00Z", ev["timestamp"])

	req := ev["request"].(map[string]any)
	require.Equal(t, "POST", req["method"])
	require.Equal(t, "HTTP/2.0", req["http_version"])
	require.Equal(t, `{"key":"value"}`, req["body_preview"])

	resp := ev["response"].(map[string]any)
	require.EqualValues(t, http.StatusCreated, resp["status"])
	require.Equal(t, "Created", resp["status_text"])
	require.Equal(t, "application/json", resp["content_type"])
	require.Len(t, resp["body_preview"], maxBodyBytes)
	require.EqualValues(t, len(body), resp["body_size"])
	require.Equal(t, true, resp["body_truncated"])
	require.Equal(t, sha256Hex(body), resp["body_sha256"])
	require.NotContains(t, resp, "method")
}

func TestWriterSkipsBinaryPreview(t *testing.T) {
	w := &writer{}
	encoded, ok := w.encode(&output.Result{
		Request: &navigation.Request{Method: http.MethodGet, URL: "https://target.example/file.png"},
		Response: &navigation.Response{
			StatusCode: http.StatusOK,
			Body:       "\x89PNG\r\n",
			Resp:       &http.Response{StatusCode: http.StatusOK, Header: http.Header{"Content-Type": []string{"image/png"}}},
		},
	})
	require.True(t, ok)
	var ev event
	require.NoError(t, json.Unmarshal(encoded, &ev))
	require.Empty(t, ev.Response.BodyPreview)
	require.Equal(t, sha256Hex("\x89PNG\r\n"), ev.Response.BodySHA256)
	require.True(t, ev.Response.BodyTruncated)
}

func TestWriterSkipsNonUTF8Preview(t *testing.T) {
	w := &writer{}
	latin1 := "caf\xe9"
	encoded, ok := w.encode(&output.Result{
		Request: &navigation.Request{Method: http.MethodPost, URL: "https://target.example/form", Body: latin1},
		Response: &navigation.Response{
			StatusCode: http.StatusOK,
			Body:       latin1,
			Resp:       &http.Response{StatusCode: http.StatusOK, Header: http.Header{"Content-Type": []string{"text/html; charset=iso-8859-1"}}},
		},
	})
	require.True(t, ok)
	var ev event
	require.NoError(t, json.Unmarshal(encoded, &ev))
	for _, m := range []message{ev.Request, ev.Response.message} {
		require.Empty(t, m.BodyPreview)
		require.True(t, m.BodyTruncated)
		require.Equal(t, sha256Hex(latin1), m.BodySHA256)
		require.EqualValues(t, len(latin1), m.BodySize)
	}
}

func TestNewMessageTruncatesOnRuneBoundary(t *testing.T) {
	body := strings.Repeat("a", maxBodyBytes-1) + "é" + "tail"
