func (w *StandardWriter) formatTemplate(output *Result) ([]byte, error) {
	var fieldOutputs []fieldOutput
	fieldNames := strings.Join(FieldNames, ",")
	fieldOutputs = formatField(output, fieldNames)
	fieldOutputs = append(fieldOutputs, getValueForCustomField(output)...)

	fieldsMap := make(map[string]string)
	for _, fo := range fieldOutputs {
		fieldsMap[fo.field] = fo.value
	}

	errUnknownTag := errors.New("unknown tag")

	tagFn := fasttemplate.TagFunc(func(w io.Writer, tag string) (int, error) {
		value, ok := fieldsMap[tag]
		if !ok {
			return 0, fmt.Errorf("%w %q", errUnknownTag, tag)
		}
		return w.Write([]byte(value))
	})

	out, err := w.outputTemplate.ExecuteFuncStringWithErr(tagFn)
	if err != nil {
		if errors.Is(err, errUnknownTag) {
			// If there is an unknown tag, we just ignore it.
			return nil, nil
		}
		return nil, err
	}

	return []byte(out), nil
}

package output

import (
	"net/http"
	"os"
	"path/filepath"
	"testing"

	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/utils/extensions"
	"github.com/stretchr/testify/require"
)

// The crawler parses the same response after writing it, so omitting fields
// from output must not strip them from the caller's result.
func TestWriteOmitDoesNotMutateResult(t *testing.T) {
	outFile := filepath.Join(t.TempDir(), "out.jsonl")
	writer, err := New(Options{
		JSON:               true,
		OmitBody:           true,
		OmitRaw:            true,
		OutputFile:         outFile,
		ExtensionValidator: extensions.NewValidator(nil, nil, true),
	})
	require.NoError(t, err)

	result := &Result{
		Request: &navigation.Request{URL: "http://example.com/api/data.json", Raw: "GET /api/data.json"},
		Response: &navigation.Response{
			Resp: &http.Response{StatusCode: http.StatusOK},
			Body: `{"next":"/p/one.html"}`,
			Raw:  "HTTP/1.1 200 OK",
		},
	}
	require.NoError(t, writer.Write(result))
	require.NoError(t, writer.Close())

	require.Equal(t, `{"next":"/p/one.html"}`, result.Response.Body)
	require.Equal(t, "HTTP/1.1 200 OK", result.Response.Raw)
	require.Equal(t, "GET /api/data.json", result.Request.Raw)

	data, err := os.ReadFile(outFile)
	require.NoError(t, err)
	require.NotContains(t, string(data), `"body"`)
	require.NotContains(t, string(data), `"raw"`)
}

package output

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"

	jsoniter "github.com/json-iterator/go"
	"github.com/logrusorgru/aurora"
	"github.com/mitchellh/mapstructure"
	"github.com/projectdiscovery/dsl"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/katana/pkg/navigation"
	"github.com/projectdiscovery/katana/pkg/utils/extensions"
	"github.com/projectdiscovery/utils/errkit"
	fileutil "github.com/projectdiscovery/utils/file"
	"github.com/stoewer/go-strcase"
	"github.com/valyala/fasttemplate"
)

const (
	indexFile          = "index.txt"
	DefaultResponseDir = "katana_response"
)

var (
	storeFieldDir    = "katana_field"
	decolorizerRegex = regexp.MustCompile(`\x1B\[[0-9;]*[a-zA-Z]`)
)

// Writer is an interface which writes output to somewhere for katana events.
type Writer interface {
	// Close closes the output writer interface
	Close() error
	// Write writes the event to file and/or screen.
	Write(*Result) error
	WriteErr(*Error) error
	// GetResultCount returns the number of results written
	GetResultCount() int64
}

// StandardWriter is an standard output writer structure
type StandardWriter struct {
	storeFields           []string
	fields                string
	json                  bool
	verbose               bool
	aurora                aurora.Aurora
	outputFile            *fileWriter
	outputMutex           *sync.Mutex
	storeResponse         bool
	storeResponseDir      string
	noClobber             bool
	omitRaw               bool
	omitBody              bool
	errorFile             *fileWriter
	matchRegex            []*regexp.Regexp
	filterRegex           []*regexp.Regexp
	extensionValidator    *extensions.Validator
	outputTemplate        *fasttemplate.Template
	outputMatchCondition  string
	outputFilterCondition string
	excludeOutputFields   []string
	filterPageType        []string
	// Result counting for completion stats
	resultCount int64
}

// New returns a new output writer instance
func New(options Options) (Writer, error) {
	writer := &StandardWriter{
		fields:                options.Fields,
		json:                  options.JSON,
		verbose:               options.Verbose,
		aurora:                aurora.NewAurora(options.Colors),
		outputMutex:           &sync.Mutex{},
		storeResponse:         options.StoreResponse,
		storeResponseDir:      options.StoreResponseDir,
		noClobber:             options.NoClobber,
		omitRaw:               options.OmitRaw,
		omitBody:              options.OmitBody,
		matchRegex:            options.MatchRegex,
		filterRegex:           options.FilterRegex,
		extensionValidator:    options.ExtensionValidator,
		outputMatchCondition:  options.OutputMatchCondition,
		outputFilterCondition: options.OutputFilterCondition,
		excludeOutputFields:   options.ExcludeOutputFields,
		filterPageType:        options.FilterPageType,
	}

	if options.StoreFieldDir != "" {
		storeFieldDir = options.StoreFieldDir
	}
	// if fieldConfig empty get the default file
	if options.FieldConfig == "" {
		var err error
		options.FieldConfig, err = initCustomFieldConfigFile()
		if err != nil {
			return nil, err
		}
	}
	err := parseCustomFieldName(options.FieldConfig)
	if err != nil {
		return nil, err
	}
	err = loadCustomFields(options.FieldConfig, fmt.Sprintf("%s,%s", options.Fields, options.StoreFields))
	if err != nil {
		return nil, err
	}
	// Perform validations for fields and store-fields
	if options.Fields != "" {
		if err := validateFieldNames(options.Fields); err != nil {
			return nil, errkit.Wrap(err, "output: could not validate fields")
		}
	}
	if options.StoreFields != "" {
		_ = os.MkdirAll(storeFieldDir, os.ModePerm)
		if err := validateFieldNames(options.StoreFields); err != nil {
			return nil, errkit.Wrap(err, "output: could not validate store fields")
		}
		writer.storeFields = append(writer.storeFields, strings.Split(options.StoreFields, ",")...)
	}
	if options.OutputFile != "" {
		output, err := newFileOutputWriter(options.OutputFile)
		if err != nil {
			return nil, errkit.Wrap(err, "output: could not create output file")
		}
		writer.outputFile = output
	}
	if options.StoreResponse {
		writer.storeResponseDir = DefaultResponseDir
		isCustomDir := options.StoreResponseDir != DefaultResponseDir && options.StoreResponseDir != ""
		if isCustomDir {
			writer.storeResponseDir = options.StoreResponseDir
		}
		if options.NoClobber {
			writer.storeResponseDir = createDirNameNoClobber(writer.storeResponseDir)
			_ = os.MkdirAll(writer.storeResponseDir, os.ModePerm)
		} else if !isCustomDir {
			removeDirsWithSuffix(writer.storeResponseDir)
			_ = os.MkdirAll(writer.storeResponseDir, os.ModePerm)
		} else {
			_ = os.MkdirAll(writer.storeResponseDir, os.ModePerm)
		}
		// Pre-create or open index file. For custom or no-clobber dirs, keep index additive.
		indexPath := filepath.Join(writer.storeResponseDir, indexFile)
		flags := os.O_CREATE | os.O_WRONLY
		if options.NoClobber || isCustomDir {
			flags |= os.O_APPEND
		} else {
			flags |= os.O_TRUNC
		}
		f, err := os.OpenFile(indexPath, flags, 0644)
		if err != nil {
			return nil, errkit.Wrap(err, "output: could not create index file")
		}
		if cerr := f.Close(); cerr != nil {
			return nil, errkit.Wrap(cerr, "output: could not close index file")
		}
	}
	if options.ErrorLogFile != "" {
		errorFile, err := newFileOutputWriter(options.ErrorLogFile)
		if err != nil {
			return nil, errkit.Wrap(err, "output: could not create error file")
		}

		writer.errorFile = errorFile
	}
	if options.OutputTemplate != "" {
		writer.outputTemplate, err = fasttemplate.NewTemplate(options.OutputTemplate, "{{", "}}")
		if err != nil {
			return nil, errkit.Wrap(err, "output: could not create output format template")
		}
	}
	return writer, nil
}

// Write writes the result to file and/or screen.
func (w *StandardWriter) Write(result *Result) error {
	if result == nil {
		return errors.New("result is nil")
	}

	// Skip empty responses (e.g., from similarity filtering)
	if result.Response != nil && result.Response.Resp == nil && result.Response.Body == "" && result.Error == "" {
		return errors.New("response filtered by similarity detection")
	}

	if len(w.storeFields) > 0 {
		storeFields(result, w.storeFields)
	}

	if !w.extensionValidator.ValidatePath(result.Request.URL) {
		return errors.New("result does not match extension filter")
	}

	if !w.matchOutput(result) {
		return errors.New("result does not match output")
	}
	if w.filterOutput(result) {
		return errors.New("result is filtered out")
	}
	if len(w.filterPageType) > 0 && result.Response != nil && result.Response.KnowledgeBase != nil {
		if pageType, ok := result.Response.KnowledgeBase["PageType"].(string); ok {
			for _, ft := range w.filterPageType {
				if strings.EqualFold(pageType, ft) {
					return errors.New("result filtered by page type")
				}
			}
		}
	}
	var data []byte
	var err error

	if w.storeResponse && result.HasResponse() {
		if fileName, fileWriter, err := getResponseFile(w.storeResponseDir, result.Response.Resp.Request.URL.String()); err == nil {
			if absPath, err := filepath.Abs(fileName); err == nil {
				fileName = absPath
			}
			result.Response.StoredResponsePath = fileName
			data, err := w.formatResult(result)
			if err != nil {
				return errkit.Wrap(err, "output: could not store response")
			}
			if err := updateIndex(w.storeResponseDir, result); err != nil {
				return errkit.Wrap(err, "output: could not store response")
			}
			if err := fileWriter.Write(data); err != nil {
				return errkit.Wrap(err, "output: could not store response")
			}
			_ = fileWriter.Close()
		}
	}

	if w.omitRaw || w.omitBody {
		result = w.withOmittedFields(result)
	}

	var outputKind string

	switch {
	case w.outputTemplate != nil:
		outputKind = "template"
		data, err = w.formatTemplate(result)
	case w.json:
		outputKind = "JSON"
		data, err = w.formatJSON(result)
	default:
		outputKind = "screen"
		data, err = w.formatScreen(result)
	}

	if err != nil {
		return errkit.Wrap(err, fmt.Sprintf("output: could not format %s output", outputKind))
	}

	if len(data) == 0 {
		return errors.New("result is empty")
	}

	// Increment result count only for valid results that produce output
	atomic.AddInt64(&w.resultCount, 1)

	w.outputMutex.Lock()
	defer w.outputMutex.Unlock()

	gologger.Silent().Msgf("%s", string(data))
	if w.outputFile != nil {
		if !w.json {
			data = decolorizerRegex.ReplaceAll(data, []byte(""))
		}
		if err := w.outputFile.Write(data); err != nil {
			return errkit.Wrap(err, "output: could not write to output")
		}
	}

	return nil
}

// withOmittedFields omits on a copy because the crawler still parses the
// original response after writing it.
func (w *StandardWriter) withOmittedFields(result *Result) *Result {
	omitted := *result
	if w.omitRaw {
		request := *omitted.Request
		request.Raw = ""
		omitted.Request = &request
	}
	if omitted.Response != nil {
		response := *omitted.Response
		if w.omitRaw {
			response.Raw = ""
		}
		if w.omitBody && result.HasResponse() {
			response.Body = ""
		}
		omitted.Response = &response
	}
	return &omitted
}

func (w *StandardWriter) WriteErr(errMessage *Error) error {
	data, err := jsoniter.Marshal(errMessage)
	if err != nil {
		return errkit.Wrap(err, "output: marshal")
	}
	if len(data) == 0 {
		return nil
	}
	w.outputMutex.Lock()
	defer w.outputMutex.Unlock()

	if w.errorFile != nil {
		if err := w.errorFile.Write(data); err != nil {
			return errkit.Wrap(err, "output: write to error file")
		}
	}
	return nil
}

// Close closes the output writer
func (w *StandardWriter) Close() error {
	if w.outputFile != nil {
		err := w.outputFile.Close()
		if err != nil {
			return err
		}
	}
	if w.errorFile != nil {
		err := w.errorFile.Close()
		if err != nil {
			return err
		}
	}
	return nil
}

// GetResultCount returns the number of results written
func (w *StandardWriter) GetResultCount() int64 {
	return atomic.LoadInt64(&w.resultCount)
}

func createDirNameNoClobber(dir string) string {
	if !fileutil.FolderExists(dir) {
		return dir
	}
	if entries, err := os.ReadDir(dir); err == nil && len(entries) == 0 {
		return dir
	}

	parentDir, dirName := filepath.Dir(dir), filepath.Base(dir)
	entries, err := os.ReadDir(parentDir)
	if err != nil {
		return dirName
	}

	highestNum := 0
	regex := regexp.MustCompile(fmt.Sprintf("^%s(\\d+)$", regexp.QuoteMeta(dirName)))
	for _, entry := range entries {
		if entry.IsDir() {
			name := entry.Name()
			matches := regex.FindStringSubmatch(name)
			if matches != nil {
				if num, err := strconv.Atoi(matches[1]); err == nil && num > highestNum {
					highestNum = num
				}
			}
		}
	}

	newDirName := fmt.Sprintf("%s%d", dirName, highestNum+1)
	newFullPath := filepath.Join(parentDir, newDirName)
	return newFullPath
}

func removeDirsWithSuffix(dir string) {
	parentDir, dirName := filepath.Dir(dir), filepath.Base(dir)
	entries, _ := os.ReadDir(parentDir)

	pattern := fmt.Sprintf("^%s(\\d*)$", regexp.QuoteMeta(dirName))
	regex := regexp.MustCompile(pattern)
	for _, entry := range entries {
		if entry.IsDir() {
			name := entry.Name()
			if regex.MatchString(name) {
				fullPath := filepath.Join(parentDir, name)
				_ = os.RemoveAll(fullPath)
			}
		}
	}
}

// matchOutput checks if the event matches the output regex
func (w *StandardWriter) matchOutput(event *Result) bool {
	if w.matchRegex == nil && w.outputMatchCondition == "" {
		return true
	}

	for _, regex := range w.matchRegex {
		if regex.MatchString(event.Request.URL) {
			return true
		}
	}

	if w.outputMatchCondition != "" {
		return evalDslExpr(event, w.outputMatchCondition)
	}

	return false
}

// filterOutput returns true if the event should be filtered out
func (w *StandardWriter) filterOutput(event *Result) bool {
	if w.filterRegex == nil && w.outputFilterCondition == "" {
		return false
	}

	for _, regex := range w.filterRegex {
		if regex.MatchString(event.Request.URL) {
			return true
		}
	}

	if w.outputFilterCondition != "" {
		return evalDslExpr(event, w.outputFilterCondition)
	}

	return false
}

func evalDslExpr(result *Result, dslExpr string) bool {
	resultMap, err := resultToMap(*result)
	if err != nil {
		gologger.Warning().Msgf("Could not map result: %s\n", err)
		return false
	}

	res, err := dsl.EvalExpr(dslExpr, resultMap)
	if err != nil && !ignoreErr(err) {
		gologger.Error().Msgf("Could not evaluate DSL expression: %s\n", err)
		return false
	}
	return res == true
}

func resultToMap(result Result) (map[string]interface{}, error) {
	resultMap := make(map[string]any)
	config := &mapstructure.DecoderConfig{
		TagName: "json",
		Result:  &resultMap,
	}
	decoder, err := mapstructure.NewDecoder(config)
	if err != nil {
		return nil, fmt.Errorf("error creating decoder: %v", err)
	}
	err = decoder.Decode(result)
	if err != nil {
		return nil, fmt.Errorf("error decoding: %v", err)
	}

	requestMap := make(map[string]any)
	if err := mapstructure.Decode(result.Request, &requestMap); err == nil {
		for k, v := range requestMap {
			resultMap[strcase.SnakeCase(k)] = v
		}
	}

	responseMap := make(map[string]any)
	if err := mapstructure.Decode(result.Response, &responseMap); err == nil {
		for k, v := range responseMap {
			if strings.ToLower(k) == "headers" {
				if headers, ok := v.(navigation.Headers); ok {
					for hk, hv := range headers {
						resultMap[strcase.SnakeCase(hk)] = hv
					}
				}
			} else {
				resultMap[strcase.SnakeCase(k)] = v
			}
		}
	}

	return flatten(resultMap), nil
}

// mapsutil.Flatten w/o separator
func flatten(m map[string]any) map[string]any {
	o := make(map[string]any)
	for k, v := range m {
		switch child := v.(type) {
		case map[string]any:
			nm := flatten(child)
			for nk, nv := range nm {
				o[strcase.SnakeCase(nk)] = nv
			}
		default:
			o[strcase.SnakeCase(k)] = v
		}
	}
	return o
}

var (
	// showDSLErr controls whether to show hidden DSL errors or not
	showDSLErr = strings.EqualFold(os.Getenv("SHOW_DSL_ERRORS"), "true")
)

// ignoreErr checks if the error is to be ignored or not
// Reference: https://github.com/projectdiscovery/katana/pull/537
func ignoreErr(err error) bool {
	if showDSLErr {
		return false
	}
	if errors.Is(err, dsl.ErrParsingArg) || strings.Contains(err.Error(), "No parameter") {
		return true
	}
	return false
}

package output

import (
	"bytes"
	"crypto/sha1"
	"encoding/hex"
	"os"
	"path/filepath"
	"strings"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/utils/errkit"
	urlutil "github.com/projectdiscovery/utils/url"
)

func getResponseHash(URL string) string {
	hash := sha1.Sum([]byte(URL))
	return hex.EncodeToString(hash[:])
}

func (w *StandardWriter) formatResult(result *Result) ([]byte, error) {
	builder := &bytes.Buffer{}

	builder.WriteString(result.Request.URL)
	builder.WriteString("\n\n\n")

	builder.WriteString(result.Request.Raw)

	builder.WriteString("\n\n")

	builder.WriteString(result.Response.Raw)

	return builder.Bytes(), nil
}

func getResponseHost(URL string) (string, error) {
	u, err := urlutil.Parse(URL)
	if err != nil {
		return "", err
	}
	return filepath.Clean(strings.ReplaceAll(u.Host, ":", "_")), nil
}

func createHostDir(storeResponseFolder, domain string) string {
	_ = os.MkdirAll(filepath.Join(storeResponseFolder, domain), os.ModePerm)
	return filepath.Join(storeResponseFolder, domain)
}

func getResponseFile(storeResponseFolder, URL string) (string, *fileWriter, error) {
	domain, err := getResponseHost(URL)
	if err != nil {
		return "", nil, err
	}
	fileName := getResponseFileName(storeResponseFolder, domain, URL)
	output, err := newFileOutputWriter(fileName)
	if err != nil {
		return "", nil, errkit.Wrap(err, "output: could not create output file")
	}

	return fileName, output, nil
}

func getResponseFileName(storeResponseFolder, domain, URL string) string {
	folder := createHostDir(storeResponseFolder, domain)
	file := getResponseHash(URL) + ".txt"
	return filepath.Join(folder, file)
}

func updateIndex(storeResponseFolder string, result *Result) error {
	index, err := os.OpenFile(filepath.Join(storeResponseFolder, indexFile), os.O_APPEND|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}

	defer func() {
		if err := index.Close(); err != nil {
			gologger.Error().Msgf("Error closing index: %v\n", err)
		}
	}()

	builder := &bytes.Buffer{}

	domain, err := getResponseHost(result.Request.URL)
	if err != nil {
		return err
	}

	builder.WriteString(getResponseFileName(storeResponseFolder, domain, result.Request.URL))
	builder.WriteRune(' ')
	builder.WriteString(result.Request.URL)
	builder.WriteRune(' ')
	builder.WriteString("(" + result.Response.Resp.Status + ")")
	builder.WriteRune('\n')

	if _, writeErr := index.Write(builder.Bytes()); writeErr != nil {
		return errkit.Wrap(err, "output: could not update index")
	}

	return nil
}

package output

import (
	"time"

	"github.com/projectdiscovery/katana/pkg/navigation"
)

// Result of the crawling
type Result struct {
	Timestamp time.Time            `json:"timestamp,omitempty"`
	Request   *navigation.Request  `json:"request,omitempty"`
	Response  *navigation.Response `json:"response,omitempty"`
	Error     string               `json:"error,omitempty"`
}

// HasResponse checks if the result has a valid response
func (r *Result) HasResponse() bool {
	return r.Response != nil && r.Response.Resp != nil
}

package similarity

import (
	"fmt"
	"strings"
	"sync"

	"github.com/projectdiscovery/gologger"
)

// Mode selects the content similarity backend.
type Mode string

const (
	ModeSimHash Mode = "simhash"
	ModeTFIDF   Mode = "tfidf"
	ModeBM25    Mode = "bm25"
)

const (
	DefaultMode            = ModeSimHash
	DefaultHammingDistance = 3
	DefaultScoreThreshold  = 0.85
	DefaultBudget          = 1
	DefaultMaxDocuments    = 1000
)

// Config configures a content similarity index.
type Config struct {
	Mode            Mode
	HammingDistance int
	ScoreThreshold  float64
	Budget          int
	MaxDocuments    int
}

// Stats are cumulative Accept counters.
type Stats struct {
	Processed int64
	Accepted  int64
	Filtered  int64
}

type simRep struct {
	id uint64
	fp uint64
}

// Index applies optional page-content similarity with a per-cluster parse budget.
type Index struct {
	cfg Config

	mu       sync.Mutex
	corpus   *lexicalCorpus
	sigs     []simRep
	nextID   uint64
	clusters map[string]int // stable clusterID -> accepted count
	stats    Stats
}

// ParseMode validates a mode string.
func ParseMode(s string) (Mode, error) {
	switch Mode(strings.ToLower(strings.TrimSpace(s))) {
	case "", ModeSimHash:
		return ModeSimHash, nil
	case ModeTFIDF:
		return ModeTFIDF, nil
	case ModeBM25:
		return ModeBM25, nil
	default:
		return "", fmt.Errorf("unknown similarity mode %q (want simhash, tfidf, or bm25)", s)
	}
}

// New creates an Index. Invalid/zero config fields are filled with defaults.
func New(cfg Config) (*Index, error) {
	if cfg.Mode == "" {
		cfg.Mode = DefaultMode
	}
	mode, err := ParseMode(string(cfg.Mode))
	if err != nil {
		return nil, err
	}
	cfg.Mode = mode
	if cfg.HammingDistance <= 0 {
		cfg.HammingDistance = DefaultHammingDistance
	}
	if cfg.ScoreThreshold <= 0 || cfg.ScoreThreshold > 1 {
		cfg.ScoreThreshold = DefaultScoreThreshold
	}
	if cfg.Budget <= 0 {
		cfg.Budget = DefaultBudget
	}
	if cfg.MaxDocuments <= 0 {
		cfg.MaxDocuments = DefaultMaxDocuments
	}
	return &Index{
		cfg:      cfg,
		corpus:   newLexicalCorpus(),
		clusters: make(map[string]int),
	}, nil
}

func clusterKey(mode Mode, id uint64) string {
	return fmt.Sprintf("%s:%d", mode, id)
}

// Accept reports whether the page should be fully processed (parsed/enqueued).
// true = accept; false = skip as similar beyond cluster budget.
// Pages with too little signal are always accepted.
func (i *Index) Accept(body []byte) bool {
	if i == nil {
		return true
	}

	i.mu.Lock()
	defer i.mu.Unlock()

	i.stats.Processed++

	doc, ok := Normalize(body)
	if !ok {
		i.stats.Accepted++
		return true
	}

	clusterID, matched := i.matchLocked(doc)
	if matched {
		if i.clusters[clusterID] >= i.cfg.Budget {
			i.stats.Filtered++
			gologger.Debug().Msgf("[similarity:%s] filtered cluster=%s budget=%d", i.cfg.Mode, clusterID, i.cfg.Budget)
			return false
		}
		i.clusters[clusterID]++
		i.stats.Accepted++
		return true
	}

	clusterID = i.rememberLocked(doc)
	i.clusters[clusterID] = 1
	i.stats.Accepted++
	return true
}

func (i *Index) matchLocked(doc Document) (clusterID string, matched bool) {
	switch i.cfg.Mode {
	case ModeSimHash:
		fp := SimHash64(doc.Shingles)
		bestDist := 64
		var bestID uint64
		found := false
		for _, existing := range i.sigs {
			d := HammingDistance(fp, existing.fp)
			if !found || d < bestDist {
				bestDist = d
				bestID = existing.id
				found = true
			}
		}
		if found && bestDist <= i.cfg.HammingDistance {
			return clusterKey(ModeSimHash, bestID), true
		}
		return "", false
	case ModeTFIDF:
		score, id, ok := i.corpus.MaxCosine(doc.Tokens)
		if ok && score >= i.cfg.ScoreThreshold {
			return clusterKey(ModeTFIDF, id), true
		}
		return "", false
	case ModeBM25:
		score, id, ok := i.corpus.MaxBM25(doc.Tokens)
		if ok && score >= i.cfg.ScoreThreshold {
			return clusterKey(ModeBM25, id), true
		}
		return "", false
	default:
		return "", false
	}
}

// rememberLocked stores a new representative and returns its stable cluster ID.
func (i *Index) rememberLocked(doc Document) string {
	switch i.cfg.Mode {
	case ModeSimHash:
		for len(i.sigs) >= i.cfg.MaxDocuments {
			old := i.sigs[0]
			delete(i.clusters, clusterKey(ModeSimHash, old.id))
			i.sigs = i.sigs[1:]
		}
		id := i.nextID
		i.nextID++
		i.sigs = append(i.sigs, simRep{id: id, fp: SimHash64(doc.Shingles)})
		return clusterKey(ModeSimHash, id)
	case ModeTFIDF, ModeBM25:
		for i.corpus.Len() >= i.cfg.MaxDocuments {
			if id, ok := i.corpus.EvictOldest(); ok {
				delete(i.clusters, clusterKey(i.cfg.Mode, id))
			}
		}
		id := i.corpus.Add(doc.Tokens)
		return clusterKey(i.cfg.Mode, id)
	default:
		return "unknown"
	}
}

// Stats returns a snapshot of counters.
func (i *Index) Stats() Stats {
	if i == nil {
		return Stats{}
	}
	i.mu.Lock()
	defer i.mu.Unlock()
	return i.stats
}

// Mode returns the configured mode.
func (i *Index) Mode() Mode {
	if i == nil {
		return ""
	}
	return i.cfg.Mode
}

// Close releases index resources.
func (i *Index) Close() {
	if i == nil {
		return
	}
	i.mu.Lock()
	defer i.mu.Unlock()
	i.sigs = nil
	i.corpus = newLexicalCorpus()
	i.clusters = make(map[string]int)
	i.nextID = 0
}

package similarity

import (
	"fmt"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

func productHTML(id int, blurb string) []byte {
	return htmlPage(
		"Home Shop Cart Account Help",
		fmt.Sprintf("Product %d %s Exclusive cotton shirt available in multiple sizes with free shipping worldwide today only", id, blurb),
	)
}

func blogHTML(title, body string) []byte {
	return htmlPage(
		"Home Shop Cart Account Help",
		fmt.Sprintf("%s %s", title, body),
	)
}

func newTestIndex(t *testing.T, cfg Config) *Index {
	t.Helper()
	idx, err := New(cfg)
	require.NoError(t, err)
	return idx
}

func TestIndex_SimHash_ClusterBudget(t *testing.T) {
	idx := newTestIndex(t, Config{Mode: ModeSimHash, HammingDistance: 3, Budget: 1})

	p1 := productHTML(1, "red")
	p2 := productHTML(2, "red") // near-identical template
	p3 := blogHTML(
		"Deep Dive Into Distributed Consensus Algorithms",
		"Raft Paxos Viewstamped Replication quorum election log replication safety liveness detailed analysis for engineers building reliable systems",
	)

	require.True(t, idx.Accept(p1), "first product should be accepted")
	require.False(t, idx.Accept(p2), "near-duplicate product should be filtered with budget 1")
	require.True(t, idx.Accept(p3), "unrelated blog should be accepted")

	st := idx.Stats()
	require.Equal(t, int64(3), st.Processed)
	require.Equal(t, int64(2), st.Accepted)
	require.Equal(t, int64(1), st.Filtered)
}

func TestIndex_SimHash_BudgetTwo(t *testing.T) {
	idx := newTestIndex(t, Config{Mode: ModeSimHash, HammingDistance: 3, Budget: 2})

	require.True(t, idx.Accept(productHTML(1, "blue")))
	require.True(t, idx.Accept(productHTML(2, "blue")), "second near-dupe allowed with budget 2")
	require.False(t, idx.Accept(productHTML(3, "blue")), "third near-dupe filtered")
}

func TestIndex_TFIDF_NearCopyFiltered_UnrelatedAccepted(t *testing.T) {
	idx := newTestIndex(t, Config{Mode: ModeTFIDF, ScoreThreshold: 0.85, Budget: 1})

	a := blogHTML(
		"Introducing GraphQL Federation at Scale",
		"This article explains schema stitching gateway composition subgraph ownership and query planning challenges when operating federated graphs across many teams",
	)
	b := blogHTML(
		"Introducing GraphQL Federation at Scale",
		"This article explains schema stitching gateway composition subgraph ownership and query planning challenges when operating federated graphs across many teams with minor notes",
	)
	c := blogHTML(
		"Sourdough Baking Hydration Percentages",
		"Learn how flour water salt and starter ratios affect crumb structure oven spring and fermentation timing for artisan loaves baked on a stone",
	)

	require.True(t, idx.Accept(a))
	require.False(t, idx.Accept(b), "near-copy should exceed TF-IDF threshold")
	require.True(t, idx.Accept(c), "topically different page should pass")
}

func TestIndex_BM25_NearCopyFiltered_UnrelatedAccepted(t *testing.T) {
	idx := newTestIndex(t, Config{Mode: ModeBM25, ScoreThreshold: 0.85, Budget: 1})

	a := blogHTML(
		"Kubernetes Network Policies Deep Dive",
		"Calico Cilium eBPF egress ingress selectors namespaces and troubleshooting connection refused errors in multi-tenant clusters explained step by step",
	)
	b := blogHTML(
		"Kubernetes Network Policies Deep Dive",
		"Calico Cilium eBPF egress ingress selectors namespaces and troubleshooting connection refused errors in multi-tenant clusters explained step by step again",
	)
	c := blogHTML(
		"Classical Guitar Fingerstyle Patterns",
		"Travis picking arpeggios rest stroke free stroke practice routines metronome technique and repertoire suggestions for intermediate players",
	)

	require.True(t, idx.Accept(a))
	require.False(t, idx.Accept(b))
	require.True(t, idx.Accept(c))
}

func TestIndex_AllModes_LowSignalAlwaysAccepted(t *testing.T) {
	for _, mode := range []Mode{ModeSimHash, ModeTFIDF, ModeBM25} {
		t.Run(string(mode), func(t *testing.T) {
			idx := newTestIndex(t, Config{Mode: mode, Budget: 1})
			require.True(t, idx.Accept([]byte("ok")))
			require.True(t, idx.Accept([]byte("ok")))
		})
	}
}

func TestIndex_DisabledNilAccepts(t *testing.T) {
	var idx *Index
	require.True(t, idx.Accept([]byte("anything at all here for safety")))
}

func TestParseMode(t *testing.T) {
	m, err := ParseMode("TFIDF")
	require.NoError(t, err)
	require.Equal(t, ModeTFIDF, m)

	_, err = ParseMode("magic")
	require.Error(t, err)
}

func TestIndex_SharedChromeDoesNotCollapseDistinctMains(t *testing.T) {
	// Same nav/footer chrome; clearly different main content.
	for _, mode := range []Mode{ModeSimHash, ModeTFIDF, ModeBM25} {
		t.Run(string(mode), func(t *testing.T) {
			idx := newTestIndex(t, Config{
				Mode:            mode,
				HammingDistance: 3,
				ScoreThreshold:  0.85,
				Budget:          1,
			})
			a := htmlPage(
				"Home About Contact Shared Nav Items",
				"Astronomy telescope aperture focal length mount equatorial tracking deep sky objects nebulae galaxies observing checklist",
			)
			b := htmlPage(
				"Home About Contact Shared Nav Items",
				"Mediterranean cooking olive oil garlic lemon herbs grilled vegetables seafood pasta recipes weeknight dinners",
			)
			require.True(t, idx.Accept(a))
			require.True(t, idx.Accept(b), "distinct main content must not be collapsed by shared chrome")
		})
	}
}

func TestLexicalCorpus_EvictRepairsDocFreq(t *testing.T) {
	c := newLexicalCorpus()
	id0 := c.Add([]string{"alpha", "beta", "gamma", "delta", "epsilon"})
	id1 := c.Add([]string{"alpha", "zeta", "eta", "theta", "iota"})
	require.Equal(t, uint64(0), id0)
	require.Equal(t, uint64(1), id1)
	require.Equal(t, 2, c.docFreq["alpha"])
	evicted, ok := c.EvictOldest()
	require.True(t, ok)
	require.Equal(t, id0, evicted)
	require.Equal(t, 1, c.docFreq["alpha"])
	require.Equal(t, 0, c.docFreq["beta"])
	require.Equal(t, 1, c.Len())
	// Remaining doc keeps its stable ID.
	score, matchedID, ok := c.MaxCosine([]string{"alpha", "zeta", "eta", "theta", "iota"})
	require.True(t, ok)
	require.Equal(t, id1, matchedID)
	require.Greater(t, score, 0.9)
}

func TestIndex_StableClusterIDsSurviveEviction(t *testing.T) {
	for _, mode := range []Mode{ModeSimHash, ModeTFIDF, ModeBM25} {
		t.Run(string(mode), func(t *testing.T) {
			idx := newTestIndex(t, Config{
				Mode:            mode,
				HammingDistance: 3,
				ScoreThreshold:  0.85,
				Budget:          1,
				MaxDocuments:    2,
			})

			pages := [][]byte{
				blogHTML("Topic Alpha One", "alpha content about networking switches routers firewalls packet capture tooling"),
				blogHTML("Topic Beta Two", "beta content about photography lenses apertures shutters composition lighting"),
				blogHTML("Topic Gamma Three", "gamma content about baking sourdough hydration fermentation oven spring crumb"),
			}
			require.True(t, idx.Accept(pages[0]))
			require.True(t, idx.Accept(pages[1]))
			// Evicts the oldest representative (page 0).
			require.True(t, idx.Accept(pages[2]))

			// Near-copy of the evicted page must be treated as a new cluster again,
			// not reuse a shifted slice index / stale budget counter.
			nearEvicted := blogHTML("Topic Alpha One", "alpha content about networking switches routers firewalls packet capture tooling notes")
			require.True(t, idx.Accept(nearEvicted), "evicted cluster should not keep a stale budget")

			// Exact repeat of a still-resident representative must still be filtered.
			require.False(t, idx.Accept(pages[2]), "resident cluster budget must still apply")
		})
	}
}

func TestNormalize_MultiArticleWithoutMainUsesAllArticles(t *testing.T) {
	pageA := []byte(`<!doctype html><html><body>
<article>Shared lead story about space telescopes and deep sky surveys with nebulae catalogs</article>
<article>Unique page one second story about urban cycling cargo bikes commuting safety</article>
</body></html>`)
	pageB := []byte(`<!doctype html><html><body>
<article>Shared lead story about space telescopes and deep sky surveys with nebulae catalogs</article>
<article>Unique page two second story about sourdough baking hydration fermentation crumb</article>
</body></html>`)

	a, ok := Normalize(pageA)
	require.True(t, ok)
	b, ok := Normalize(pageB)
	require.True(t, ok)
	joinedA := strings.Join(a.Tokens, " ")
	joinedB := strings.Join(b.Tokens, " ")
	require.Contains(t, joinedA, "cycling")
	require.Contains(t, joinedB, "sourdough")
	require.NotEqual(t, joinedA, joinedB)
}

package similarity

import "math"

// termCounts maps term -> raw frequency in a document.
type termCounts map[string]int

func countTerms(tokens []string) termCounts {
	counts := make(termCounts, len(tokens))
	for _, t := range tokens {
		counts[t]++
	}
	return counts
}

type lexicalDoc struct {
	id     uint64
	counts termCounts
	length int
}

type lexicalCorpus struct {
	docs      []lexicalDoc
	docFreq   map[string]int
	avgDocLen float64
	totalLen  int
	nextID    uint64
}

func newLexicalCorpus() *lexicalCorpus {
	return &lexicalCorpus{
		docFreq: make(map[string]int),
	}
}

func (c *lexicalCorpus) Len() int {
	return len(c.docs)
}

// Add stores a document and returns its stable ID.
func (c *lexicalCorpus) Add(tokens []string) uint64 {
	counts := countTerms(tokens)
	length := 0
	for _, n := range counts {
		length += n
	}
	id := c.nextID
	c.nextID++
	c.docs = append(c.docs, lexicalDoc{id: id, counts: counts, length: length})
	c.totalLen += length
	for term := range counts {
		c.docFreq[term]++
	}
	if len(c.docs) > 0 {
		c.avgDocLen = float64(c.totalLen) / float64(len(c.docs))
	}
	return id
}

// EvictOldest removes the oldest document, repairs docFreq, and returns its stable ID.
func (c *lexicalCorpus) EvictOldest() (id uint64, ok bool) {
	if len(c.docs) == 0 {
		return 0, false
	}
	old := c.docs[0]
	c.docs = c.docs[1:]
	c.totalLen -= old.length
	for term := range old.counts {
		c.docFreq[term]--
		if c.docFreq[term] <= 0 {
			delete(c.docFreq, term)
		}
	}
	if len(c.docs) > 0 {
		c.avgDocLen = float64(c.totalLen) / float64(len(c.docs))
	} else {
		c.avgDocLen = 0
	}
	return old.id, true
}

func (c *lexicalCorpus) idf(term string) float64 {
	df := c.docFreq[term]
	n := float64(len(c.docs) + 1) // +1 for the query/candidate document
	return math.Log((n)/(1+float64(df))) + 1
}

// MaxCosine returns the best cosine score and the matched document's stable ID.
// ok is false when the corpus is empty or there is no usable query.
func (c *lexicalCorpus) MaxCosine(tokens []string) (score float64, id uint64, ok bool) {
	if len(c.docs) == 0 || len(tokens) == 0 {
		return 0, 0, false
	}
	query := countTerms(tokens)
	queryLen := 0
	for _, n := range query {
		queryLen += n
	}
	if queryLen == 0 {
		return 0, 0, false
	}

	best := 0.0
	var bestID uint64
	found := false
	for _, doc := range c.docs {
		s := cosineTFIDF(query, queryLen, doc.counts, doc.length, c)
		if !found || s > best {
			best = s
			bestID = doc.id
			found = true
		}
	}
	return best, bestID, found
}

func cosineTFIDF(a termCounts, aLen int, b termCounts, bLen int, c *lexicalCorpus) float64 {
	if aLen == 0 || bLen == 0 {
		return 0
	}
	var dot, normA, normB float64
	seen := make(map[string]struct{}, len(a)+len(b))
	for t := range a {
		seen[t] = struct{}{}
	}
	for t := range b {
		seen[t] = struct{}{}
	}
	for term := range seen {
		idf := c.idf(term)
		va := float64(a[term]) / float64(aLen) * idf
		vb := float64(b[term]) / float64(bLen) * idf
		dot += va * vb
		normA += va * va
		normB += vb * vb
	}
	if normA == 0 || normB == 0 {
		return 0
	}
	return dot / (math.Sqrt(normA) * math.Sqrt(normB))
}

const (
	bm25K1 = 1.2
	bm25B  = 0.75
)

// MaxBM25 returns the best normalized BM25 score and the matched document's stable ID.
func (c *lexicalCorpus) MaxBM25(tokens []string) (score float64, id uint64, ok bool) {
	if len(c.docs) == 0 || len(tokens) == 0 {
		return 0, 0, false
	}
	query := countTerms(tokens)
	queryLen := 0
	for _, n := range query {
		queryLen += n
	}
	if queryLen == 0 {
		return 0, 0, false
	}
	self := bm25Score(query, query, queryLen, c)
	if self <= 0 {
		return 0, 0, false
	}

	best := 0.0
	var bestID uint64
	found := false
	for _, doc := range c.docs {
		raw := bm25Score(query, doc.counts, doc.length, c)
		norm := raw / self
		if norm > 1 {
			norm = 1
		}
		if !found || norm > best {
			best = norm
			bestID = doc.id
			found = true
		}
	}
	return best, bestID, found
}

func bm25Score(query, doc termCounts, docLen int, c *lexicalCorpus) float64 {
	if docLen == 0 || c.avgDocLen == 0 {
		return 0
	}
	var score float64
	for term, qf := range query {
		tf := float64(doc[term])
		if tf == 0 {
			continue
		}
		idf := c.idf(term)
		denom := tf + bm25K1*(1-bm25B+bm25B*float64(docLen)/c.avgDocLen)
		score += idf * (tf * (bm25K1 + 1) / denom) * float64(qf)
	}
	return score
}

package similarity

import (
	"bytes"
	"strings"
	"unicode"

	"github.com/PuerkitoBio/goquery"
)

const (
	minTokensForSimilarity = 5
	shingleSize            = 3
)

// Document is normalized page content ready for similarity scoring.
type Document struct {
	Tokens   []string
	Shingles []string
}

// Normalize extracts comparable text features from a response body.
// HTML is stripped of scripts/styles/chrome; non-HTML is tokenized as plain text.
// ok is false when there is not enough signal for similarity scoring.
func Normalize(body []byte) (Document, bool) {
	text := extractText(body)
	tokens := tokenize(text)
	if len(tokens) < minTokensForSimilarity {
		return Document{}, false
	}
	return Document{
		Tokens:   tokens,
		Shingles: shingles(tokens, shingleSize),
	}, true
}

func extractText(body []byte) string {
	trimmed := bytes.TrimSpace(body)
	if len(trimmed) == 0 {
		return ""
	}

	looksHTML := bytes.Contains(bytes.ToLower(trimmed[:min(len(trimmed), 512)]), []byte("<html")) ||
		bytes.Contains(bytes.ToLower(trimmed[:min(len(trimmed), 512)]), []byte("<!doctype")) ||
		bytes.Contains(trimmed, []byte("<body")) ||
		bytes.Contains(trimmed, []byte("<div")) ||
		bytes.Contains(trimmed, []byte("<p"))

	if !looksHTML {
		return string(trimmed)
	}

	doc, err := goquery.NewDocumentFromReader(bytes.NewReader(trimmed))
	if err != nil {
		return string(trimmed)
	}

	doc.Find("script, style, noscript, svg, template").Remove()

	root := doc.Find("main, [role=main]").First()
	if root.Length() == 0 {
		// Fall back to all articles when no main landmark exists so multi-article
		// index/pagination pages are compared on their full content.
		root = doc.Find("article")
	}
	if root.Length() == 0 {
		root = doc.Find("body")
	}
	if root.Length() == 0 {
		root = doc.Selection
	}
	root.Find("nav, header, footer, aside").Remove()
	return root.Text()
}

func tokenize(text string) []string {
	fields := strings.FieldsFunc(text, func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsNumber(r)
	})
	out := make([]string, 0, len(fields))
	for _, f := range fields {
		if len(f) < 2 {
			continue
		}
		// Lowercase and clone so corpus retention does not pin the full page buffer.
		out = append(out, strings.Clone(strings.ToLower(f)))
	}
	return out
}

func shingles(tokens []string, n int) []string {
	if n <= 0 || len(tokens) < n {
		// Fall back to tokens so short docs still get a fingerprint.
		cp := make([]string, len(tokens))
		copy(cp, tokens)
		return cp
	}
	out := make([]string, 0, len(tokens)-n+1)
	for i := 0; i <= len(tokens)-n; i++ {
		out = append(out, strings.Join(tokens[i:i+n], " "))
	}
	return out
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

package similarity

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

const (
	similarProductCount = 300
	similarArticleCount = 150
	distinctPageCount   = 5

	// Shared product/article boilerplate must dominate the varying id token so
	// near-duplicate detection stays stable across hundreds of pages.
	productBoilerplate = `Exclusive cotton shirt available in multiple sizes with free shipping worldwide today only.
Soft fabric durable stitching classic fit warehouse clearance event premium materials carefully selected
for comfort durability and everyday wear across seasons. Customer reviews highlight consistent sizing
and colorfast dyes after repeated washing cycles. Pair with denim chinos or layered autumn jackets.
Care instructions recommend cold wash gentle cycle and line dry to preserve fabric integrity.
Available colors include navy charcoal olive sand and classic white with seasonal limited editions.`

	articleBoilerplate = `Deep analysis of distributed systems consensus protocols covering raft paxos viewstamped replication
quorum elections log replication safety and liveness guarantees for reliable platform engineers.
We examine leader election timeout tuning snapshotting membership changes and multi-region failover
strategies under partition scenarios. Operational playbooks include metrics dashboards alerting
thresholds and chaos experiments that validate recovery objectives. Readers should leave with a
practical checklist for production consensus deployments and capacity planning guidance.`
)

// similarPagesServer serves hundreds of template-similar product/article pages
// plus a handful of topically distinct pages.
func similarPagesServer(t *testing.T, products, articles, distinct int) *httptest.Server {
	t.Helper()
	mux := http.NewServeMux()

	mux.HandleFunc("/", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		var b strings.Builder
		b.WriteString(`<!doctype html><html><body><nav>Home</nav><main><ul>`)
		for i := 1; i <= products; i++ {
			fmt.Fprintf(&b, `<li><a href="/product/%d">Product %d</a></li>`, i, i)
		}
		for i := 1; i <= articles; i++ {
			fmt.Fprintf(&b, `<li><a href="/article/%d">Article %d</a></li>`, i, i)
		}
		for i := 1; i <= distinct; i++ {
			fmt.Fprintf(&b, `<li><a href="/distinct/%d">Distinct %d</a></li>`, i, i)
		}
		b.WriteString(`</ul></main></body></html>`)
		_, _ = io.WriteString(w, b.String())
	})

	mux.HandleFunc("/product/", func(w http.ResponseWriter, r *http.Request) {
		_ = strings.TrimPrefix(r.URL.Path, "/product/")
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		// Body is intentionally identical across product IDs (id lives in the URL
		// only) so hundreds of template pages form one near-duplicate cluster.
		_, _ = fmt.Fprintf(w, `<!doctype html><html><body>
<nav>Home Products Cart Help Account</nav>
<main>Product detail. %s</main>
<footer>copyright 2026 example corp all rights reserved</footer>
</body></html>`, productBoilerplate)
	})

	mux.HandleFunc("/article/", func(w http.ResponseWriter, r *http.Request) {
		_ = strings.TrimPrefix(r.URL.Path, "/article/")
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = fmt.Fprintf(w, `<!doctype html><html><body>
<nav>Home Blog Topics Authors Subscribe</nav>
<main>Article detail. %s</main>
<footer>copyright 2026 example corp all rights reserved</footer>
</body></html>`, articleBoilerplate)
	})

	mux.HandleFunc("/distinct/", func(w http.ResponseWriter, r *http.Request) {
		id := strings.TrimPrefix(r.URL.Path, "/distinct/")
		n, _ := strconv.Atoi(id)
		pages := []string{
			`Mediterranean cooking workshop focusing on olive oil tasting garlic confit lemon zest herb blends grilled vegetables seafood stews handmade pasta dough and weeknight dinner planning for families who love bright coastal flavors.`,
			`Amateur astronomy field guide covering telescope aperture choices focal length ratios equatorial mounts nebulae catalogs galaxy hunting polar alignment and cold-weather observing checklists for dark-sky weekend trips.`,
			`Classical guitar practice curriculum with travis picking patterns rest-stroke free-stroke drills metronome ladders repertoire goals for bach loure studies and performance anxiety routines for intermediate players.`,
			`Sourdough bakery notebook documenting hydration percentages flour blends water temperature salt ratios starter feeding schedules crumb structure scoring patterns oven spring targets and fermentation timelines for artisan loaves.`,
			`Urban cycling advocacy handbook about cargo bike geometry lighting standards U-lock technique commuting rain gear protected intersections and city infrastructure campaigns that improve everyday rider safety.`,
		}
		body := pages[(n-1)%len(pages)]
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = fmt.Fprintf(w, `<!doctype html><html><body>
<nav>Home Products Cart Help Account</nav>
<main>%s</main>
<footer>copyright 2026 example corp all rights reserved</footer>
</body></html>`, body)
	})

	return httptest.NewServer(mux)
}

func fetchBody(t *testing.T, client *http.Client, url string) []byte {
	t.Helper()
	resp, err := client.Get(url)
	require.NoError(t, err)
	defer resp.Body.Close() //nolint:errcheck
	body, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	require.Equal(t, http.StatusOK, resp.StatusCode)
	return body
}

type crawlStats struct {
	productAccepted  int
	productFiltered  int
	articleAccepted  int
	articleFiltered  int
	distinctAccepted int
	distinctFiltered int
	elapsed          time.Duration
}

func (s crawlStats) totalAccepted() int {
	return s.productAccepted + s.articleAccepted + s.distinctAccepted
}

func (s crawlStats) totalFiltered() int {
	return s.productFiltered + s.articleFiltered + s.distinctFiltered
}

func (s crawlStats) totalProcessed() int {
	return s.totalAccepted() + s.totalFiltered()
}

func runSimilarSiteCrawl(t *testing.T, idx *Index, server *httptest.Server, products, articles, distinct int) crawlStats {
	t.Helper()
	client := server.Client()
	start := time.Now()
	var st crawlStats

	for i := 1; i <= products; i++ {
		body := fetchBody(t, client, fmt.Sprintf("%s/product/%d", server.URL, i))
		if idx.Accept(body) {
			st.productAccepted++
		} else {
			st.productFiltered++
		}
	}
	for i := 1; i <= articles; i++ {
		body := fetchBody(t, client, fmt.Sprintf("%s/article/%d", server.URL, i))
		if idx.Accept(body) {
			st.articleAccepted++
		} else {
			st.articleFiltered++
		}
	}
	for i := 1; i <= distinct; i++ {
		body := fetchBody(t, client, fmt.Sprintf("%s/distinct/%d", server.URL, i))
		if idx.Accept(body) {
			st.distinctAccepted++
		} else {
			st.distinctFiltered++
		}
	}

	st.elapsed = time.Since(start)
	return st
}

func assertIndexStatsMatch(t *testing.T, idx *Index, got crawlStats) {
	t.Helper()
	st := idx.Stats()
	require.Equal(t, int64(got.totalProcessed()), st.Processed, "index Processed")
	require.Equal(t, int64(got.totalAccepted()), st.Accepted, "index Accepted")
	require.Equal(t, int64(got.totalFiltered()), st.Filtered, "index Filtered")
	require.Equal(t, st.Processed, st.Accepted+st.Filtered, "Accepted+Filtered must equal Processed")
}

func logCrawlStats(t *testing.T, mode Mode, budget int, got crawlStats) {
	t.Helper()
	filterRate := 100 * float64(got.totalFiltered()) / float64(got.totalProcessed())
	t.Logf("[%s budget=%d] processed=%d accepted=%d filtered=%d (%.1f%% filtered) in %s",
		mode, budget, got.totalProcessed(), got.totalAccepted(), got.totalFiltered(), filterRate, got.elapsed.Round(time.Millisecond))
	t.Logf("  products: accepted=%d filtered=%d | articles: accepted=%d filtered=%d | distinct: accepted=%d filtered=%d",
		got.productAccepted, got.productFiltered, got.articleAccepted, got.articleFiltered, got.distinctAccepted, got.distinctFiltered)
}

func TestSimilarPagesServer_HundredsFilteredPerMode(t *testing.T) {
	products, articles, distinct := similarProductCount, similarArticleCount, distinctPageCount
	server := similarPagesServer(t, products, articles, distinct)
	defer server.Close()

	totalPages := products + articles + distinct
	require.GreaterOrEqual(t, totalPages, 400, "fixture must exercise hundreds of pages")

	cases := []struct {
		name   string
		cfg    Config
		budget int
	}{
		{"simhash", Config{Mode: ModeSimHash, HammingDistance: 3, Budget: 1}, 1},
		{"tfidf", Config{Mode: ModeTFIDF, ScoreThreshold: 0.85, Budget: 1}, 1},
		{"bm25", Config{Mode: ModeBM25, ScoreThreshold: 0.85, Budget: 1}, 1},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			idx := newTestIndex(t, tc.cfg)
			got := runSimilarSiteCrawl(t, idx, server, products, articles, distinct)
			logCrawlStats(t, tc.cfg.Mode, tc.budget, got)

			// Two template clusters (products, articles), each keeps budget representatives.
			require.Equal(t, tc.budget, got.productAccepted, "product cluster representatives")
			require.Equal(t, products-tc.budget, got.productFiltered, "product near-dupes skipped")
			require.Equal(t, tc.budget, got.articleAccepted, "article cluster representatives")
			require.Equal(t, articles-tc.budget, got.articleFiltered, "article near-dupes skipped")

			// Distinct topical pages must survive.
			require.Equal(t, distinct, got.distinctAccepted, "all distinct pages accepted")
			require.Zero(t, got.distinctFiltered)

			expectedAccepted := 2*tc.budget + distinct
			expectedFiltered := (products - tc.budget) + (articles - tc.budget)
			require.Equal(t, expectedAccepted, got.totalAccepted())
			require.Equal(t, expectedFiltered, got.totalFiltered())
			require.Equal(t, totalPages, got.totalProcessed())

			// Vast majority of the site should be filtered as similar.
			require.Greater(t, got.totalFiltered(), got.totalAccepted()*10,
				"filtered volume should dwarf accepted representatives on a template-heavy site")
			assertIndexStatsMatch(t, idx, got)
		})
	}
}

func TestSimilarPagesServer_BudgetTwoScales(t *testing.T) {
	products, articles, distinct := similarProductCount, similarArticleCount, distinctPageCount
	server := similarPagesServer(t, products, articles, distinct)
	defer server.Close()

	const budget = 2
	for _, mode := range []Mode{ModeSimHash, ModeTFIDF, ModeBM25} {
		t.Run(string(mode), func(t *testing.T) {
			idx := newTestIndex(t, Config{
				Mode:            mode,
				HammingDistance: 3,
				ScoreThreshold:  0.85,
				Budget:          budget,
			})
			got := runSimilarSiteCrawl(t, idx, server, products, articles, distinct)
			logCrawlStats(t, mode, budget, got)

			require.Equal(t, budget, got.productAccepted)
			require.Equal(t, products-budget, got.productFiltered)
			require.Equal(t, budget, got.articleAccepted)
			require.Equal(t, articles-budget, got.articleFiltered)
			require.Equal(t, distinct, got.distinctAccepted)
			require.Zero(t, got.distinctFiltered)

			assertIndexStatsMatch(t, idx, got)
			require.Equal(t, int64(2*budget+distinct), idx.Stats().Accepted)
			require.Equal(t, int64(products+articles-2*budget), idx.Stats().Filtered)
		})
	}
}

func TestSimilarPagesServer_DisabledKeepsAllHundreds(t *testing.T) {
	products := similarProductCount
	server := similarPagesServer(t, products, 0, 0)
	defer server.Close()
	client := server.Client()

	var idx *Index
	accepted := 0
	for i := 1; i <= products; i++ {
		body := fetchBody(t, client, fmt.Sprintf("%s/product/%d", server.URL, i))
		if idx.Accept(body) {
			accepted++
		}
	}
	require.Equal(t, products, accepted, "nil index must not skip any of the %d similar pages", products)
}

package similarity

import (
	"hash/fnv"
	"math/bits"
)

// SimHash64 computes a 64-bit Charikar simhash over weighted features.
func SimHash64(features []string) uint64 {
	if len(features) == 0 {
		return 0
	}
	var weights [64]int
	counts := make(map[string]int, len(features))
	for _, f := range features {
		counts[f]++
	}
	for feature, weight := range counts {
		h := hash64(feature)
		for bit := 0; bit < 64; bit++ {
			if (h>>uint(bit))&1 == 1 {
				weights[bit] += weight
			} else {
				weights[bit] -= weight
			}
		}
	}
	var fingerprint uint64
	for bit := 0; bit < 64; bit++ {
		if weights[bit] > 0 {
			fingerprint |= 1 << uint(bit)
		}
	}
	return fingerprint
}

// HammingDistance returns the number of differing bits between two fingerprints.
func HammingDistance(a, b uint64) int {
	return bits.OnesCount64(a ^ b)
}

func hash64(s string) uint64 {
	h := fnv.New64a()
	_, _ = h.Write([]byte(s))
	return h.Sum64()
}

package types

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestNewCrawlerOptionsWithContext(t *testing.T) {
	t.Run("nil context defaults to background", func(t *testing.T) {
		opts := &Options{RateLimit: 10}
		crawlerOpts, err := NewCrawlerOptions(opts)
		require.NoError(t, err)
		defer func() { _ = crawlerOpts.Close() }()
		require.NotNil(t, crawlerOpts.RateLimit)
	})

	t.Run("cancelling context unblocks rate limiter", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		opts := &Options{Context: ctx, RateLimit: 1}
		crawlerOpts, err := NewCrawlerOptions(opts)
		require.NoError(t, err)
		defer func() { _ = crawlerOpts.Close() }()

		crawlerOpts.RateLimit.Take()

		// Ensure the goroutine is blocked on Take() before we cancel.
		ready := make(chan struct{})
		done := make(chan struct{})
		go func() {
			close(ready)
			crawlerOpts.RateLimit.Take()
			close(done)
		}()
		<-ready

		cancel()

		// The rate limiter detects cancellation on its next tick (~1s for
		// RateLimit:1). Use 2s to allow for scheduling jitter.
		select {
		case <-done:
		case <-time.After(2 * time.Second):
			t.Fatal("Take() did not unblock after context cancellation")
		}
	})

	t.Run("Close stops rate limiter goroutine", func(t *testing.T) {
		opts := &Options{RateLimit: 1}
		crawlerOpts, err := NewCrawlerOptions(opts)
		require.NoError(t, err)

		crawlerOpts.RateLimit.Take()

		ready := make(chan struct{})
		done := make(chan struct{})
		go func() {
			close(ready)
			crawlerOpts.RateLimit.Take()
			close(done)
		}()
		<-ready

		require.NoError(t, crawlerOpts.Close())

		select {
		case <-done:
		case <-time.After(2 * time.Second):
			t.Fatal("Take() did not unblock after Close()")
		}
	})
}

